local P = LoreForeverPacks.Begin("LoreForever_Lang_ptBR")
P.entries["zone:razorfenkraul"] = {n="Urzal dos Tuscos",s="Escondido no extremo sul dos Sertões, o Urzal dos Tuscos é o coração ancestral dos javatuscos de Kalimdor. Essas tribos ferozes reverenciam o denso labirinto de espinheiros gigantes como o local de descanso sagrado de seu progenitor, o semideus caído Agamaggan. Hoje, o Urzal tornou-se agressivamente hostil sob a tirania da matriarca javatusco Charlga Talhaflanco, cujos negócios sombrios ameaçam toda a região.",h="Escondido no extremo sul dos Sertões, o Urzal dos Tuscos é o coração ancestral dos javatuscos de Kalimdor.",kw={"agamaggan","sertoes","charlga","halmgar","urzal","javatusco","ramtusk","urzal dos tuscos","talhaflanco","flagelo"},ang={["class:Shaman"]="A geomancia dos javatuscos distorce a terra e os elementos ao redor do sangue de Agamaggan, oferecendo uma visão marcante de poderes xamanistas primais empunhados com intenção selvagem.",["faction:Horde"]="Neutralizar a agressão dentro do Urzal é essencial para proteger carroças de suprimentos e povoados incipientes pelas extensões do sul dos Sertões.",["race:Tauren"]="Os javatuscos há muito disputam as fronteiras de Mulgore, e sua profanação da terra por meio de alianças sombrias torna a purificação do Urzal uma questão vital de defesa tribal.",["race:Undead"]="Boticários da Cidade Baixa têm um interesse aguçado nos reagentes bizarros, no guano de morcego e nos rumores de incursões do Flagelo encontrados dentro das sarças."},sec={{t="O Sangue do Deus Javali",b="Dez mil anos atrás, durante a catastrófica Guerra dos Antigos, o colossal deus selvagem Agamaggan lançou-se na luta contra a Legião Ardente. O grande javali acabou sendo morto em batalha, mas seu sacrifício preservou a vida em Azeroth. As lendas contam que, onde quer que seu sangue tenha se infiltrado na terra, enormes videiras cobertas de espinhos brotaram, formando labirintos densos e defensivos pelas planícies do sul. Os javatuscos, venerando Agamaggan como seu ancestral divino, reivindicaram esses matagais colossais como suas terras sagradas, estabelecendo o maior deles como o Urzal."},{t="A Ambição da Bruxa",b="O Urzal dos Tuscos é governado com presas de ferro pela Bruxa Anciã Charlga Talhaflanco. Sob sua liderança despótica, os javatuscos xamanistas abandonaram suas escaramuças territoriais tradicionais para travar uma guerra agressiva e coordenada contra tribos rivais, rotas comerciais regionais e jovens assentamentos da Horda. Pior ainda, sussurros perturbadores e relatórios de batedores falam de demônios mortos-vivos rondando perto dos espinheiros. Teme-se que Charlga tenha começado a negociar com emissários do temido Flagelo, buscando dominar a necromancia proibida para aumentar a selvageria de sua tribo."}},faq={{q="O que é o Urzal dos Tuscos?",a="O Urzal dos Tuscos é uma antiga rede subterrânea de enormes videiras espinhosas nos Sertões Meridionais. Ele serve como o coração espiritual e a fortaleza da raça dos javatuscos, que consideram o labirinto emaranhado seu lar ancestral.",al={"o que e rfk","explicar urzal dos tuscos","visao geral do urzal"}},{q="Como foram criados os espinhos gigantes?",a="Os enormes espinheiros brotaram da terra há dez mil anos durante a Guerra dos Antigos, surgindo diretamente do sangue derramado pelo semideus javali caído, Agamaggan.",al={"por que ha espinhos gigantes","de onde vieram os espinheiros","espinhos de agamaggan"}},{q="Quem governa o Urzal dos Tuscos?",a="O Urzal é governado por Charlga Talhaflanco, uma implacável bruxa e xamã javatusco que comanda a tribo dos Tuscos e orquestra ataques a aldeias vizinhas e viajantes.",al={"quem e o chefe do rfk","charlga talhaflanco","bruxa do urzal"}},{q="Por que a Horda está preocupada com o Urzal dos Tuscos?",a="Além dos constantes ataques de javatuscos a povoados recém-nascidos nos Sertões, batedores da Horda avistaram mortos-vivos espreitando ao redor dos matagais, levantando preocupações aterrorizantes de que Charlga esteja se aliando ao Flagelo.",al={"por que a horda se importa","interesse da horda no rfk","ameaca dos sertoes"}},{q="Por que as forças da Aliança têm interesse no Urzal?",a="A expansão agressiva da tribo de Charlga ameaça entrepostos perto de Feralas e das Mil Agulhas, levando comandantes e batedores da Aliança em Thalanaar a buscar a morte da bruxa para estabilizar a fronteira.",al={"missoes da alianca no rfk","por que a alianca vem aqui","missao de thalanaar"}},{q="O que significa derrotar o Clamaterrestre Halmgar para a história?",a="Derrotar o Clamaterrestre Halmgar, um geomante raro e influente nas profundezas dos matagais, desferiu um golpe contra o sacerdócio moldador da terra dos javatuscos. Destituir o Urzal de tais poderosos invocadores elementais abala as fortificações defensivas de Charlga Talhaflanco e prejudica a capacidade dos javatuscos de manipular os espinheiros sagrados de Agamaggan.",al={"o que acontece apos a morte do clamaterrestre halmgar","historia do clamaterrestre halmgar","halmgar derrotado"}}},fx={["7583b13a"]={q="Quem são os Cabeça-da-Morte?",a="Os Cabeça-da-Morte são uma facção militante de quilboars liderada no campo de batalha pelo Lorde Supremo Marretusco, que opera ao lado da tribo Urzal. Marretusco comanda suas tropas disciplinadas e endurecidas pela batalha para manter um domínio absoluto sobre o labirinto de espinhos e travar guerras cruéis contra seus vizinhos.",al={"tribo cabeça-da-morte","quem são os cabeça-da-morte","quilboars cabeça-da-morte"}},["4bc36485"]={q="Os quilboars aqui vão atacar os assentamentos dos Sertões?",a="Eles já estão atacando. Sob o comando da Anciã Charlga Talhaflanco, grupos de ataque agressivos varrem constantemente os espinhos em direção às terras vizinhas. Eles importunam viajantes perto do Grande Elevador, assaltam tribos rivais e levaram os assentamentos e caravanas da Horda à beira de uma guerra aberta.",al={"quilboars atacarão os sertões","sertões sob ataque de quilboars","ataques quilboars sertões"}},ed4c33ec={q="Qual é a diferença entre o Urzal e o Urzal dos Mortos?",a="Ambos são redes maciças de espinhos que surgiram da queda de Agamaggan, mas servem a propósitos diferentes. O Urzal dos Tuscos é o coração ancestral onde Charlga Talhaflanco reúne invasores quilboars vivos. O Urzal dos Mortos, localizado mais a sudeste perto da enorme boca esquelética do semideus, caiu sob a influência mais sombria do Flagelo.",al={"diferença entre urzal e urzal dos mortos","urzal dos tuscos vs urzal dos mortos","urzal ou urzal dos mortos"}},["974f5634"]={q="O Flagelo está envolvido no Urzal?",a="Sim. Relatos perturbadores e cartas interceptadas revelam que Charlga Talhaflanco começou a negociar com agentes do Flagelo. Batedores avistaram mortos-vivos invadindo as proximidades do Urzal, levantando preocupações graves de que os lacaios do Lich Rei buscam uma base em Kalimdor através dessas tribos desavisadas.",al={"flagelo no urzal","há mortos-vivos no urzal","presença do flagelo no urzal"}},a384c7af={q="Quem é Amnennar?",a="Amnennar o Portador do Frio é um poderoso agente do Flagelo que se estabeleceu no vizinho Urzal dos Mortos. Trabalhando nos bastidores, ele manipula a liderança quilboar e comanda as forças Cabeça-da-Morte para transformar os espinhais do sul em uma fortaleza morta-viva.",al={"quem é amnennar","amnennar o portador do frio","história de amnennar"}},af015f4e={q="Como eu vim parar no Urzal dos Tuscos?",a="Você viajou para as extremidades mais ao sul dos Sertões, perto dos penhascos imponentes com vista para Mil Agulhas. Atravessando as matas arbustivas disputadas, você encontrou o imenso emaranhado de espinhos nutridos por sangue que brotaram do cadáver do antigo deus javali Agamaggan. Esculpida diretamente nessas vinhas de espinhos petrificadas e maciças está a entrada ocidental do Urzal, onde defensores quilboars guardam a aproximação contra qualquer um que ouse invadir seu território sagrado.",al={"como cheguei aqui","como chegar ao urzal dos tuscos","onde fica o urzal dos tuscos"}},["141f6ea5"]={q="O que devo fazer no Urzal dos Tuscos?",a="Você está aqui para quebrar o poder hostil da tribo Urzal e deter sua expansão agressiva pelos Sertões. Sob a orientação de sua anciã, Charlga Talhaflanco, esses quilboars fanáticos intensificaram os assaltos violentos a assentamentos e caravanas vizinhas. Seu objetivo é lutar através das passagens sinuosas de espinhos, despedaçar a liderança Cabeça-da-Morte e abater Charlga antes que sua geomancia sombria e suas suspeitas negociações com forças mortas-vivas sinistras iniciem uma guerra total.",al={"qual é minha missão aqui","por que estou no urzal dos tuscos","o que estou fazendo aqui"}},["59c8bcc4"]={q="Quem construiu todos esses espinhos no Urzal dos Tuscos?",a="Ninguém os construiu manualmente. Dez mil anos atrás, durante a Guerra dos Antigos, o colossal semideus javali Agamaggan caiu lutando contra a Legião Ardente. Onde seu sangue divino embebeu o solo, sarças massivas e impenetráveis cobertas de espinhos irromperam da terra, formando o emaranhado labiríntico que você vê hoje.",al={"quem criou os espinhos","quem construiu os espinhos","origem dos espinhos no urzal dos tuscos"}},["4843f165"]={q="O que são quilboar?",a="Quilboar são humanoides primitivos e agressivos semelhantes a javalis, nativos de Kalimdor. Eles têm costas musculosas e curvadas, eriçadas com espinhos afiados e defensivos. Acredita-se que sejam a descendência mortal do semideus Agamaggan, eles reverenciam seus locais de descanso e defendem ferozmente seus territórios espinhosos contra quaisquer estranhos.",al={"o que são quilboar","quem são os quilboar","história dos quilboar"}},ea4583b3={q="Por que os quilboar vivem em um labirinto de espinhos gigante?",a="O labirinto de espinhos brotou diretamente do sangue de seu deus caído, Agamaggan. Para os quilboar, o Urzal dos Tuscos é um solo sagrado e seu verdadeiro local de descanso. As sarças proporcionam a eles tanto reverência sagrada quanto fortalezas naturais, quase impenetráveis, contra seus inimigos regionais.",al={"por que viver em espinhos","por que os quilboar vivem aqui","labirinto de espinhos quilboar"}},b1fd1d2b={q="Charlga Talhaflanco é a líder de todos os quilboar?",a="Não de todos os quilboar, mas ela governa a poderosa tribo do Urzal dos Tuscos entrincheirada no local. Uma bruxa astuta e geomante, ela expulsou os tauren locais dos Sertões Meridionais e comanda uma autoridade ampla, embora tribos quilboar rivais espalhadas por Kalimdor governem a si mesmas independentemente.",al={"liderança de charlga talhaflanco","quem lidera todos os quilboar","charlga está no comando de todos"}},["8ed48c28"]={q="Quem é Agathelos, o Furioso?",a="Agathelos é um javali massivo e feroz que habita o Urzal dos Tuscos. Os quilboar reverenciam javalis como símbolos vivos de seu deus Agamaggan, vendo bestas particularmente grandes e tenazes como Agathelos como bênçãos diretas e manifestações sagradas do poder primal do Grande Javali.",al={"quem é agathelos","história de agathelos, o furioso","javali gigante agathelos"}},["4f663063"]={q="A Horda também está bisbilhotando o Urzal dos Tuscos?",a="Sim. Os saqueadores de Charlga Talhaflanco encenam continuamente ataques brutais aos assentamentos da Horda por todos os Sertões e expulsaram os tauren de suas cordilheiras ancestrais do sul. Tanto os orcs quanto os tauren estão despachando ativamente guerreiros para quebrar o poder da bruxa e acabar com a ameaça quilboar.",al={"a horda está aqui","presença da horda no urzal dos tuscos","horda no urzal dos tuscos"}},["5328604f"]={q="Quem é Agamaggan?",a="Agamaggan, o Grande Javali, era um Guardião Ancestral e um dos primeiros e mais poderosos Deuses Selvagens a caminhar em Azeroth. Reverenciando-o como seu criador, os quilboar cultuam sua memória, extraindo poder espiritual e geomântico de seu sangue e dos vastos aglomerados de espinhos nascidos de seu sacrifício.",al={"quem é agamaggan","agamaggan, o grande javali","história de agamaggan"}},bc4e6730={q="Agamaggan morreu na Guerra dos Antigos?",a="Sim. Dez mil anos atrás, Agamaggan atendeu ao chamado de Cenarius para defender Azeroth da Legião Ardente. Ele enfureceu-se pelo continente, esmagando milhares de demônios antes de finalmente cair em batalha contra legiões demoníacas avassaladoras, sacrificando sua vida para que Malfurion Tempesfúria pudesse alcançar a Nascente da Eternidade.",al={"como agamaggan morreu","agamaggan e a guerra dos antigos","agamaggan morreu"}},e47b7687={q="Os quilboar ainda adoram Agamaggan?",a="Eles o fazem, com devoção fanática. Xamãs e geomantes quilboar rezam para Agamaggan por força na batalha, veneram javalis gigantes como suas bênçãos e acumulam Estilhaços de Sangue formados a partir de seu sangue petrificado. Eles acreditam que seus restos físicos protegem a eles e ao seu lar sagrado.",al={"os quilboar ainda adoram agamaggan","religião quilboar","adoração a agamaggan"}}},fp="14,218,21.427.0,20.423.1,23.142.0,34.156.0,25.170.0,48.182.0,48.157.0,59.248.0"}
P.entries["zone:redridge"] = {n="Montanhas Cristarrubra",s="A leste da Floresta de Elwynn, as Montanhas Cristarrubra apresentam rios velozes, encostas arborizadas e a extensão serena do Lago Plácido. Apesar de suas alturas cênicas, a região está cercada por hostis gnolls Shadowhide e pelos orcs Rocha Negra da Horda Sombria que avançam sobre ela. Com as forças armadas do reino ocupadas por conflitos internos em Ventobravo, a cidade à beira do lago, Vila Plácida, precisa depender de mercenários errantes para manter a linha de defesa.",h="A leste da Floresta de Elwynn, as Montanhas Cristarrubra apresentam rios velozes, encostas arborizadas e a...",kw={"orcs rocha negra","lago plácido","vila plácida","magistrado salomão","oficial marris","montanhas cristarrubra","vale dos laceradores","shadowhide","mirante de pedra","bastilha mirante de pedra","vervo obom"},ang={["faction:Alliance"]="Vila Plácida serve como um entreposto crítico de linha de frente para jovens soldados da Aliança aprimorarem suas habilidades contra forças organizadas de orcs e gnolls.",["faction:Horde"]="Os orcs Rocha Negra entrincheirados em Montanhas Cristarrubra pertencem à hostil Horda Sombria, tornando-os inimigos da Horda de Thrall tanto quanto dos humanos em Vila Plácida.",["profession:Herbalism"]="As encostas temperadas da montanha favorecem o crescimento constante de Cravespinho, Ervamossa, Magi-real e Cardo-veloz.",["profession:Mining"]="Os penhascos rochosos e os vales ao redor do Lago Plácido oferecem afloramentos abundantes de cobre, estanho e veios raros de prata, especialmente perto das Cavernas Retibanas."},sec={{t="Um Bastião Sob Cerco",b="A cordilheira de Montanhas Cristarrubra já foi um dos cantos mais pacíficos do reino, abastecendo Ventobravo com madeira, peixes de água doce e colheitas. Hoje, essa vida tranquila se desfez. O vilarejo à beira do lago, Vila Plácida, encontra-se perpetuamente fortificado contra incursões agressivas. A leste, a Bastilha Mirante de Pedra — outrora um orgulhoso bastião do reino — caiu sob o controle de orcs Rocha Negra renegados, cortando estradas e ameaçando tomar completamente os vales orientais."},{t="A Cordilheira Dividida",b="Geograficamente, esses picos formam parte da espinha dorsal que percorre o subcontinente de Azeroth. Séculos atrás, a cadeia de montanhas se estendia muito mais ao norte, até que o clã Ferro Negro inadvertidamente invocou o Senhor do Fogo Ragnaros, fendendo a terra e criando a cratera ardente da Montanha Rocha Negra. Esse cataclismo separou os picos do norte nas Estepes Ardentes cobertas de cinzas, deixando apenas os vales do sul de Montanhas Cristarrubra exuberantes, verdes e vulneráveis a ataques que descem das encostas acima."},{t="Negligenciada pela Coroa",b="Enquanto o Magistrado Salomão e o Oficial Marris clamam por reforços, o conselho de regência em Ventobravo efetivamente abandonou Vila Plácida à própria sorte. Apelos desesperados enviados ao Morro da Sentinela e a Vila Sombria nada resultam, pois ambos os povoados irmãos estão paralisados por suas próprias crises. Sem reforços à vista, os magistrados locais precisam contratar qualquer mercenário capaz disposto a desafiar a Estrada Beira-lago, limpar os acampamentos de gnolls e repelir a sombra que paira sobre o Lago Plácido."},{t="As Alianças Ocultas",b="O ladino bruxo Morganth inicialmente se aliou aos orcs Rocha Negra para tomar a Bastilha Mirante de Pedra, depois os traiu e submeteu os gnolls Shadowhide ao seu serviço a partir da Torre de Ilgalar. Relatórios recuperados durante a investigação sobre os Rocha Negra também revelam uma aliança entre os orcs e a revoada dragônica negra."}},faq={{q="Por que Ventobravo não envia soldados para ajudar Vila Plácida?",a="Os soldados reais sobreviventes de Vila Plácida estão em grande desvantagem numérica após perderem a Bastilha Mirante de Pedra. O Magistrado Salomão pediu tropas, armas, comida e suprimentos, mas as forças de Ventobravo estão sobrecarregadas e os povoados vizinhos enfrentam seus próprios problemas. A guarnição, portanto, depende de aventureiros para ajudar a manter a região.",al={"por que não há guardas de ventobravo","por que montanhas cristarrubra está abandonada","onde está o exército de ventobravo"}},{q="Quem controla a Bastilha Mirante de Pedra?",a="A Bastilha Mirante de Pedra foi tomada por orcs Rocha Negra afiliados à Horda Sombria. A partir dessa fortaleza fortificada nas montanhas, eles ameaçam os vales orientais e transitam pela Estrada Beira-lago. Suas relações com outras ameaças locais são exploradas durante a investigação.",al={"quem está em mirante de pedra","inimigos de mirante de pedra","o que aconteceu com mirante de pedra"}},{q="Quais ameaças habitam o Lago Plácido?",a="Embora tranquilo a partir da margem, as águas do Lago Plácido estão infestadas de tribos hostis de murlocs que atacam as docas e ruínas próximas. Os nadadores também devem lidar com predadores trissadons à espreita sob a superfície, dando origem a rumores persistentes de monstros aquáticos rondando as profundezas.",al={"monstros do lago plácido","perigos do lago de montanhas cristarrubra","murlocs do lago plácido"}},{q="Existe algum posto avançado da Horda em Montanhas Cristarrubra?",a="Não. As Montanhas Cristarrubra não contêm povoados, comerciantes ou pontos de voo da Horda. Viajantes da Horda que passam pela zona geralmente estão em trânsito entre as Estepes Ardentes ao norte e o Pântano das Mágoas ao sudeste, tendo que percorrer estradas mantidas pela Aliança e terras ermas hostis.",al={"cidades da horda em montanhas cristarrubra","montanhas cristarrubra é da horda ou da aliança","ponto de voo da horda em montanhas cristarrubra"}},{q="O que é Três Caminhos?",a="Três Caminhos é uma encruzilhada vital no canto sudoeste de Montanhas Cristarrubra. Ela conecta a Estrada Beira-lago com a fronteira oriental da Floresta de Elwynn e a estrada para a Floresta do Crepúsculo, tornando-se um ponto de trânsito essencial frequentemente visado por gnolls errantes e feras selvagens.",al={"três caminhos","encruzilhada três caminhos","cruzamento de montanhas cristarrubra"}},{q="Por que o caminho ao norte para as Estepes Ardentes é tão perigoso?",a="A trilha que segue para o norte passando pelo Acampamento de Render sobe diretamente para as Estepes Ardentes, um ermo vulcânico desolado dominado por poderosos orcs Rocha Negra, elementais do fogo e draconídeos. A súbita mudança no perigo faz da passagem montanhosa ao norte uma das subidas geográficas mais mortais do sul de Azeroth.",al={"estrada norte de montanhas cristarrubra","fronteira de estepes ardentes e montanhas cristarrubra","passagem norte de montanhas cristarrubra"}}},fx={["85c0e73f"]={q="O que são as Montanhas Cristarrubra?",a="As Montanhas Cristarrubra são uma região elevada e pitoresca a leste da Floresta de Elwynn e ao sul das Estepes Ardentes. Conhecida por seus rios caudalosos, olmos imponentes e o cintilante Lago Plácido, foi considerada por muito tempo uma das terras mais pacíficas no sul de Azeroth. Hoje, sua beleza tranquila é destruída pelos orcs da Rocha Negra invasores, gnolls violentos e murlocs hostis do lago.",al={"o que são as montanhas cristarrubra","zona montanhas cristarrubra","fale-me sobre as montanhas cristarrubra"}},["5d244582"]={q="As Montanhas Cristarrubra fazem parte do reino de Ventobravo?",a="Sim, as Montanhas Cristarrubra estão sob a proteção e domínio do reino de Ventobravo, embora, desde a Segunda Guerra, seus líderes locais tenham governado os assuntos cotidianos em grande parte de forma independente. O Magistrado Salomão de Vila Plácida ainda peticiona formalmente ao trono de Ventobravo por defesa, contando com o comércio da Aliança e a lealdade mútua, mesmo quando as tropas reais não estão à vista.",al={"as montanhas cristarrubra pertencem a ventobravo","montanhas cristarrubra aliança","vila plácida faz parte de ventobravo"}},["8563150d"]={q="Por que existe um lago no meio das Montanhas Cristarrubra?",a="O Lago Plácido reúne naturalmente a drenagem das cadeias de montanhas circundantes. Suas águas claras e serenas já sustentaram Vila Plácida com peixes abundantes e água limpa, embora ultimamente tenha sido invadido por tribos cruéis de murlocs e espreitado por bestas de barbatana sob a superfície.",al={"por que o lago plácido","origem do lago das montanhas cristarrubra","qual é o lago nas montanhas cristarrubra"}},["8de34bfa"]={q="O que aconteceu nas Montanhas Cristarrubra?",a="As Montanhas Cristarrubra já foram um berço tranquilo de fazendas humanas até a Primeira Guerra, quando o Chefe Guerreiro Mão Negra e os bruxos do Conselho das Sombras derrotaram os cavaleiros de Sir Anduin Lothar e forçaram os humanos ao exílio. Reclamada e reconstruída pela Aliança após a Segunda Guerra, a região caiu recentemente sob cerco mais uma vez depois que orcs da Rocha Negra desceram das montanhas e tomaram a Bastilha Mirante de Pedra.",al={"história das montanhas cristarrubra","o que aconteceu nas montanhas cristarrubra","primeira guerra montanhas cristarrubra"}},bf444872={q="As Montanhas Cristarrubra são perigosas?",a="Apesar de sua aparência idílica, as Montanhas Cristarrubra são extraordinariamente perigosas. Orcs da Rocha Negra controlam os desfiladeiros orientais e a bastilha, gnolls Pele-Sombria atacam os bosques e murlocs enxameiam as margens do lago. Até a estrada do norte faz fronteira com os picos escaldantes das Estepes Ardentes, onde ameaças monstruosas muito além de uma patrulha comum espreitam logo após as passagens do vale.",al={"as montanhas cristarrubra são seguras","nível de perigo montanhas cristarrubra","quão perigosas são as montanhas cristarrubra"}},["1cc45818"]={q="Por que todos em Vila Plácida estão tão preocupados?",a="Vila Plácida está em um estado ativo de cerco. Os orcs da Rocha Negra capturaram a Bastilha Mirante de Pedra do outro lado do lago, gnolls Pele-Sombria pressionam a cidade a partir das colinas e murlocs infestam as hidrovias. Com a ponte quebrada e nenhum reforço chegando de Ventobravo, os habitantes temem que um ataque total os extermine a qualquer momento.",al={"por que vila plácida está com medo","ameaça a vila plácida","por que se preocupar em vila plácida"}},["851f5e81"]={q="Vila Plácida está prestes a cair?",a="Sem intervenção externa, a posição de Vila Plácida é sombria. A guarda da cidade local é amplamente superada em número por invasores orcs, bandos de gnolls e monstros do lago. Sua fortaleza em Mirante de Pedra foi facilmente invadida, e os defensores de Vila Plácida foram empurrados de volta para a margem oeste do lago, mal mantendo um perímetro ao longo da ponte quebrada.",al={"vila plácida vai cair","vila plácida está condenada","vila plácida pode sobreviver"}},["7ced12b0"]={q="Ventobravo enviou alguma ajuda para Vila Plácida?",a="Vila Plácida apelou a Ventobravo, Cerro Oeste e Vila Sombria por ajuda, mas os assentamentos vizinhos estão consumidos por suas próprias crises. O General Marcus Jonas também foi solicitado por reforços. Os soldados reais que ainda defendem Vila Plácida permanecem com falta de tropas e suprimentos após a queda da Bastilha Mirante de Pedra.",al={"ventobravo ajudou vila plácida","ajuda de ventobravo a vila plácida","ventobravo enviou tropas para as montanhas cristarrubra"}},["3a3ab87f"]={q="Quem está no comando por aqui?",a="Vila Plácida é governada pelo Magistrado Salomão, que supervisiona questões civis e os assuntos da cidade a partir da Prefeitura de Vila Plácida. As operações militares e de defesa cabem ao Oficial Marris, que direciona a guarda local e coordena os esforços defensivos perto da ponte.",al={"quem lidera as montanhas cristarrubra","quem governa vila plácida","líderes das montanhas cristarrubra"}},["1dd15680"]={q="Quem é o Magistrado Salomão?",a="O Magistrado Salomão é o governante eleito de Vila Plácida e juiz chefe do Tribunal de Vila Plácida. Envelhecido e exausto, ele carrega o fardo de manter a cidade alimentada, organizada e politicamente conectada ao reino, enquanto peticiona desesperadamente a líderes estrangeiros e regionais por alívio militar.",al={"magistrado salomão","quem é salomão","salomão montanhas cristarrubra"}},["0e63cf14"]={q="O Oficial Marris responde ao Magistrado Salomão?",a="Sim. Salomão representa a autoridade civil e o tribunal do reino em Vila Plácida, enquanto o Oficial Marris comanda o destacamento da Guarda de Ventobravo estacionado lá. Os dois trabalham juntos em estreita parceria, com Salomão gerenciando a sobrevivência diplomática e municipal, enquanto Marris cuida de escaramuças táticas e destacamentos de tropas.",al={"marris se reporta a salomão","posto oficial marris salomão","quem tem patente maior em vila plácida"}},["7b7fd7c0"]={q="Quem são os orcs da Rocha Negra e por que estão nas Montanhas Cristarrubra?",a="O clã Rocha Negra é um remanescente implacável da Antiga Horda baseado na Montanha Rocha Negra ao norte. Diferente da Horda de Thrall em Kalimdor, esses renegados rejeitam qualquer paz com a Aliança. Eles desceram das Estepes Ardentes para as Montanhas Cristarrubra buscando conquistar a região, usando a Bastilha Mirante de Pedra como base para esmagar Vila Plácida.",al={"orcs da rocha negra montanhas cristarrubra","por que há orcs nas montanhas cristarrubra","quem são o clã rocha negra nas montanhas cristarrubra"}},["114fb915"]={q="De onde vieram os orcs da Rocha Negra?",a="Eles marcharam para o sul através das passagens serradas das montanhas do norte diretamente das Estepes Ardentes e do Pico da Rocha Negra, sua antiga fortaleza da Segunda Guerra. Eles estabeleceram postos avançados como o Acampamento do Render antes de dominar a Bastilha Mirante de Pedra.",al={"de onde vieram os orcs das montanhas cristarrubra","origem dos orcs da rocha negra","de onde estão vindo os orcs"}},["9f02e3ae"]={q="Os orcs Rocha Negra são os mesmos orcs das guerras?",a="Sim. Eles são veteranos endurecidos e descendentes diretos do clã Rocha Negra da Primeira e Segunda Guerra, que se recusaram a se render ou a seguir o novo caminho xamânico de Thrall. Eles mantêm suas práticas sanguinárias originais e magia das trevas, apegando-se firmemente à sua missão original de extinguir os reinos humanos.",al={"orcs rocha negra da primeira guerra","orcs rocha negra da segunda guerra","são os mesmos orcs das guerras antigas"}},["09fb7c4a"]={q="O que são os gnolls das Montanhas Cristarrubra? Por que estão atacando?",a="Os gnolls Pelo-Sombrio locais são humanoides selvagens, semelhantes a hienas, que habitam as colinas e vales de Montanhas Cristarrubra. Embora sejam naturalmente territoriais e predadores, sua violência coordenada atual é impulsionada por influências sombrias que unificaram suas matilhas dispersas em um exército organizado determinado a massacrar assentamentos humanos.",al={"gnolls de montanhas cristarrubra","por que gnolls atacam montanhas cristarrubra","gnolls pelo-sombrio"}},ba7471d2={q="Os gnolls estão trabalhando com os orcs?",a="Os gnolls Pelo-Sombrio servem ao bruxo ladino Morganth na Torre de Ilgalar. A relação deles com os orcs Rocha Negra pode ser investigada através de relatórios recuperados na região.",al={"gnolls e orcs aliados","gnolls trabalham para os rocha negra","orcs e gnolls se unindo"}},["74e139ea"]={q="Quem é Uivador?",a="Uivador é o líder dos gnolls de Montanhas Cristarrubra. Residindo nas colinas acima de Vila Plácida, ele reúne a matilha contra a cidade. Vervo Obom pede aos aventureiros que o derrotem e tragam sua pata de volta.",al={"quem é uivador","líder gnoll uivador","uivador montanhas cristarrubra"}},b25dfaa0={q="Por que a ponte do Lago Plácido está destruída, e por que isso importa?",a="A ponte do Lago Plácido está muito danificada. Ela é importantíssima porque atravessa o gargalo estreito do Lago Plácido, servindo como a principal ligação de transporte de Vila Plácida para a margem leste e para a Bastilha Mirante de Pedra. Sua destruição prejudica o comércio e a defesa da cidade, além de complicar qualquer contra-ataque contra acampamentos inimigos.",al={"ponte do Lago Plácido destruída","por que a ponte de Vila Plácida está quebrada","ponte destruída nas Montanhas Cristarrubra"}},b35f81a4={q="Por que Ventobravo ainda não reparou a ponte do Lago Plácido?",a="Ventobravo não enviou verbas, suprimentos ou pedreiros para ajudar. A responsabilidade recaiu inteiramente sobre os trabalhadores locais liderados pelo Encarregado Oslow, cujos esforços de reparo são constantemente interrompidos e sabotados por ataques de murlocs e perdas de suprimentos.",al={"por que a ponte não foi consertada","conserto da ponte de ventobravo em vila plácida","quem está consertando a ponte"}},["834d2ea2"]={q="Por que há filhotes de dragão negro em Montanhas Cristarrubra?",a="Filhotes de dragão negro se espalharam pelas passagens vindos dos Estepes Ardentes, infestando a Estrada Beira-lago e os desfiladeiros do sul. Eles rondam as cristas rochosas, vigiando o território e atacando transeuntes, servindo como um aviso sinistro de que a ninhada de Deathwing está ativa nas proximidades.",al={"filhotes de dragão em montanhas cristarrubra","dragões negros montanhas cristarrubra","por que filhotes em montanhas cristarrubra"}},ce7dd1a7={q="Os dragões estão trabalhando com os orcs?",a="A crescente presença dos Rocha Negra e os avistamentos de filhotes de dragão negro alarmam Vila Plácida. O Magistrado Salomão pede aos viajantes que levem suas preocupações ao Grão-lorde Bolvar Fordragon. Investigações adicionais revelam a natureza da ameaça.",al={"dragões negros aliados com rocha negra","aliança de orcs e dragões","orcs rocha negra trabalham com dragões"}},["7d7bd3f8"]={q="Por que um aventureiro está fazendo todo o combate aqui em vez dos guardas?",a="Os guardas de Vila Plácida estão totalmente acuados defendendo o perímetro da cidade, não sobrando ninguém para surtidas ofensivas. Com os reforços solicitados ainda indisponíveis, o Magistrado Salomão e o Oficial Marris não têm escolha a não ser contratar aventureiros viajantes para repelir os orcs, eliminar os gnolls e proteger a estrada.",al={"por que estou fazendo isso em montanhas cristarrubra","por que aventureiros em montanhas cristarrubra","onde estão os guardas de montanhas cristarrubra"}},["839c7682"]={q="Onde está o exército de Ventobravo?",a="As forças de Ventobravo estão sobrecarregadas. Soldados reais permanecem em Vila Plácida após a derrota na Bastilha Mirante de Pedra, mas os repetidos pedidos da cidade por tropas frescas e suprimentos não trouxeram os reforços de que seus defensores precisam.",al={"onde estão os soldados de ventobravo","por que não há exército de ventobravo","localização do exército de ventobravo"}},de572e98={q="Como vim parar em Montanhas Cristarrubra?",a="Você provavelmente seguiu as estradas para o leste da Floresta de Elwynn através da encruzilhada de Três Caminhos, ou atravessou o rio vindo dos bosques sombrios da Floresta do Crepúsculo, a sudoeste. Como um campeão iniciante auxiliando as terras humanas, suas viagens naturalmente o levam até aqui assim que os problemas nas periferias de Ventobravo exigem mãos mais firmes. Os pedidos de ajuda de Vila Plácida alcançam os territórios vizinhos, atraindo aventureiros viajantes pela Estrada Beira-lago até essas alturas em conflito.",al={"como vim parar aqui","como cheguei em montanhas cristarrubra","por que vim para montanhas cristarrubra"}},d1ce2561={q="O que devo estar fazendo em Montanhas Cristarrubra?",a="Vila Plácida está em situação desesperadora e virtualmente abandonada pela coroa. Você está aqui para atender aos apelos de defesa do Magistrado Salomão e do Oficial Marris. A cidade está sob pressão constante de gnolls Pelo-Sombrio saqueadores ao longo das estradas e de ferozes orcs Rocha Negra que tomaram a Bastilha Mirante de Pedra. Com a guarnição real em menor número e a ponte do Lago Plácido destruída, você deve repelir os gnolls, rechaçar a vanguarda dos orcs e impedir que este refúgio tranquilo à beira do lago entre em colapso total.",al={"o que estou fazendo aqui","por que estou aqui","qual é meu objetivo em montanhas cristarrubra","qual é minha missão aqui"}}},fp="18,271,21.379.0,17.453.0,22.430.0,22.309.1,52.324.0,29.235.0,37.186.0,41.258.0,26.229.0,60.279.0"}
P.entries["zone:riverglades"] = {n="Sendas do Rio",s="As Sendas do Rio são um vale fluvial disputado a leste das Estepes Ardentes e dos Ermos, historicamente reivindicado pelo Reino de Ventobravo. Invadida pela Horda Antiga durante a Primeira Guerra e praticamente abandonada pela coroa, a região continua sendo um campo de batalha à medida que lealistas humanos locais enfrentam postos avançados da Horda moderna e a fauna local. Faz fronteira com as Montanhas Cristarrubra a sudoeste, com o Pântano das Mágoas ao sul, e fica de frente para Tanaris do outro lado do mar.",h="As Sendas do Rio são um vale fluvial disputado a leste das Estepes Ardentes e dos Ermos, historicamente...",kw={"estreito rocha negra","irmandade do cavalo","demar brant","bastilha de ermoforte","fortaleza de krol'dok","porto detonapavio","redridge pass","sendas do rio","rog'mar","solclaro"},ang={["faction:Alliance"]="Soldados da Aliança encontram velhas feridas expostas nas Sendas do Rio, onde remanescentes da Irmandade do Cavalo continuam uma cruzada esquecida para retomar terras que Ventobravo abandonou durante a Primeira Guerra.",["faction:Horde"]="Para a Horda, estabelecer postos avançados como Rog'mar garante uma posição costeira segura e mantém a pressão sobre antigos redutos humanos que resistem a leste de Cristarrubra.",["race:Human"]="Viajantes humanos testemunham um capítulo trágico de sua própria história em Solclaro, uma lembrança do pesado tributo cobrado pela Primeira Guerra na fronteira oriental de seu reino."},sec={{t="Uma Fronteira Esquecida",b="Historicamente parte do Reino de Ventobravo, as Sendas do Rio caíram em ruínas durante a Primeira Guerra, quando a Horda Antiga assolou a região. Seu principal assentamento, Solclaro, foi saqueado pelos orcs, que pouparam sua torre de magos unicamente para estudar a feitiçaria humana antes de escravizarem os habitantes sobreviventes. Embora soldados de Ventobravo tenham organizado esforços para libertar os prisioneiros e reconstruir a cidade, o reino acabou considerando todo o vale perdido e desviou recursos para defender o coração de suas terras natais. Por anos, a região permaneceu amplamente sem o apoio formal da coroa."},{t="A Luta por Ermoforte",b="Apesar de terem sido deixados para trás pelos altos escalões de Ventobravo, os defensores humanos nunca entregaram totalmente sua terra natal. Sob o comando do Cavaleiro-comandante Demar Brant, da lendária Irmandade do Cavalo, os lealistas remanescentes mantêm a Bastilha de Ermoforte como um baluarte contra a natureza implacável e invasores hostis. Enquanto isso, a Horda moderna mantém uma presença formidável nas proximidades, em postos como Rog'mar e Bolder'ok, garantindo que o antigo conflito pelas sendas continue a arder."},{t="Geografia e Deslocamento",b="Estendendo-se ao longo da costa do Forbidding Sea, as Sendas do Rio são ladeadas por relevo montanhoso e cursos d'água sinuosos. Viajantes a pé podem cruzar a oeste pelo Estreito Rocha Negra até as Estepes Ardentes, seguir a sudoeste pelo Redridge Pass em direção às Montanhas Cristarrubra, navegar para o sul adentrando o Pântano das Mágoas ou caminhar para o noroeste, passando pela Mortalha do Crepúsculo, até os Ermos. Na costa, o Porto Detonapavio oferece uma rota marítima conectando-se diretamente através do oceano ao Porto de Bondebico, em Tanaris."}},faq={{q="O que são as Sendas do Rio?",a="As Sendas do Rio são uma região disputada situada a leste dos Ermos e das Estepes Ardentes, de frente para o Forbidding Sea. Outrora um território próspero de Ventobravo, agora é uma fronteira ativa disputada pela Aliança na Bastilha de Ermoforte e pela Horda em Rog'mar.",al={"visão geral de sendas do rio","o que é esta zona","sobre sendas do rio"}},{q="O que aconteceu com Solclaro?",a="Solclaro foi atacada e destruída pela Horda Antiga durante a Primeira Guerra. Os orcs escravizaram os aldeões sobreviventes e mantiveram uma torre de magos local intacta para decifrar a magia humana. Embora os soldados de Ventobravo tenham libertado os cativos e tentado reconstruir o local, o reino acabou abandonando a área para se concentrar em suas fronteiras ocidentais.",al={"história de solclaro","queda de solclaro","o que aconteceu com a cidade"}},{q="Quem controla a Bastilha de Ermoforte?",a="A Bastilha de Ermoforte é controlada por lealistas da Aliança sob a liderança do Cavaleiro-comandante Demar Brant, da Irmandade do Cavalo. Suas forças passaram anos lutando para retomar as Sendas do Rio depois que Ventobravo inicialmente deu o território como perdido.",al={"quem lidera ermoforte","aliança em sendas do rio","irmandade do cavalo"}},{q="Como chegar a Tanaris a partir das Sendas do Rio?",a="Um barco costeiro faz viagens regulares entre o Porto Detonapavio, na costa leste das Sendas do Rio, e o Porto de Bondebico, em Tanaris, oferecendo uma conexão naval direta pelo mar.",al={"barco para tanaris","barco do porto detonapavio","como chegar a tanaris"}},{q="Quais passagens levam a outras zonas?",a="Você pode viajar para o sudoeste através do Redridge Pass para chegar às Montanhas Cristarrubra, ou seguir diretamente para o sul em direção ao Pântano das Mágoas. A oeste, o Estreito Rocha Negra passa pelas Colinas Cerdosas até as Estepes Ardentes, enquanto as trilhas ao norte da Mortalha do Crepúsculo seguem direto para os Ermos.",al={"como chegar a cristarrubra","passagens a partir de sendas do rio","saídas de sendas do rio"}},{q="O que é a Fortaleza de Krol'Dok?",a="A Fortaleza de Krol'Dok é um complexo fortificado de masmorra nas Sendas do Rio, representando um grande centro de poder hostil no território disputado.",al={"fortaleza de krol'dok","masmorra de sendas do rio","qual masmorra fica aqui"}}},fp="11,291,22.431.0,25.415.0,20.414.0,24.187.0,28.295.0,27.212.0,46.146.0,34.266.0,28.127.0"}
P.entries["zone:ruinsoflordaeron"] = {n="Ruínas de Lordaeron",s="Empoleiradas diretamente acima da subterrânea Cidade Baixa, as Ruínas de Lordaeron são os restos desolados do reino humano outrora grandioso do norte. Tendo caído diante do Flagelo e do Príncipe Arthas durante a Terceira Guerra, as ruas da superfície e praças rachadas agora fervilham de monstruosidades errantes, espectros vingativos e experimentadores vis. Tanto a Aliança quanto a Horda enviam expedições a esta cidadela arruinada para resgatar relíquias do passado caído ou expurgar os horrores à espreita acima da capital dos Renegados.",h="Empoleiradas diretamente acima da subterrânea Cidade Baixa, as Ruínas de Lordaeron são os restos desolados do...",kw={"bjork","capitão de Lordaeron","nova peste","rath'mael","ruínas de lordaeron","o abandonado","o barão","clareiras de tirisfal","cidade baixa","viktor, o vil","witherfang"},ang={["class:Paladin"]="Lordaeron foi o berço dos Cavaleiros do Punho de Prata; percorrer seus salões profanados para expurgar horrores e dar descanso a capitães inquietos é um dever solene da Luz.",["faction:Alliance"]="Aventurar-se em Lordaeron permite que a Aliança ataque os portões da capital dos Renegados enquanto traz justiça e paz aos espíritos de seus irmãos do norte massacrados.",["race:Human"]="Aventureiros humanos veem a capital arruinada como solo sagrado roubado pela traição, buscando resgatar relíquias perdidas e honrar parentes caídos.",["race:Undead"]="Para os Renegados, as ruínas acima são seu antigo lar e eterno cemitério. Limpar a área assegura sua entrada e fornece aos boticários componentes para desenvolver a Nova Peste."},sec={{t="O Pátio de um Império Caído",b="Capital já foi a joia da coroa dos Reinos do Leste, a sede do Rei Terenas Menethil II e o coração pulsante da civilização humana. Quando o Príncipe Arthas retornou de Northrend, ele assassinou seu pai na sala do trono e libertou os mortos-vivos sobre a população. Hoje, enquanto os Renegados habitam as catacumbas da Cidade Baixa abaixo, as ruínas da superfície permanecem como uma esquecida terra de penumbra. Arcos quebrados e pedras cobertas de mato abrigam feras selvagens como Witherfang e vestígios ensandecidos do passado."},{t="Tormento e Pestilência",b="Os perigos dentro dos terrenos arruinados vão além dos mortos inquietos. Boticários e figuras sinistras como Viktor, o Vil trabalham testando novas pragas entre as sombras, enquanto experimentos distorcidos como O Abandonado vagam livremente. Espíritos coléricos como Rath'mael e serviçais amaldiçoados como O Barão assombram os corredores desabados, presos em tormento perpétuo e atacando quaisquer invasores, vivos ou mortos-vivos, que cruzem seus caminhos."},{t="Fantasmas da Guarda Real",b="Entre os perigos mais pungentes nas ruínas superiores estão os resquícios espectrais dos defensores da cidade, culminando no surgimento de um fantasmagórico Capitão de Lordaeron. Ainda apegados aos seus juramentos despedaçados, essas aparições veem qualquer um que se aproxime do trono como invasor. Dar descanso ao Capitão e aos seus soldados traz um desfecho agridoce a uma vigília ininterrupta que dura desde o dia em que a capital caiu."}},faq={{q="Onde fica a masmorra de Ruínas de Lordaeron?",a="A masmorra fica situada diretamente nos níveis de superfície de Capital em Clareiras de Tirisfal, posicionada logo acima da rede de entradas que desce para a capital dos Renegados em Cidade Baixa.",al={"localização das ruínas de lordaeron","onde fica a masmorra de lordaeron","entrada da masmorra de cidade baixa"}},{q="Por que a Horda e a Aliança têm interesse neste local?",a="Para a Aliança, aventurar-se em Lordaeron é uma peregrinação sagrada para recuperar relíquias de família perdidas, coletar brasões reais e conceder paz final aos ancestrais caídos. Para a Horda, em particular os Renegados, expurgar as ruínas superiores é essencial para proteger o perímetro de Cidade Baixa e obter amostras de pesquisa para a nova peste da Real Sociedade de Boticários.",al={"por que ir às ruínas de lordaeron","missões da aliança em lordaeron","missões da horda em lordaeron"}},{q="Quem é Viktor, o Vil?",a="Viktor, o Vil é uma das figuras malévolas que se aproveitam da ausência de lei nas ruínas. Ele realiza experimentos nefastos e alimenta a corrupção que mantém a parte superior da capital infestada de abominações deformadas.",al={"história de Viktor, o Vil","quem é Viktor, o Vil"}},{q="Quem é o Abandonado encontrado nas ruínas?",a="O Abandonado é uma monstruosidade morta-viva grotesca deixada nas ruínas. Como tantos horrores feitos de retalhos criados durante e após a conquista do Flagelo, ele vagueia sem rumo pelas câmaras abandonadas e ataca tudo o que encontra.",al={"chefe O Abandonado","quem é O Abandonado"}},{q="O que derrotar o Capitão de Lordaeron representa para a história?",a="Derrotar o espectral Capitão de Lordaeron liberta um defensor real de alta patente de um dever perpétuo e enlouquecedor. Atado pela honra desde o massacre inicial do Flagelo, o Capitão passou anos guardando um reino destruído contra todos os que se aproximam. Dar descanso ao Capitão quebra um ciclo agonizante de servidão fantasma e permite que sua insígnia ensanguentada seja recuperada.",al={"derrotando capitão de Lordaeron","importância do capitão de Lordaeron","o que acontece quando o capitão morre"}},{q="As Ruínas de Lordaeron são separadas de Cidade Baixa?",a="Sim. Enquanto os Renegados têm seu lar nas cavernas de Cidade Baixa abaixo, as ruínas da superfície são uma zona de combate ativa tomada por fantasmas inquietos, predadores ferozes e ameaças experimentais que os Renegados não erradicaram completamente.",al={"cidade baixa fica nesta masmorra","ruínas vs cidade baixa"}}},fx={["1b77984b"]={q="O que é este lugar, as Ruínas de Lordaeron?",a="Você está diante dos restos despedaçados da Capital, outrora a joia da civilização humana e o coração do Reino de Lordaeron. Durante a Terceira Guerra, o Príncipe Arthas traiu seu reino, massacrou seu pai, o Rei Terenas, na sala do trono acima, e libertou o Flagelo morto-vivo sobre suas ruas. Hoje, seus arcos quebrados e torres chamuscadas situam-se acima da Cidade Baixa subterrânea, servindo como um memorial amargo ao reino que caiu.",al={"o que são as ruínas de lordaeron","conhecimento sobre as ruínas de lordaeron","o que era este lugar"}},eb89374f={q="Quem vivia aqui antes de ser arruinado?",a="Esta cidade era o lar do maior reino nortista da humanidade, governado pela dinastia Menethil. Nobres, sacerdotes da Luz Sagrada, soldados e centenas de milhares de pessoas comuns caminhavam por essas ruas pavimentadas. Tragicamente, muitos desses antigos cidadãos nunca partiram de verdade; abatidos pela peste, seus cadáveres reanimados compõem tanto o Flagelo sem mente que assombra as Terras Pestilentas quanto os Renegados libertados que agora habitam as cavernas abaixo.",al={"quem viveu aqui antes","povo original de lordaeron","quem estava aqui primeiro"}},["6e6195fd"]={q="Por que está tudo quebrado e queimado?",a="Quando o Príncipe Arthas retornou com a Gélido Lamento, ele matou o Rei Terenas e entregou a cidade ao Flagelo. Horrores mortos-vivos devastaram as avenidas, queimando edifícios e massacrando qualquer um que tentasse resistir. Mais tarde, durante a guerra civil entre os mortos-vivos, Sylvana Correventos e seus Renegados lutaram contra senhores do pavor e legiões remanescentes do Flagelo por esses mesmos pátios, derrubando o que restava da grande arquitetura da cidade.",al={"por que lordaeron foi destruída","como lordaeron foi queimada","por que está em ruínas"}},dd470a5c={q="Quem destruiu Lordaeron?",a="O reino foi destruído por dentro por seu próprio príncipe herdeiro, Arthas Menethil, sob o sussurro corruptor do Lich Rei. Enviado para deter a Seita dos Malditos e sua peste da morte-viva, Arthas tornou-se implacável, empunhou a lâmina rúnica amaldiçoada Gélido Lamento no norte gelado e rendeu sua alma. Voltando para casa como um cavaleiro da morte, ele matou seu pai e entregou a cidade às garras do Flagelo.",al={"quem arruinou lordaeron","quem derrubou lordaeron","destruidor de lordaeron"}},f5a9164f={q="Onde está Arthas agora?",a="Arthas deixou o continente arruinado de Lordaeron anos atrás, navegando de volta pelo O Grande Oceano para Nortúndria quando o Lich Rei foi ameaçado pelo caçador de demônios Illidan Tempesfúria. Ele lutou para subir a agulha gelada do Trono de Gelo e desapareceu da visão comum nos ermos congelados, deixando para trás um reino despedaçado em facções rivais de mortos-vivos e sobreviventes.",al={"para onde arthas foi","onde está o príncipe arthas","localização de arthas"}},["2fe0baef"]={q="Alguém escapou da cidade?",a="Alguns poucos afortunados escaparam do massacre. Antes do colapso final, a feiticeira Jaina Proudmore atendeu aos avisos de um profeta misterioso e liderou milhares de refugiados humanos através do mar para Kalimdor, onde estabeleceram o porto de Theramore. Outros fugiram para o sul em direção ao Reino de Ventobravo, ou pegaram em armas sagradas para lutar, formando a fanática Cruzada Escarlate e a vigilante Aurora Argêntea.",al={"cidadãos de lordaeron sobreviveram","alguém sobreviveu à queda de lordaeron","sobreviventes de lordaeron"}},["9cf7434f"]={q="Por que existe uma cidade de mortos-vivos sob as ruínas?",a="Quando o poder do Lich Rei diminuiu, Sylvana Correventos quebrou seu controle mental sobre uma multidão de mortos-vivos. Chamando-se de Renegados, eles derrubaram os senhores do pavor demoníacos que mantinham a Capital. As ruínas acima estavam muito expostas a olhares hostis e ataques constantes da Cruzada Escarlate, então Sylvana escolheu transformar as vastas criptas e esgotos subterrâneos em uma fortaleza fortemente protegida.",al={"por que a cidade baixa existe","por que a cidade baixa está sob lordaeron","cidade morta-viva sob ruínas"}},["55ddf3da"]={q="Quem construiu a Cidade Baixa?",a="A fundação começou sob a Capital como masmorras reais, esgotos e criptas profundas construídas pelos humanos de Lordaeron. Durante a Terceira Guerra, Arthas e o Flagelo começaram a expandir esses corredores subterrâneos em uma rede elaborada destinada a ser um centro de poder do Flagelo. Depois de arrancar o controle do lorde do pavor Varimatras, Sylvana e os Renegados terminaram de esculpir a Cidade Baixa como sua capital permanente.",al={"quem fez a cidade baixa","construção da cidade baixa","quem escavou a cidade baixa"}},c0ee4f6f={q="A Cidade Baixa sempre esteve lá embaixo?",a="Não em seu estado moderno e extenso. Nos dias do Rei Terenas, o subterrâneo consistia apenas de masmorras de castelo, aquedutos, canais de esgoto e tumbas familiares. Somente após a queda do reino é que as abominações do Flagelo e os trabalhadores Renegados escavaram os enormes anéis e bairros que você vê hoje, transformando túneis de serviço em um vasto bastião subterrâneo dos mortos.",al={"cidade baixa sempre existiu","cidade baixa existia antes","cidade baixa antiga"}},dc41e367={q="Quem está no comando aqui?",a="A Grande Dama Sylvana Correventos, a Rainha Banshee, comanda estas ruínas e a Cidade Baixa sob elas. Antigamente a Patrulheira-Geral de Luaprata, ela foi morta por Arthas, erguida como uma banshee vingativa e, eventualmente, recuperou seu cadáver físico. Através de pura força de vontade e astúcia, ela libertou seus irmãos mortos-vivos e forjou os Renegados, guiando-os com determinação implacável de seu trono no Royal Quarter.",al={"quem governa as ruínas de lordaeron","líder da cidade baixa","quem controla este lugar"}},["3d3094f9"]={q="Sylvanas é uma rainha ou algo diferente?",a="Seu povo a reverencia como a Rainha Banshee e Senhora dos Renegados, mas ela não é da realeza hereditária de Lordaeron. O título reflete a natureza trágica de sua morte pelas mãos do Príncipe Arthas, que arrancou sua alma de seu corpo para servir como uma banshee lamuriente. Embora o título ecoe uma monarquia, sua autoridade nasce da libertação, da sobrevivência e do comando militar total.",al={"sylvanas é uma rainha","título rainha banshee","qual o título de sylvanas"}},ac534dbb={q="Sylvanas responde a Thrall?",a="No papel, Sylvanas reconhece o Chefe Guerreiro Thrall como o comandante supremo da Horda, e ela concordou com a aliança de conveniência deles. Na realidade, a Rainha Banshee mantém autonomia total sobre os Renegados e seus territórios do norte. A palavra de Thrall é respeitada, e emissários Renegados caminham por Orgrimmar, mas a Lady Sylvanas responde, em primeiro lugar, à sua própria sobrevivência e às ambições de seu povo.",al={"relação sylvanas thrall","sylvanas obedece thrall","sylvanas está sob thrall"}},["6b51523d"]={q="O que aconteceu naquela sala do trono no topo das escadas?",a="A sala do trono foi o local da traição catastrófica que encerrou o reino. O Príncipe Arthas, recém-retornado de Nortúndria, marchou diante dos cidadãos que o recebiam e dos sinos que tocavam até chegar a esta câmara. Quando seu pai, o Rei Terenas, levantou-se do trono para cumprimentá-lo, Arthas sacou a Gélido Lamento, proclamou que estava sucedendo seu pai e cravou a lâmina rúnica amaldiçoada no coração do velho rei.",al={"o que aconteceu na sala do trono","história da sala do trono de lordaeron","histórico da sala do trono"}},["6e83c082"]={q="É esse o local onde Terenas foi morto?",a="Sim. Se você ficar bem diante do estrado quebrado, estará nas mesmas lajes onde o Rei Terenas Menethil II deu seu último suspiro. Uma mancha escura e tênue permanece visível no chão de pedra, dita ser o sangue do velho rei que penetrou na alvenaria quando seu filho o derrubou. Ainda hoje, sussurros espectrais e sinos ecoam fracamente na câmara.",al={"onde terenas foi morto","aquilo é sangue de terenas","local onde o rei terenas morreu"}},ea8d978d={q="O que aconteceu com a coroa de Terenas?",a="A coroa dourada de Terenas caiu no chão quando Arthas o assassinou na sala do trono. Sua queda marca o fim de seu reinado e a catástrofe que sobreveio a Lordaeron.",al={"por que a coroa está no chão","coroa do rei terenas ruínas","sangue na coroa de terenas"}},bb044bc8={q="Os Renegados fazem parte da Horda?",a="Sim, embora seja, em grande parte, um pacto de sobrevivência mútua. Cercados pela Cruzada Escarlate, humanos hostis e o Flagelo remanescente, os Renegados enviaram embaixadores através do mar em busca de aliados. A Horda, precisando de uma base nos Reinos do Leste para contra-atacar a Aliança, concordou em permitir sua entrada, dando aos Renegados um apoio militar muito necessário e status internacional.",al={"renegados horda aliança","mortos-vivos fazem parte da horda","por que renegados na horda"}},["50000697"]={q="Por que Thrall aceitou mortos-vivos na Horda?",a="Thrall foi convencido principalmente através da intercessão do Arquidruida Hamuul Runetotem e dos tauren, que acreditavam que os Renegados eram vítimas trágicas que poderiam, um dia, encontrar redenção ou uma cura para sua aflição. Além disso, Thrall reconheceu a necessidade estratégica de uma fortaleza estabelecida nos Reinos do Leste para impedir que a Aliança dominasse o continente norte sem oposição.",al={"por que thrall permitiu mortos-vivos","motivo thrall renegados","por que a horda aceitou os renegados"}},["9af0f393"]={q="Os orcs e tauren confiam neles?",a="Não inteiramente. Enquanto os tauren os veem com profunda piedade e esperança de curar sua condição, muitos orcs nutrem profundas dúvidas sobre a magia das trevas, a necromancia e a natureza sinistra da Cidade Baixa. Thrall mantém um olhar atento sobre as ações de Sylvanas, e os embaixadores estacionados ficam cautelosos com o que é preparado nos laboratórios da Real Sociedade de Boticários.",al={"orcs confiam nos renegados","confiança tauren renegados","a horda confia nos mortos-vivos"}},["849f698a"]={q="É seguro eu ficar aqui?",a="Depende inteiramente de suas lealdades. Se você luta pela Horda, os Renegados e suas abominações reconhecem você como um aliado, embora as sombras acima abriguem criaturas ladinas e espíritos persistentes. Se você marcha sob a bandeira da Aliança, você está em território inimigo; sentinelas Renegados e guardas do pavor o derrubarão à vista.",al={"é seguro ficar nas ruínas de lordaeron","estou seguro aqui","perigo em lordaeron"}},aac358a1={q="Os guardas vão me atacar?",a="Os Guardas da Morte Renegados e as abominações reais estacionados ao redor das ruínas ignorarão ou protegerão os viajantes da Horda, mas são brutalmente hostis aos campeões da Aliança. Além disso, renegados hostis e monstros espreitam dentro de corredores isolados e alas de masmorras das ruínas acima, e eles atacarão qualquer um que cruzar seu caminho, independentemente da lealdade.",al={"os guardas da cidade baixa atacam","guardas das ruínas são hostis","os guardas me atacam"}},e9ec8c01={q="Ainda há Flagelo por perto?",a="Sim. Embora Sylvanas tenha varrido a maioria do Flagelo da Cidade Capital, o Flagelo permanece fortemente entrincheirado logo além das fronteiras, nas Terras Pestilentas Ocidentais. Mesmo dentro dos nichos mais escuros e subníveis esquecidos destas ruínas, mortos-vivos irracionais e remanescentes do Flagelo ainda permanecem, esperando para estraçalhar qualquer carne viva que se afaste demais.",al={"flagelo nas ruínas de lordaeron","o flagelo está perto da cidade baixa","há flagelo por perto"}},["0a975308"]={q="O que é a praga sobre a qual todos continuam falando?",a="Eles falam da Praga da Morte-viva, um contágio biomágico horrível desenvolvido pelo Lich Rei e seus necromantes. Distribuída por toda Lordaeron através de grãos infectados pela Seita dos Malditos, ela matou qualquer um que os consumiu em poucas horas e imediatamente reanimou seus cadáveres como thralls obedientes e apodrecidos do Flagelo.",al={"o que é a praga da morte-viva","qual praga é mencionada","praga de lordaeron"}},["290f94a8"]={q="Quem criou a praga original?",a="A praga original foi projetada pelos senhores do medo da Legião Ardente e aperfeiçoada pelo Lich Rei, Ner'zhul, enquanto ele estava aprisionado no topo do Trono de Gelo em Nortúndria. Para libertá-la em Lordaeron, ele recrutou o arquimago renegado de Dalaran, Kel'Thuzad, que fundou a Seita dos Malditos e contaminou os estoques de grãos.",al={"quem criou a praga da morte-viva","criador da praga original","quem fez a praga"}},["89f62638"]={q="Sylvanas está criando uma nova praga?",a="Sim. A Lady Sylvanas encarregou a Real Sociedade de Boticários de preparar uma 'Nova Praga'. Seu objetivo é criar uma arma biológica potente o suficiente para aniquilar tanto o Flagelo quanto os vivos, garantindo a sobrevivência dos Renegados e vingança contra Arthas. Seus testes secretos estão acontecendo agora no Boticarium abaixo.",al={"sylvanas está criando uma praga","nova praga dos renegados","nova praga cidade baixa"}},dcb566d2={q="Quem é o Lich Rei e o que ele quer?",a="O Lich Rei é o governante supremo do Flagelo, criado a partir do espírito torturado do xamã orc Ner'zhul, encerrado em gelo no topo do Trono de Gelo. Seu objetivo era suavizar Azeroth para a Legião Ardente, mas ele nutria suas próprias ambições aterrorizantes: erradicar toda vida mortal e substituí-la por um império eterno e unificado de morte-viva sob seu comando mental absoluto.",al={"quem é o lich rei","o que o lich rei quer","motivos do lich rei"}},["3a9893a7"]={q="Onde está o Lich Rei agora?",a="Ele governa do Trono de Gelo no topo da Geleira da Coroa de Gelo, no distante e congelado continente de Nortúndria. Após o ataque de Illidan que rachou sua prisão de gelo, o Lich Rei convocou Arthas de volta a Nortúndria para fundir seus espíritos e preservar seu poder, bem longe do reino despedaçado de Lordaeron.",al={"onde está o lich rei","localização do lich rei","onde fica o trono de gelo"}},["0138c577"]={q="Ele ainda controla os Renegados?",a="Não. Quando o Trono de Gelo foi rachado pelos feitiços de Illidan, o controle telepático do Lich Rei começou a se fragmentar. Sylvanas e muitos outros mortos-vivos recuperaram seu livre-arbítrio e romperam com sua mente coletiva. Embora ele tente recuperá-los, os Renegados agora resistem violentamente aos seus sussurros e lutam ferozmente para manter sua autonomia.",al={"o lich rei controla os renegados","o lich rei pode comandar os renegados","livre-arbítrio dos renegados"}},["6a523c60"]={q="Quem é a Cruzada Escarlate e por que eles odeiam os mortos-vivos?",a="a Cruzada Escarlate é uma ordem de fanáticos religiosos humanos formada a partir dos remanescentes despedaçados do Punho de Prata e dos cavaleiros de Lordaeron. Traumatizados pela praga que destruiu sua terra natal, eles são consumidos pela paranoia. Aos olhos deles, todos os mortos-vivos são abominações sem exceção, e qualquer vivo que se associe a eles é considerado contaminado e marcado para execução.",al={"quem é a cruzada escarlate","por que a cruzada escarlate odeia mortos-vivos","história da cruzada escarlate"}},b59db3a3={q="Eles são o mesmo que a Aurora Argêntea?",a="Não, eles são rivais amargos com raízes comuns. Ambos surgiram das cinzas dos Cavaleiros do Punho de Prata, mas quando a Cruzada Escarlate sucumbiu ao fanatismo cego e à xenofobia, paladinos moderados se separaram para formar a Aurora Argêntea. A Aurora acolhe todas as raças e se concentra em defender a terra contra o Flagelo em vez de expurgar indiscriminadamente.",al={"cruzada escarlate vs aurora argêntea","cruzada escarlate e aurora argêntea são iguais","diferença entre cruzada escarlate e aurora argêntea"}},ca88b6f6={q="Eles também atacam jogadores vivos?",a="Sim. a Cruzada Escarlate acredita que qualquer um que não esteja vestindo seu tabardo carmesim está secretamente escondendo a praga ou colaborando com os mortos-vivos. Seja você um orc, um tauren, um elfo noturno ou um soldado humano de Ventobravo, os fanáticos deles o rotularão como um portador da corrupção e o atacarão à primeira vista.",al={"cruzada escarlate ataca a aliança","os escarlates atacam os vivos","cruzada escarlate hostil aos vivos"}},["861c7602"]={q="O que a Real Sociedade de Boticários está fazendo lá embaixo?",a="Operando a partir do Boticarium na Cidade Baixa, esta guilda sinistra de alquimistas Renegados e ex-magos trabalha incansavelmente sob o decreto de Lady Sylvanas. Seu mandato principal é desenvolver uma 'Nova Praga' catastrófica que pode eliminar tanto o Flagelo quanto as raças vivas, conduzindo experimentos cruéis para garantir a supremacia dos Renegados.",al={"o que a real sociedade de boticários faz","objetivo da real sociedade de boticários","boticários cidade baixa"}},["3c47ce18"]={q="Eles estão fazendo experimentos em pessoas?",a="Sim. Nas profundezas do Boticarium, cruzados da Cruzada Escarlate capturados, carniçais do Flagelo e várias feras estão trancados em gaiolas de ferro. Os boticários submetem esses prisioneiros a coquetéis químicos dolorosos e cepas virulentas de praga, avaliando quão rapidamente a carne apodrece e como o contágio afeta a fisiologia tanto viva quanto necrótica.",al={"boticário fazendo experimentos em humanos","experimentos da real sociedade de boticários","boticários da cidade baixa torturam pessoas"}},f7d23701={q="Arthas ainda está vivo, e eu poderia lutar contra ele?",a="Arthas não está morto no sentido mortal, mas totalmente corrompido em um cavaleiro da morte campeão do Flagelo. Ele está muito longe, do outro lado do mar em Nortúndria, além do alcance de qualquer pessoa em Lordaeron. Sua luta agora é contra as ameaças que ainda persistem aqui: os comandantes locais do Flagelo, a Cruzada Escarlate e as feras rebeldes que infestam estas ruínas.",al={"posso lutar contra arthas","arthas está vivo","enfrentaremos arthas"}},["9fc2648e"]={q="Ele é o Lich Rei agora?",a="Sussurros do norte alegam que Arthas ascendeu à torre da Coroa de Gelo para libertar o Lich Rei do cerco de Illidan, despedaçando o gelo para empunhar o Elmo da Dominação e fundindo sua alma com a de Ner'zhul. Para o mundo em geral, o estado exato de Nortúndria permanece envolto em mistério gelado, mas sua presença sombria paira sobre todos os mortos-vivos.",al={"arthas é o lich rei","arthas se tornou o lich rei","identidade de arthas lich rei"}},["89a21402"]={q="Como eu vim parar nas Ruínas de Lordaeron?",a="Você caminhou pelos portões externos em ruínas da capital caída nas Clareiras de Tirisfal, logo acima dos elevadores que descem para a Cidade Baixa. Quer você tenha atendido a uma convocação militar, perseguido rumores de horrores incontroláveis agarrados ao cadáver do reino, ou passado furtivamente por território hostil para recuperar remanescentes sagrados do passado, sua jornada o trouxe para os pátios selados e disputados onde as sombras do Flagelo e os fantasmas da antiga humanidade ainda permanecem.",al={"como cheguei aqui","como fui parar aqui","por que estou nas ruínas de lordaeron","como cheguei a este lugar"}},bb4abd7f={q="O que eu deveria estar fazendo nas Ruínas de Lordaeron?",a="Você está aqui para purgar os horrores que apodrecem nas ruínas da superfície acima da capital dos Renegados. Para a Horda, isso significa limpar feras do Flagelo rebeldes, recuperar insígnias perdidas e testar misturas letais para a Real Sociedade de Boticários. Para a Aliança, é um ataque secreto para limpar terras ancestrais, recuperar relíquias sagradas como o Escudo de Lordaeron e trazer consolo aos fantasmas errantes e atormentados que não encontraram paz.",al={"o que estou fazendo aqui","qual é minha missão aqui","o que devo fazer nas ruínas","qual é meu objetivo aqui"}}},fp="18,278,27.503.0,22.413.0,25.302.1,48.174.0,61.277.0,23.179.0,49.228.0,61.384.1,54.227.0"}
P.entries["zone:scarlet"] = {n="Monastério Escarlate",s="Empoleirado nas colinas a nordeste de Clareiras de Tirisfal, o Monastério Escarlate já foi um santuário pacífico e centro de aprendizado para a Igreja da Luz Sagrada. Após a queda de Lordaeron, ele foi tomado e fortemente fortificado pela Cruzada Escarlate como sua principal base avançada no oeste. Agora, ergue-se como uma fortaleza ampla dividida em quatro alas, onde fanáticos zelosos treinam, torturam prisioneiros e travam uma guerra intransigente contra todos os forasteiros.",h="Empoleirado nas colinas a nordeste de Clareiras de Tirisfal, o Monastério Escarlate já foi um santuário...",kw={"armaria","catedral","doan","cemitério","herodes","library","mograine","cruzada escarlate","monastério escarlate","clareiras de tirisfal","whitemane"},ang={["class:Mage"]="A ala da Library abriga tomos históricos e teológicos raros, guardados pelo Arcanista Doan, o principal arcanista da Cruzada.",["class:Paladin"]="O monastério já foi uma sede sagrada do sacerdócio de Lordaeron, tornando sua decadência em um zelo carmesim uma lembrança trágica de como a devoção pode azedar em loucura.",["class:Priest"]="Originalmente uma sede da Igreja da Luz Sagrada, suas grandes capelas demonstram como o poder sagrado ainda pode ser empunhado por mortais corrompidos pelo ódio e pela vingança.",["race:Undead"]="Empoleirado na fronteira de Clareiras de Tirisfal, o Monastério Escarlate representa uma ameaça existencial aos Renegados, infiltrando espiões em Plangemortis e torturando mortos-vivos capturados dentro de suas masmorras."},sec={{t="Um Santuário Caído",b="Antes da Terceira Guerra, o monastério servia como uma orgulhosa sede do sacerdócio de Lordaeron e um centro de aprendizado e iluminação. Após a devastação do Flagelo, cruzados sobreviventes expurgaram os mortos-vivos e as aranhas remanescentes dos corredores, transformando os arquivos e pátios tranquilos em uma guarnição fortificada. Movida pela paranoia e pelo luto, a Cruzada Escarlate passou a ver todos os forasteiros — vivos ou mortos-vivos, humanos ou não — como portadores da peste que devem ser purificados com fogo."},{t="As Quatro Alas",b="Passando pelo Grand Vestibule do monastério, encontram-se quatro setores distintos. O Cemitério é um terraço a céu aberto profanado onde cruzados caídos se erguem como abominações mortas-vivas e torturadores arrancam confissões de prisioneiros. A Biblioteca preserva preciosos textos teológicos e tomos históricos, guardada pelo mago renegado Arcanista Doan e seus cães. A Armaria serve como campo de treinamento onde mestres de armas escarlates como Herodes treinam recrutas fanáticos para se tornarem guerreiros couraçados. Mais adiante, no ponto mais profundo, ergue-se a Catedral, o grandioso coração da fortaleza, de onde a liderança da Cruzada comanda sua cruzada pelo norte assolado."},{t="A Queda da Alta-inquisidora",b="O santuário interior da Catedral é comandado pelo Comandante Escarlate Mograine e pela verdadeira mestra do monastério, High Inquisitor Whitemane. Derrotar Whitemane desfere um golpe crítico no comando operacional da Crusade em Clareiras de Tirisfal. Sua capacidade de canalizar a cegante Holy Light e ressuscitar campeões caídos fazia a guarnição parecer invencível para seus devotos. Matá-la despedaça a aura de mandato divino que alimentava o fanatismo do monastério, expondo a liderança da Crusade como mortal e enfraquecendo severamente sua campanha contra os Renegados e as terras vizinhas."}},faq={{q="Por que a Cruzada Escarlate é hostil a aventureiros vivos da Aliança?",a="A Cruzada sucumbiu à loucura e à paranoia extremas. Aos olhos deles, qualquer um que não use seu tabardo carmesim é um potencial portador da peste do Flagelo. Eles não fazem mais distinção entre amigo ou inimigo, vendo todos os forasteiros como seres maculados que precisam ser purificados antes que possam espalhar a corrupção.",al={"por que escarlates atacam humanos","cruzada escarlate hostil à aliança","por que eles enlouqueceram"}},{q="O que acontece quando você derrota a Alta-inquisidora Whitemane?",a="Derrotar a Alta-inquisidora Whitemane decapita a liderança militar ocidental da Cruzada Escarlate. Como líder espiritual do monastério, seus miraculosos poderes de ressurreição mantinham a moral das tropas e sustentavam o Comandante Mograine lutando ao seu lado. Sua morte remove a sacerdotisa mais poderosa da Cruzada em Clareiras de Tirisfal, deixando a guarnição desordenada e diminuindo severamente sua ameaça à região circundante.",al={"o que significa matar whitemane","história da derrota de whitemane","desfecho da catedral"}},{q="O que é A Chave Escarlate e onde ela é encontrada?",a="A Chave Escarlate é mantida nas profundezas da ala da Library do monastério, guardada dentro do cofre do Arcanista Doan, atrás de seu gabinete pessoal. Possuir esta chave é necessário para destrancar os portões externos de ambas as alas da Armaria e da Catedral.",al={"onde fica a chave escarlate","como abrir armaria e catedral","chave do monastério"}},{q="Por que o Arcanista Doan está no Monastério Escarlate?",a="O Arcanista Doan é um poderoso mago humano que serve à Cruzada Escarlate, convencido de que a magia arcana é uma arma necessária para purificar o Flagelo de Lordaeron. Ele cuida da extensa ala da Library do monastério e protege A Chave Escarlate em seu gabinete.",al={"quem é arcanista doan","história de doan","mago na biblioteca"}},{q="Quem foi Alexandros Mograine e qual é a sua ligação aqui?",a="Alexandros Mograine, o famoso portador de A Crematória, foi um lendário paladino do Punho de Prata e, com a Alta-general Abbendis e o Grão-inquisidor Isillien, um dos fundadores da Cruzada Escarlate. Seu filho Renault agora comanda a Catedral ao lado da Alta-inquisidora Whitemane.",al={"história de mograine no monastério","a crematória monastério","pai de renault mograine"}},{q="O que torna a ala do Cemitério tão diferente do resto do monastério?",a="Enquanto o resto do monastério mantém uma aparência externa de devoção imaculada, o Cemitério é onde o fanatismo da Cruzada apodrece por dentro. Ele abriga suas brutais câmaras de tortura comandadas pelo Interrogador Vishas, enquanto criptas negligenciadas e mortos inquietos são colhidos ou manipulados por conjuradores caídos como o Mago Sangrento Thalnos.",al={"por que o cemitério tem mortos-vivos","história de thalnos","interrogador vishas"}}},fx={["3ffc247b"]={q="O que é o Monastério Escarlate?",a="Situado no nordeste das Clareiras de Tirisfal, o Monastério Escarlate é um santuário fortificado e o principal bastião da Cruzada Escarlate na região. Antigamente um complexo de catedral pacífico dedicado à Luz Sagrada e ao aprendizado clerical, a fortaleza foi convertida em um quartel-general fortemente armado, campo de treinamento e reduto ideológico para a campanha zelosa da Cruzada contra a morte.",al={"o que é o monastério escarlate","lore do monastério escarlate","sobre o monastério escarlate"}},fd7417a7={q="O Monastério Escarlate sempre foi deles?",a="Não. Antes da queda de Lordaeron, ele era conhecido simplesmente como o Antigo Monastério. Originalmente patrocinado pela nobre Casa de Godwyn, serviu como sede de arcebispado e seminário sob o Arcebispo Alonsus Faol. Após a devastação da Terceira Guerra, paladinos sobreviventes recuperaram seus salões das infestações persistentes do Flagelo e o renomearam como Monastério Escarlate.",al={"o monastério escarlate sempre foi da cruzada","história do monastério escarlate","a quem pertencia o monastério escarlate antigamente"}},e7b85043={q="Quem construiu o Monastério Escarlate?",a="O Antigo Monastério foi construído como um santuário da Igreja da Luz Sagrada sob o patrocínio da nobre Casa de Godwyn. Suas bibliotecas e arquivos foram organizados por gerações por arquivistas como Blake Godwyn, permanecendo como um orgulhoso centro de treinamento de sacerdócio e paladinos de Lordaeron até o colapso do reino.",al={"quem construiu o monastério","origens do monastério"}},["0c05301c"]={q="Quem é a Cruzada Escarlate?",a="a Cruzada Escarlate é uma ordem militar fanática de guerreiros sagrados e sacerdotes humanos formados a partir de remanescentes dos Cavaleiros do Punho de Prata. Consumidos pelo luto e pelo ódio após o Flagelo de Lordaeron, eles se dedicaram inteiramente a erradicar os mortos-vivos, impondo sua missão com extrema crueldade e paranoia.",al={"quem é a cruzada escarlate","o que é a cruzada escarlate","lore da cruzada escarlate"}},b0ef06b1={q="a Cruzada Escarlate é humana?",a="Sim, suas fileiras consistem inteiramente de humanos do reino caído de Lordaeron. Eles nutrem uma intolerância feroz em relação a todas as raças não humanas, independentemente de alianças ou laços anteriores, considerando os forasteiros indignos ou inerentemente contaminados pela praga.",al={"a cruzada escarlate é composta apenas por humanos","raça da cruzada","cruzada escarlate é humana"}},["1402011d"]={q="Por que estou atacando uma igreja cheia de paladinos?",a="Embora vistam as insígnias de ordens sagradas e empunhem a Luz, os comandantes do Monastério sucumbiram ao extremismo violento. Quer você responda ao chamado de Raul, o Devotado para purificar a liderança corrompida da ordem, ou ataque em nome de Varimatras na Cidade Baixa para neutralizar um vizinho agressivo na sua porta, você está lá para destruir o poder militar deles.",al={"por que atacar o monastério escarlate","por que matar paladinos aqui","motivo para lutar contra o monastério escarlate"}},["18e8d4ac"]={q="a Cruzada Escarlate é realmente má?",a="Eles começaram com uma causa nobre: purgar Lordaeron do Flagelo dos mortos-vivos. No entanto, o trauma e a paranoia corromperam seu propósito completamente. Eles agora torturam viajantes inocentes, rotulam qualquer forasteiro como contaminado pela praga e matam qualquer um que não porte seu tabardo, perdendo toda a sanidade moral na busca pela purificação.",al={"a cruzada escarlate é má","eles são os vilões","cruzados são maus"}},fe2faadd={q="A Aliança apoia Cruzada Escarlate?",a="Não oficialmente. Embora alguns em Ventobravo possam nutrir simpatia pelos guerreiros sagrados sobreviventes de Lordaeron, a hostilidade indiscriminada da Cruzada rompeu os laços formais. Aventureiros e figuras da Aliança como Raul, o Devotado veem seus comandantes atuais como fanáticos loucos cujas atrocidades mancham a honra da Luz.",al={"a aliança apoia a cruzada","cruzada escarlate é da aliança","laços da aliança com a cruzada escarlate"}},fbd0569e={q="Quem comanda o Monastério Escarlate?",a="A guarnição militar da fortaleza responde ao Comandante Escarlate Renault Mograine, que comanda uma força devota de guerreiros. No entanto, a verdadeira autoridade espiritual e doutrinária do complexo é a Alta-inquisidora Cristalba, uma poderosa sacerdotisa capaz de reviver os caídos para lutar em seu nome.",al={"quem lidera o monastério escarlate","quem comanda o monastério","líder do monastério escarlate"}},ae07147f={q="O líder do Monastério está dentro da Catedral?",a="Sim. Tanto o Comandante Escarlate Mograine quanto a Alta Inquisidora Sally Whitemane residem dentro da Capela do Cruzado nas profundezas da ala da Catedral, guardados por um séquito interno de defensores zelosos.",al={"onde está whitemane","whitemane está na catedral","localização do chefe da catedral"}},["11700a05"]={q="Por que a Cruzada Escarlate odeia tanto os Renegados?",a="Para a Cruzada, todos os mortos-vivos são abominações nascidas da praga que obliterou suas famílias e sua terra natal. Eles não fazem distinção entre os lacaios irracionais do Flagelo e os Renegados de livre arbítrio ocupando a Cidade Capital; ambos são vistos como usurpadores podres que devem ser totalmente purificados no fogo sagrado.",al={"cruzada vs renegados","por que a cruzada odeia mortos-vivos","rixa entre cruzada escarlate e renegados"}},["38169c8a"]={q="Os Cruzados Escarlates e os Renegados já foram as mesmas pessoas?",a="Sim. A maioria dos Cruzados e Renegados eram cidadãos, soldados ou sacerdotes do Reino de Lordaeron antes da Terceira Guerra. Quando a praga se espalhou, aqueles que morreram e ressurgiram tornaram-se os mortos-vivos, enquanto os vivos traumatizados fugiram ou se uniram, transformando ex-vizinhos e parentes em inimigos amargos e jurados.",al={"cruzados e renegados se conheciam","ambos eram cidadãos de lordaeron","remanescentes de lordaeron"}},["80c0e472"]={q="Qual é a origem da Cruzada Escarlate?",a="A Cruzada surgiu dos cavaleiros sobreviventes da Mão de Prata e soldados de Lordaeron liderados pelo Grão-Lorde Alexandros Mograine e pela General Abbendis. Sobrecarregados pela perda de seu reino, os líderes sobreviventes se dividiram: aqueles que defendiam um zelo incansável e intransigente formaram a Cruzada Escarlate, enquanto os moderados se separaram para fundar a Aurora Argêntea.",al={"origem da cruzada escarlate","como a cruzada escarlate foi fundada","quem começou a cruzada escarlate"}},c4a70323={q="O que era a Mão de Prata?",a="Os Cavaleiros da Mão de Prata eram a lendária ordem sagrada de paladinos fundada durante a Segunda Guerra pelo Arcebispo Alonsus Faol e Uther, o Arauto da Luz. Eles serviram como campeões da linha de frente da Aliança e de Lordaeron até que o Príncipe Arthas despedaçou suas fileiras durante a invasão do Flagelo.",al={"o que era a mão de prata","cavaleiros da mão de prata","paladinos da mão de prata"}},d5472427={q="Por que a Cruzada Escarlate também mata humanos vivos?",a="Uma paranoia profunda corroeu a percepção da realidade da Cruzada. Eles acreditam que qualquer forasteiro pode ser um portador infiltrado da praga dos mortos-vivos. Qualquer pessoa que não esteja usando seu uniforme e se submetendo à sua autoridade rígida é rotulada como corrompida e sentenciada à tortura ou à morte.",al={"por que atacar humanos vivos","cruzada mata humanos","por que eles matam os seus"}},b6568619={q="a Cruzada Escarlate é uma ameaça a Ventobravo?",a="Não diretamente em termos de conquista geográfica, já que seus esforços estão ancorados nas ruínas ao norte de Lordaeron. No entanto, sua loucura e disposição para assassinar qualquer viajante os tornam uma ameaça ativa aos cidadãos, embaixadores e aventureiros da Aliança que se aventuram perto de seus territórios.",al={"a cruzada escarlate é uma ameaça à aliança","cruzada vs ventobravo","ameaça da cruzada escarlate"}},["6889160e"]={q="Por que todos querem que eu vá ao Monastério Escarlate?",a="Ambas as facções têm interesses vitais nas Clareiras de Tirisfal. Os Renegados não podem tolerar uma fortaleza de fanáticos fortemente armados bem diante de sua capital, enquanto figuras da Aliança buscam recuperar textos sagrados, conter renegados perigosos e levar justiça a uma liderança que enlouqueceu.",al={"por que fui enviado ao monastério escarlate","quem quer o monastério morto","motivo das missões no monastério escarlate"}},["0c6b4a7d"]={q="Para que serve a Scarlet Monastery Library?",a="A Biblioteca, que inclui o Ateneu e a Galeria de Tesouros, abriga escrituras antigas de Lordaeron, registros históricos e saberes arcanos. Ela serve tanto como um arquivo intelectual quanto como um santuário de pesquisa isolado presidido pelo Arcanista Doan.",al={"objetivo da ala da biblioteca","o que eles fazem na biblioteca","athenaeum do monastério escarlate"}},["29dc31ee"]={q="Para que são usadas as alas do Arsenal e da Catedral?",a="O Arsenal atua como o coração marcial da Cruzada, abrigando campos de treinamento, quartéis e depósitos de armas supervisionados por Herodes, o Campeão Escarlate. A Catedral se destaca como o santuário espiritual supremo e posto de comando, onde Mograine treina tropas de elite e Whitemane faz sermões e coordena a presença da Cruzada em Tirisfal.",al={"para que servem o arsenal e a catedral","propósito do arsenal no me","propósito da catedral no me"}},f04a1b7f={q="Como eu vim parar no Monastério Escarlate?",a="Você viajou até as colinas do extremo nordeste das Clareiras de Tirisfal, atravessando as clareiras enevoadas até a sede fortificada da Cruzada Escarlate. Quer você tenha vindo da Cidade Baixa sob ordens da Horda para desmantelar uma ameaça fanática à sua porta, ou marchado ao norte do Contraforte de Eira dos Montes atendendo ao chamado de cruzados desiludidos que buscam purgar a liderança fanática do Monastério, o caminho inevitavelmente o levou até este complexo fortemente guardado.",al={"como vim parar aqui","como cheguei ao monastério escarlate","por que vim aqui"}},be779d1d={q="O que eu deveria fazer no Monastério Escarlate?",a="Você está aqui para invadir as quatro alas da Cruzada e quebrar seu controle sobre a região. Dependendo de quem o enviou, você pode estar caçando líderes caídos como o Comandante Escarlate Mograine e a Alta Inquisidora Whitemane, descobrindo tomos e saberes perdidos dentro da biblioteca, coletando corações de zelo para a Real Sociedade de Boticários, ou recuperando artefatos sagrados e matando líderes corrompidos que rotulam qualquer pessoa fora de suas fileiras como mortos-vivos praguejados.",al={"o que estou fazendo aqui","por que estou aqui","qual é a minha missão aqui"}}},fp="17,291,18.495.0,14.492.0,31.517.1,66.284.0,55.301.1,46.170.0,46.213.0,57.280.1,74.218.0"}
P.entries["zone:searinggorge"] = {n="Garganta Abrasadora",s="A Garganta Abrasadora é um cânion árido e desolado no sul de Khaz Modan, que faz fronteira com a Montanha Rocha Negra ao sul. Outrora uma vasta região verdejante das Montanhas Cristarrubra, foi devastada há mais de dois séculos pela invocação apocalíptica de Ragnaros, o Senhor do Fogo. Hoje, o cânion é intensamente explorado pelo clã Ferro Negro, cujas extensas minas de escravos no Caldeirão são monitoradas de perto pela dissidente Irmandade do Tório.",h="A Garganta Abrasadora é um cânion árido e desolado no sul de Khaz Modan, que faz fronteira com a Montanha...",kw={"montanha rocha negra","o caldeirão","clã ferro negro","ragnaros","garganta abrasadora","fosso de lava","galeria lapidada","irmandade do tório","posto de tório"},ang={["class:Rogue"]="Ladinos com experiência em arrombamento de fechaduras são viajantes valorizados por aqui, pois conseguem passar pelo portão trancado da Galeria Lapidada, que liga Loch Modan diretamente ao cânion.",["faction:Alliance"]="A Aliança mantém trancado o portão da Galeria Lapidada para isolar os Ferro Negro dos povoados pacíficos de anões em Loch Modan, embora aventureiros corajosos tenham autorização para atacar o cânion.",["faction:Horde"]="Usando Karrath como base de operações, a Horda abriu uma rota terrestre até o cânion para obter informações sobre a Montanha Rocha Negra e interromper as operações Ferro Negro em Khaz Modan.",["profession:Mining"]="A paisagem vulcânica e as escavações profundas no Fosso de Lava fazem da Garganta Abrasadora um dos principais locais de caça a ricos veios de mithril, veraprata e cobiçado minério Ferro Negro.",["race:Dwarf"]="Para os anões de Altaforja, a Garganta Abrasadora é uma lembrança amarga da Guerra dos Três Martelos e da desastrosa imprudência do clã Ferro Negro, cujas escavações agora ameaçam as rotas de acesso ao sul de Khaz Modan."},sec={{t="Uma terra devastada e queimada",b="Antes da Guerra dos Três Martelos, o território que hoje é a Garganta Abrasadora era uma região montanhosa verde e ondulada, ligada à cadeia das Montanhas Cristarrubra. Essa paisagem exuberante deixou de existir há mais de duzentos e trinta anos, quando o Feiticeiro-Thane Thaurissan, desesperado para virar o rumo da derrota, invocou Ragnaros das profundezas subterrâneas. A aparição cataclísmica do Senhor do Fogo rasgou a terra, ergueu a Montanha Rocha Negra, reduziu a grandiosa cidade Ferro Negro de Thaurissan a ruínas fumegantes e queimou o vale ao norte, transformando-o numa extensão rachada de cinzas, enxofre e vidro vulcânico."},{t="O Caldeirão e o Fosso de Lava",b="Em busca de matérias-primas para abastecer sua máquina de guerra após perder a antiga capital, os anões Ferro Negro tomaram o cânion desolado. No centro do vale fica o Caldeirão, uma escavação colossal a céu aberto que se aprofunda nas rochas. Em suas reentrâncias inferiores encontra-se o Fosso de Lava, um brutal complexo de mineração subterrâneo. Ali, supervisores Ferro Negro e golems de guerra descomunais forçam inimigos capturados a cumprir trabalhos extenuantes como escravos, extraindo ferro, mithril e raros depósitos de minério Ferro Negro das rochas ardentes, sob a ameaça constante de jorros de lava e feras errantes."},{t="Irmandade do Tório e caminhos disputados",b="No alto dos penhascos ao norte, com vista para a escavação, fica o Posto de Tório, o posto avançado fortificado da Irmandade do Tório. Depois de romper com seus parentes na Montanha Rocha Negra, esses mestres artesãos oferecem abrigo neutro a viajantes dispostos a sabotar as operações Ferro Negro ou a fornecer componentes raros para fundição. O acesso ao próprio cânion é rigorosamente restrito: a Aliança mantém a Galeria Lapidada bloqueada por pesados portões de ferro na direção de Loch Modan, enquanto expedições da Horda vindas da vizinha Karrath abriram uma trilha estreita pelos Ermos a leste para explorar a região."}},faq={{q="Por que a Garganta Abrasadora está queimada e coberta de cinzas?",a="Há mais de duzentos e trinta anos, durante a Guerra dos Três Martelos, o Feiticeiro-Thane Ferro Negro Thaurissan tentou invocar um poder sobrenatural para evitar a derrota. Em vez disso, invocou Ragnaros, o Senhor do Fogo. A erupção cataclísmica despedaçou a cadeia montanhosa ao sul das Montanhas Cristarrubra, criou o vulcão da Montanha Rocha Negra e incinerou os vales ao redor, transformando-os na Garganta Abrasadora e nas Estepes Ardentes.",al={"por que está queimada","história da garganta abrasadora","como a garganta abrasadora foi criada"}},{q="Quem são os anões que vivem no Posto de Tório?",a="Eles pertencem à Irmandade do Tório, uma facção independente de anões Ferro Negro que rompeu os laços com seus parentes imperiais sob a Montanha Rocha Negra. De seu acampamento no alto do Posto de Tório, eles atuam como ferreiros e artífices mestres, negociando conhecimento e segredos de ofício com qualquer viajante que os ajude contra as forças Ferro Negro abaixo.",al={"anões do posto de tório","quem é a irmandade do tório","história da irmandade do tório"}},{q="O que está acontecendo no Caldeirão?",a="O Caldeirão é uma enorme escavação a céu aberto dominada pelo clã Ferro Negro e contém o Fosso de Lava subterrâneo. Supervisores Ferro Negro e golems de guerra usam prisioneiros capturados como mão de obra escrava para extrair minérios preciosos, incluindo valiosos depósitos de minério Ferro Negro, destinados a abastecer as grandes forjas dentro da Montanha Rocha Negra.",al={"o que é o caldeirão","história do fosso de lava","o que os ferro negro estão minerando"}},{q="Como chegar à Garganta Abrasadora saindo de Loch Modan?",a="A passagem de Loch Modan pela Galeria Lapidada está bloqueada por um pesado portão trancado, guardado por montanheses de Altaforja. Os viajantes precisam obter a Chave da Garganta Abrasadora por meio de uma tarefa oficial para o Curador Tórius, pedir a um Ladino habilidoso para arrombar a fechadura ou contornar o portão por completo, usando a trilha aberta ao sul de Karrath, nos Ermos.",al={"portão da galeria lapidada","como abrir o portão da garganta abrasadora","chave da garganta abrasadora"}},{q="Por que a Horda tem interesse na Garganta Abrasadora?",a="Operando a partir da fortaleza vizinha de Karrath, nos Ermos, comandantes da Horda abriram uma passagem montanhosa até o cânion para observar os movimentos das tropas Ferro Negro e garantir rotas estratégicas até a Montanha Rocha Negra, que tem enorme importância estratégica.",al={"por que a horda está aqui","ligação entre karrath e o cânion","presença da horda"}},{q="Há entradas de masmorras ou raides dentro da Garganta Abrasadora?",a="Não há portais de instância diretamente no próprio cânion, mas a entrada ao sul leva direto à Montanha Rocha Negra. Essa montanha abriga o Abismo Rocha Negra, o Pico da Rocha Negra e as passagens profundas que levam ao Núcleo Derretido.",al={"instâncias da garganta abrasadora","masmorras na garganta abrasadora","onde fica o núcleo derretido"}}},fp="13,249,20.456.0,29.498.0,39.549.0,51.376.0,44.359.0,33.260.0,50.303.0,45.225.0,62.207.0"}
P.entries["zone:shadowfang"] = {n="Bastilha da Presa Negra",s="Erguida sobre os penhascos escarpados acima do Vilarejo Lenhardente, a Bastilha da Presa Negra é a sombria fortaleza do mago renegado do Kirin Tor, o Arquimago Arugal. Outrora a propriedade ancestral do Barão Silverlaine, o bastião agora fervilha de feras worgens selvagens e dos fantasmas atormentados de seus defensores massacrados. Para os aventureiros que atravessam o sul da Floresta de Pinhaprata, a bastilha representa o epicentro sombrio do flagelo bestial que consome a região.",h="Erguida sobre os penhascos escarpados acima do Vilarejo Lenhardente, a Bastilha da Presa Negra é a sombria...",kw={"arugal","fenrus","lenhardente","sfk","presa negra","silverlaine","floresta de pinhaprata","floraval","worgen"},ang={["class:Mage"]="A tragédia da Presa Negra serve como um aviso sombrio do que acontece quando um mago do Kirin Tor se intromete em invocações extradimensionais além do controle mortal.",["class:Paladin"]="O espírito inquieto do Comandante Floraval permanece como uma dolorosa lembrança dos defensores paladinos caídos cujos juramentos sagrados foram deturpados pela morte.",["class:Warlock"]="As energias sombrias, os emissários do caos e as feitiçarias vis dentro da bastilha atraem o interesse de praticantes que buscam recuperar relíquias antigas, como o Orbe de Soran'ruk.",["faction:Horde"]="Os Renegados consideram as matilhas de Arugal uma ameaça imediata a seu território ainda incipiente na Floresta de Pinhaprata, o que torna a bastilha um alvo prioritário para os sicários e a Real Sociedade de Boticários."},sec={{t="A Queda da Dinastia Silverlaine",b="Antes de ser envolta em pesadelo, a Presa Negra era conhecida como Bastilha Silverlaine, uma sede nobre guarnecida pelo piedoso Comandante Floraval. Quando o Flagelo varreu Lordaeron durante a Terceira Guerra, os magos de Dalaran tombaram aos montes. Desesperado para conter os mortos em ascensão, o Arquimago Arugal desafiou a liderança do Kirin Tor e aprofundou-se nas pesquisas do mago Ur, invocando worgens extradimensionais para virar a maré. As feras invocadas estraçalharam os mortos-vivos, mas rapidamente fugiram a todo o controle mortal, irrompendo pelo sul da Floresta de Pinhaprata e invadindo o bastião. O Barão Silverlaine e toda a sua corte foram massacrados, condenados a assombrar os salões de pedra ao lado dos monstros selvagens que invadiram seu lar."},{t="Os Filhos de Arugal",b="Arruinado pela culpa e pela loucura, Arugal refugiou-se nas ameias manchadas de sangue, adotando os vorazes homens-lobo como seus amados 'filhos' e batizando o castelo de Bastilha da Presa Negra. Nas profundezas dos poleiros de pedra, matilhas lupinas e cães sombrios prosperam sob o comando de adestradores como o Mestre dos Lobos Nandos, vigiados pela colossal besta lupina de Arugal, Fenrus, o Devorador. Fora das muralhas, a maldição não parou; o vizinho Vilarejo Lenhardente permanece preso em um aterrorizante ciclo noturno, com seus residentes caminhando como homens durante o dia e caçando como worgens vorazes sob o luar, atrelados inexoravelmente ao arquimago louco empoleirado nas alturas."},{t="O Ataque dos Renegados",b="Reconhecendo a grave ameaça que Arugal representa para seu domínio na Floresta de Pinhaprata, a Grande Dama Sylvana Correventos despachou a Real Sociedade de Boticários e sicários de elite para erradicar a fonte da maldição dos worgens. As equipes de infiltração sofreram baixas brutais dentro das masmorras, mas os heróis da Horda que atenderam ao chamado de O Sepulcro acabam por invadir a torre mais alta. Derrubar o Arquimago põe um fim formal ao mestre da matilha, rompendo a mente que orquestra a propagação das feras pela natureza e reivindicando sua cabeça como prova da vingança de Lordaeron."}},faq={{q="O que acontece quando o Arquimago Arugal é derrotado?",a="Matar Arugal decapita a força central que controla as matilhas de worgens no sul da Floresta de Pinhaprata. Aventureiros da Horda entregam sua cabeça decepada a Dalar Tessalba em O Sepulcro sob as ordens da Grande Dama Sylvana Correventos. Embora sua morte rompa a vontade direta que comanda a matilha da Presa Negra, as feras selvagens e os vestígios fantasmagóricos que permanecem na bastilha e nos bosques ao redor continuam sendo um perigo persistente para os viajantes.",al={"desfecho de matar arugal","história da morte de arugal","o que acontece após a morte de arugal"}},{q="Por que Arugal invocou os worgens?",a="Durante a Terceira Guerra, os exércitos de Dalaran sofriam derrotas desastrosas contra o Flagelo. Magos caídos renasciam continuamente como soldados mortos-vivos do Lich Rei. Em busca de uma arma para virar a maré, Arugal utilizou as pesquisas arcanas do mago Ur para invocar worgens extradimensionais, acreditando que a ferocidade deles poderia deter o Flagelo.",al={"por que os worgens foram invocados","motivação de arugal","invocação de worgens em dalaran"}},{q="Quem foi o Barão Silverlaine?",a="O Barão Silverlaine foi o nobre humano que governou a bastilha e supervisionou o vilarejo vizinho de Lenhardente antes da Terceira Guerra. Quando as feras invocadas por Arugal escaparam do controle, invadiram a fortaleza e massacraram o barão, sua corte e seus guardas. O fantasma vingativo de Silverlaine ainda assombra os grandes salões de banquete, amaldiçoado a caminhar ao lado dos monstros que o mataram.",al={"história do barão silverlaine","senhor original da bastilha da presa negra"}},{q="Por que os moradores do Vilarejo Lenhardente são amistosos durante o dia?",a="Arugal submeteu os habitantes do vizinho Vilarejo Lenhardente à sua magia sombria. De dia, eles mantêm sua forma humana, mentes lúcidas e um comportamento pacífico com viajantes da Aliança. Ao pôr do sol, a maldição se manifesta, transformando toda a população em worgens selvagens leais ao arquimago louco na bastilha.",al={"humanos de lenhardente","maldição de lenhardente","por que lenhardente se transforma em worgens"}},{q="Quem é o Comandante Floraval?",a="O Comandante Floraval foi um paladino e o oficial militar responsável por defender a Bastilha Silverlaine. Quando os worgens tomaram a fortaleza, ele lutou até a morte. Seu espírito inquieto ainda patrulha os corredores superiores, apegando-se ao dever marcial mesmo na morte-vida.",al={"história de floraval","chefe paladino fantasma"}},{q="O que é O Livro de Ur?",a="O Livro de Ur é um tomo contendo as pesquisas de Ur, um arquimago de Dalaran que estudou entidades extradimensionais, incluindo os worgens. Arugal usou os escritos de Ur para realizar suas invocações desastrosas. A Real Sociedade de Boticários na Cidade Baixa busca o livro para entender a natureza das criaturas-lobo e sua magia bizarra.",al={"missão o livro de ur","história de ur"}}},fx={["4bfedcc6"]={q="O que é a Bastilha da Presa Negra?",a="A Bastilha da Presa Negra é um castelo assombrado empoleirado nos altos penhascos do sul da Floresta de Pinhaprata, com vista para o Vilarejo Lenhardente. Originalmente conhecida como Fortaleza Silverlaine, ela já serviu como uma fortaleza da Aliança guardando as fronteiras perto de Guilnéas. Hoje, ela permanece corrompida e envolta em névoas escuras, servindo como a fortaleza do Arquimago Arugal e sua progênie feral de worgens.",al={"o que é a bastilha da presa negra","fale sobre a bastilha da presa negra","saber sobre a bastilha da presa negra"}},["1d3b32c5"]={q="Quem construiu a Bastilha da Presa Negra?",a="A fortaleza era a sede do Barão Silverlaine, um nobre cuja família deteve o senhorio das terras vizinhas e do Vilarejo Lenhardente por muito tempo antes da Terceira Guerra. Sob seu governo, ela se manteve como um orgulhoso bastião humano, guardado pelo Comandante Floraval e soldados juramentados do reino.",al={"quem construiu a bastilha da presa negra","origem da bastilha da presa negra","quem fez a bastilha da presa negra"}},efb02893={q="Por que a Bastilha da Presa Negra está cheia de worgens?",a="Quando os worgens invocados se libertaram do controle do Kirin Tor, eles saquearam a floresta e sitiaram o castelo. Eles massacraram o Barão Silverlaine e sua família. Enlouquecido pela culpa sobre o que havia libertado, o Arquimago Arugal adotou as feras como seus próprios 'filhos', reivindicou a ruína para si e a renomeou como Bastilha da Presa Negra.",al={"por que há worgens aqui","por que os worgens na bastilha da presa negra","por que worgens dentro"}},["7d419eb0"]={q="Por que a Horda está interessada neste castelo?",a="Os worgens que vagam para fora da bastilha são uma praga desenfreada que ameaça o controle dos Renegados sobre a Floresta de Pinhaprata. De sua base no Sepulcro, os líderes Renegados perceberam que, enquanto Arugal comandar seus horrores lupinos das alturas do castelo, as terras vizinhas nunca estarão seguras.",al={"por que a horda se importa com a bastilha da presa negra","interesse da horda na bastilha da presa negra","por que vir à bastilha da presa negra"}},d6cbfc07={q="Quem me enviou aqui?",a="Comandantes Renegados no Sepulcro ordenaram o ataque para eliminar Arugal e descobrir o destino de seus batedores desaparecidos. Enquanto isso, a Real Sociedade de Boticários na Cidade Baixa enviou agentes para recuperar a pesquisa mágica de Ur da biblioteca do arquimago.",al={"quem me enviou à bastilha da presa negra","quem dá missões na bastilha da presa negra","quem quer arugal morto"}},a794fece={q="Estas terras agora são dos Renegados?",a="Os Renegados reivindicam o norte da Floresta de Pinhaprata, mas seu controle sobre o sul é intensamente disputado. A Bastilha da Presa Negra permanece firmemente sob o domínio de Arugal, enquanto vestígios do Flagelo, feras selvagens e assentamentos humanos sobreviventes disputam o governo da Dama Sombria por toda a região.",al={"a floresta de pinhaprata é terra dos renegados","sylvanas é dona disso","território renegado na bastilha da presa negra"}},b918d1de={q="Quem está no comando da Bastilha da Presa Negra?",a="O castelo responde inteiramente ao Arquimago Arugal. Enlouquecido pela Terceira Guerra, ele governa as torres superiores ladeado por seus monstruosos worgens e seu enorme worg de estimação, Fenrus, comandando a bastilha por meio de magia sombria.",al={"quem governa a bastilha da presa negra","quem está no comando lá dentro","mestre da bastilha da presa negra"}},ecad974c={q="Arugal é o chefe da bastilha?",a="Sim. Arugal é o mestre da Bastilha da Presa Negra. Ele orquestra a infestação de worgens por toda a Floresta de Pinhaprata e senta-se no pináculo da torre da bastilha como sua autoridade máxima.",al={"arugal é o chefe","chefe final da bastilha da presa negra","arugal mestre"}},["3b086809"]={q="Alguém estava no comando antes dele?",a="O Barão Silverlaine governava a bastilha quando ela era um reduto da Aliança. Ele e sua família governaram o castelo até que os worgens de Arugal romperam as muralhas e massacraram todos lá dentro durante a Terceira Guerra.",al={"quem governava antes de arugal","mestre anterior da bastilha da presa negra","antigo lorde da bastilha"}},["7f02160f"]={q="De onde vêm os worgens?",a="Eles são seres extradimensionais vorazes arrancados de outro plano. Desesperado para deter o Flagelo durante a Terceira Guerra, Arugal recorreu à pesquisa proibida do mago de Dalaran, Ur, e invocou essas feras de outro mundo para Azeroth.",al={"de onde vieram os worgens","origem dos worgens","fonte dos worgens"}},["4fa8e666"]={q="Arugal invocou os worgens sozinho?",a="Arugal realizou a invocação contra o conselho explícito de seus pares no Kirin Tor de Dalaran. Baseando-se pesadamente nos escritos de O Livro de Ur, ele forçou as entidades através de fronteiras planares.",al={"arugal agiu sozinho","quem ajudou a invocar worgens","invocação de arugal"}},a6a018be={q="Os worgen podem ser controlados?",a="Mal, e apenas através de magia sombria. Embora invocados para servir como aliados contra os mortos-vivos, eles se voltaram imediatamente contra seus invocadores. Arugal consegue direcionar alguns deles apenas porque sua mente perturbada os trata como família, usando encantamentos para forçar uma obediência frágil.",al={"os worgen podem ser controlados","controlando os worgen","os worgen são dóceis"}},["24ed31c3"]={q="O que aconteceu com os sicários Admeto e Vicente?",a="Os sicários Admeto e Vicente entraram na Bastilha da Presa Negra por ordem do Sepulcro para avaliar as forças de Arugal. Foram capturados pelos defensores da bastilha: Vicente foi aprisionado e executado no pátio, enquanto Admeto permaneceu nas masmorras, à espera de resgate.",al={"adamant e vincent","o que aconteceu com Os sicários","batedores renegados na bastilha da presa negra"}},cc7bdeae={q="Por que os sicários foram enviados à Bastilha da Presa Negra?",a="O comando dos Renegados precisava de informações precisas sobre a infestação de feras que ameaçava sua fronteira sul. Admeto e Vicente receberam a missão de se infiltrar na bastilha, descobrir quantos seguidores Arugal possuía e preparar o terreno para um ataque decisivo.",al={"por que enviar Os sicários","investigando a bastilha da presa negra","missão dos sicários"}},["4cfa60a4"]={q="Os sicários ainda estão vivos?",a="Vicente morreu após ser capturado. Admeto, porém, continua preso nas celas inferiores da bastilha e ainda pode ajudar os aventureiros da Horda que conseguirem alcançá-lo.",al={"vincent e adamant estão vivos","Os sicários sobreviveram","destino dos sicários"}},c6ee2849={q="Quem são os sicários?",a="Os sicários são assassinos e ladinos de elite dos Renegados, especializados em furtividade, espionagem e eliminações rápidas. Atuam como as adagas silenciosas da Cidade Baixa nas fronteiras de Lordaeron.",al={"o que é um sicário","quem são os sicários","sicários dos Renegados"}},["40c5e48b"]={q="A quem os sicários respondem?",a="Eles respondem através de uma rigorosa cadeia de comando governada por oficiais e comandantes dos Renegados estacionados por todos os territórios, servindo, em última análise, à vontade do conselho governante da Cidade Baixa.",al={"liderança dos sicários","quem comanda Os sicários","quem lidera Os sicários"}},["63a10ab0"]={q="Os sicários trabalham diretamente para Sylvana?",a="Sim. Todos sicários juram lealdade à Rainha Banshee, Grande Dama Sylvana Correventos. Eles integram sua rede pessoal de informações e eliminam ameaças aos mortos-vivos de livre-arbítrio em Lordaeron.",al={"Os sicários servem sylvanas","sylvanas e Os sicários","Os sicários e a rainha banshee"}},f68cd02f={q="Por que todos estão me enviando para a Bastilha da Presa Negra?",a="Porque o reconhecimento inicial dos Renegados colapsou completamente com a captura de seus Os sicários de elite. O covil de Arugal é traiçoeiro demais para a infantaria comum, exigindo aventureiros provados que possam atravessar tanto as feras quanto os espíritos vingativos.",al={"por que me enviar para a bastilha da presa negra","por que estou fazendo isso","por que um herói na bastilha da presa negra"}},ebbfbfb0={q="Sou o único que resta para fazer isso?",a="Os recursos dos Renegados na Floresta de Pinhaprata estão extremamente limitados, lutando contra gnolls Pele-podre, remanescentes do Flagelo e patrulhas de Dalaran. Com seus próprios batedores comprometidos, você e seus aliados são a única força capaz de invadir a bastilha.",al={"sou o único","não há mais ninguém para limpar a bastilha da presa negra","única escolha"}},["0f7e4add"]={q="Outros tentaram invadir a bastilha antes de mim?",a="Sim. Além dos sicários enviados em reconhecimento, investigadores do Kirin Tor, como o Feiticeiro Ashcrombe, entraram na bastilha para avaliar Arugal, mas acabaram capturados ou presos em seus salões amaldiçoados.",al={"outros tentaram a bastilha da presa negra","tentativas anteriores na bastilha da presa negra","quem tentou antes"}},["13386e7c"]={q="O que aconteceu com a Floresta de Pinhaprata?",a="A Floresta de Pinhaprata já foi um reino verdejante de pinheiros altivos de casca prateada protegidos pela Aliança. Quando o Flagelo varreu Lordaeron durante a Terceira Guerra, a praga definhou os bosques, colheitas foram queimadas e seu povo foi massacrado ou conduzido para trás da Muralha Greymane.",al={"história da floresta de pinhaprata","o que aconteceu com a floresta de pinhaprata","por que a floresta de pinhaprata está assim"}},["7c8f83a0"]={q="A Floresta de Pinhaprata era terra de Lordaeron?",a="Sim. A Floresta de Pinhaprata formava a borda oeste acidentada do Reino de Lordaeron, fazendo fronteira com Guilnéas ao sul. Suas propriedades e assentamentos estavam ligados à Aliança antes que a praga destruísse o reino.",al={"isso era lordaeron","história de lordaeron na floresta de pinhaprata","lordaeron era dona da floresta de pinhaprata"}},["91da6ffd"]={q="Por que a Floresta de Pinhaprata está tão vazia agora?",a="Entre a invasão do Flagelo, o fechamento da grande muralha de Guilnéas e a maldição desenfreada dos worgen de Arugal, a população viva foi massacrada, amaldiçoada ou fugiu para o exterior. Os poucos que restam se apegam desesperadamente a aldeias contestadas como Vilasombra.",al={"por que a floresta de pinhaprata está vazia","floresta de pinhaprata deserta","por que as ruínas da floresta de pinhaprata"}},["2ee73ad9"]={q="Por que Arugal trouxe worgen para a Floresta de Pinhaprata em primeiro lugar?",a="Quando o Flagelo dos mortos-vivos marchou para o sul, os magos de Dalaran morriam aos montes, apenas para se erguerem novamente a serviço do Lich Rei. Arugal acreditava que aliados invocados de outras dimensões poderiam subjugar os mortos-vivos onde exércitos mortais convencionais haviam falhado.",al={"por que trazer worgen para a floresta de pinhaprata","razão de arugal invocar os worgen","por que invocar worgen aqui"}},["671a79f5"]={q="Quem Arugal estava tentando impedir?",a="Ele os invocou especificamente para aniquilar os exércitos de mortos-vivos do Flagelo, que cresciam ao massacrar e erguer cada soldado e mago que caía em batalha.",al={"contra quem arugal estava lutando","inimigo de arugal","contra quem arugal invocou os worgen"}},eeb57b84={q="O plano de Arugal funcionou contra o Flagelo?",a="Taticamente, sim — os worgen despedaçaram os mortos-vivos sem esforço. Mas estrategicamente, foi uma catástrofe. Os homens-lobo ferozes não podiam ser controlados, voltaram-se contra soldados humanos e magos, e espalharam uma maldição mortal por toda a região.",al={"os worgen venceram o flagelo","a invocação funcionou","sucesso dos worgen contra o flagelo"}},["2bfe7e75"]={q="Os worgen na bastilha são os mesmos que invadiram Vilasombra?",a="Sim. As alcateias de Arugal, incluindo a alcateia Presa Negra e a alcateia Raiva Lunar, compartilham a mesma origem amaldiçoada. As feras que perseguem os salões do castelo são a prole pessoal de Arugal, intimamente ligadas à maldição que aflige os aldeões lá embaixo.",al={"os worgen da bastilha da presa negra são de vilasombra","worgen de vilasombra e bastilha da presa negra","mesma alcateia worgen"}},b78b86f3={q="O que aconteceu com os aldeões de Vilasombra?",a="Os aldeões sobreviveram à Terceira Guerra apenas para serem enredados pela magia sombria de Arugal. Embora pareçam humanos normais durante a luz do dia, o pôr do sol os transforma em worgen selvagens e sedentos de sangue, leais ao arquimago louco.",al={"o que aconteceu com o povo de vilasombra","destino de vilasombra","habitantes de vilasombra"}},["39fbc1b5"]={q="Os aldeões de Vilasombra também estão amaldiçoados?",a="Sim. Eles são vítimas da maldição licantrópica worgen. De dia, mantêm suas mentes e negociam pacificamente com viajantes da Aliança; à noite, a maldição arranca sua humanidade, transformando-os em feras vorazes.",al={"vilasombra está amaldiçoada","maldição de vilasombra","os aldeões estão infectados"}},d6e89a88={q="Quem são os fantasmas dentro da Bastilha da Presa Negra?",a="Eles são os espíritos inquietos do Barão Silverlaine, do Comandante Floraval e dos antigos habitantes do castelo. Mortos no ataque surpresa dos worgen, suas almas permanecem presas às pedras em ruínas pelo tormento e pela dor.",al={"fantasmas na bastilha da presa negra","quem são os espíritos na bastilha da presa negra","espectros da bastilha da presa negra"}},["0a399272"]={q="Os fantasmas são os antigos servos da bastilha?",a="Sim. De cozinheiros fantasmagóricos e atendentes sombrios a antigos guardas, os defensores espectrais que vagam pelos corredores são os criados massacrados que serviram o Barão Silverlaine em vida.",al={"fantasmas são antigos servos","fantasmas dos servos do castelo","servos de silverlaine"}},["3f532512"]={q="Por que os fantasmas não podem descansar?",a="O puro horror do massacre, combinado com a pesada magia das sombras que satura a bastilha, impede a libertação deles. Em sua angústia perpétua, eles atacam com ódio profano qualquer intruso vivo que perturbe seus túmulos.",al={"por que os fantasmas não descansam","por que espíritos assombram a bastilha da presa negra","agitação dos fantasmas na bastilha da presa negra"}},["59c03d52"]={q="Arugal trabalha para o Flagelo?",a="Não. Arugal despreza o Flagelo; ele invocou os worgens justamente para destruí-los. Embora tenha enlouquecido, sua lealdade pertence aos seus 'filhos' e não ao Lich Rei.",al={"arugal é do flagelo","arugal trabalha para o flagelo","arugal serve ao flagelo"}},["99eb22e3"]={q="O Lich Rei controla Arugal?",a="Não. A loucura de Arugal é totalmente autoinfligida, nascida da culpa e da magia planar, e não do controle telepático do Trono de Gelo. Ele opera de forma independente como mestre de seu próprio domínio sombrio.",al={"o lich rei controla arugal","lich rei arugal","controle mental de arugal"}},["501c4a9b"]={q="A maldição termina depois que Arugal morre?",a="Não. Matar Arugal decapita a liderança da Bastilha da Presa Negra, mas a maldição worgen já infectou o sangue de mortais por toda a floresta. A aflição persiste muito tempo depois da queda do arquimago.",al={"a maldição worgen termina","a maldição worgen desaparecerá","lenhardente está curado"}},["6cb01af1"]={q="Os Renegados tomarão a Bastilha da Presa Negra?",a="Por enquanto, os Renegados estão satisfeitos em eliminar a ameaça à sua fronteira sul e recuperar O Livro de Ur. A ruína permanece como uma casca sombria e assombrada que vigia a floresta, em vez de um posto avançado guarnecido.",al={"os renegados tomarão a bastilha da presa negra","os renegados capturam a bastilha da presa negra","quem controla a bastilha da presa negra depois"}},["3f22b397"]={q="Como fui parar na Bastilha da Presa Negra?",a="Você seguiu o rastro de terror pela Floresta de Pinhaprata até os penhascos que vigiam o Vilarejo Lenhardente. Se você serve a Horda, provavelmente foi enviado do Sepulcro ou da Cidade Baixa para o sul para investigar a ameaça worgen que sufoca a região. Se você luta pela Aliança, rumores sobre as florestas amaldiçoadas, relíquias sagradas perdidas ou o Kirin Tor caído levaram você para o fundo do território hostil dos Renegados. Escalando as encostas sinuosas além dos portões do Vilarejo Lenhardente, você passou por bestas-lobo vorazes e forçou a antiga entrada da bastilha para entrar no covil do arquimago louco.",al={"como cheguei aqui","como chego na bastilha da presa negra","como encontrei este lugar"}},["31a8c552"]={q="O que devo fazer na Bastilha da Presa Negra?",a="Seu objetivo final é lutar pelos corredores assombrados e derrubar o Arquimago Arugal, encerrando seu reinado distorcido sobre Pinhaprata. No caminho, você deve abater os worgens que espreitam pelos pátios e acalmar os espíritos inquietos do Barão Silverlaine e seus criados assassinados. Se estiver agindo em nome dos Renegados, sua tarefa é recuperar O Livro de Ur e descobrir o destino dos Carrascos desaparecidos enviados lá dentro. Campeões, paladinos e bruxos da Aliança buscam artefatos de poder perdidos, armamentos sagrados e retribuição contra a magia das sombras que envenena a terra.",al={"o que estou fazendo aqui","por que estou aqui","qual é meu objetivo na bastilha da presa negra"}}},fp="15,249,31.608.0,17.575.0,19.531.1,46.300.1,33.314.0,26.353.0,59.258.0,28.263.0,23.300.0"}
P.entries["zone:shendralas"] = {n="Shen'dralas",s="Shen'dralas é uma região selvagem, acidentada e disputada, situada entre Feralas, Mulgore e o sudeste de Desolação. Dominada por antigos vestígios élficos noturnos e fronteiras conturbadas, ela serve como uma encruzilhada volátil onde centauros invasores, proscritos deslocados e javatuscos hostis colidem.",h="Shen'dralas é uma região selvagem, acidentada e disputada, situada entre Feralas, Mulgore e o sudeste de...",kw={"refúgio dos costagulha","desolação","evenshade overlook","feralas","lake dumont","front dos magram","mulgore","esconderijo dos proscritos","shendralas","vale dos ossos"},ang={["faction:Alliance"]="Uma região selvagem remota e disputada que oferece rotas alternativas entre Feralas e a região central de Kalimdor, repleta de perigos que exigem vigilância constante.",["faction:Horde"]="Posicionada logo além dos limites do sul de Mulgore, manter os Magram e os javatuscos contidos aqui é vital para proteger as fronteiras da Horda.",["race:NightElf"]="O nome evoca a antiga história dos Altaneiros de Eldre'Thalas, atraindo a atenção de sentinelas receosas com o uso imprudente da magia arcana no sul de Kalimdor.",["race:Tauren"]="Com a região fazendo fronteira com Mulgore e Desolação, a agressividade dos javatuscos e centauros ao longo dessas cordilheiras representa uma ameaça direta aos campos de caça ancestrais próximos."},sec={{t="Uma Fronteira em Turbulência",b="Escondida nas elevações a sudeste de Desolação e margeada por Mulgore e Feralas, Shen'dralas é uma fronteira rústica, muito distante das capitais das principais facções. Suas passagens escarpadas e enclaves ocultos abrigam grupos desesperados que lutam pela existência no limiar da selvagem Kalimdor. De pontos de observação isolados como Evenshade Overlook a refúgios sem lei como o Esconderijo dos Proscritos, a zona é definida por aqueles que desejam vigiar sem serem vistos ou permanecer esquecidos."},{t="Centauros, Javatuscos e Ruínas Antigas",b="A terra traz a marca distinta do legado altaneiro que lhe deu o nome, mas está longe de ser pacífica. O conflito dos centauros transborda pelo Front dos Magram, mantendo antigas rixas de sangue bem vivas ao longo de suas fronteiras. Enquanto isso, javatuscos invasores mantêm redutos fortificados, como o Refúgio dos Costagulha, transformando cada desfiladeiro sombrio em território disputado para qualquer viajante de passagem."},{t="O Vale dos Ossos",b="Partindo em direção a noroeste rumo a Desolação fica o Vale dos Ossos, um corredor sombrio que serve como a principal rota de acesso terrestre a Shen'dralas. Alvejada pelo sol e pelo vento, essa passagem permanece como uma dura lembrança das lutas violentas que ecoam constantemente por esses penhascos."}},faq={{q="Onde fica Shen'dralas?",a="Shen'dralas fica a sudeste de Desolação, aninhada entre as fronteiras de Feralas e Mulgore. Os viajantes que chegam a pé costumam entrar a partir de Desolação, passando pelo Vale dos Ossos.",al={"onde fica shendralas","localização de shendralas","como chegar a shendralas"}},{q="Shen'dralas é controlada pela Aliança ou pela Horda?",a="Nenhuma das facções detém domínio aqui. Shen'dralas é uma fronteira disputada, povoada por centauros errantes, javatuscos hostis, proscritos e acampamentos isolados.",al={"shendralas é da horda","shendralas é da aliança","quem controla shendralas"}},{q="Quais assentamentos ou marcos importantes existem aqui?",a="Entre os marcos proeminentes estão o Vale dos Ossos, o Refúgio dos Costagulha, Evenshade Overlook, o Front dos Magram, o Esconderijo dos Proscritos e a própria extensão central de Shen'dralas.",al={"subzonas de shendralas","marcos em shendralas","pontos de interesse em shendralas"}},{q="Por que há centauros aqui?",a="As guerras territoriais dos centauros estendem-se das planícies de Desolação diretamente para a região ao longo do Front dos Magram, onde o clã enfrenta defensores locais e facções rivais.",al={"centauros em shendralas","front dos magram","por que os magram estão aqui"}},{q="O que é o Refúgio dos Costagulha?",a="O Refúgio dos Costagulha é um entreposto fortificado mantido por javatuscos Costagulha, que estabeleceram uma base obstinada ao longo das bordas da zona.",al={"refúgio dos costagulha","javatuscos em shendralas"}},{q="Qual é a ligação entre esta zona e Lake Dumont?",a="Geograficamente, a vastidão selvagem de Shen'dralas abrange o território montanhoso onde o isolado Lake Dumont fica escondido em antigos mapas de reconhecimento.",al={"lake dumont","história do mapa de shendralas"}}},fp="11,141,23.322.0,36.313.0,19.222.0,29.144.0,55.152.0,45.155.0,27.159.0,28.132.0,57.115.0"}
P.entries["zone:silithus"] = {n="Silithus",s="Silithus é um deserto desolado e varrido pelo vento localizado no extremo sudoeste de Kalimdor. Abaixo de suas areias áridas jazem vastas colônias de silithids insetoides e as antigas ruínas de Ahn'Qiraj, seladas há um milênio atrás da formidável Muralha do Escaravelho. Hoje, os druidas do Círculo Cenariano mantêm uma vigília sob cerco contra enxames rastejantes e cultistas do apocalipse.",h="Silithus é um deserto desolado e varrido pelo vento localizado no extremo sudoeste de Kalimdor.",kw={"ahn'qiraj","forte cenariano","colme'ashi","colme'régia","colme'zora","palanque do escaravelho","muralha do escaravelho","silithid","silithus","twilight's hammer"},ang={["class:Druid"]="Como o coração das operações do Círculo Cenariano no sul de Kalimdor, Silithus convoca druidas para deter a corrupção da terra e confrontar as proles antinaturais que ameaçam o equilíbrio da natureza.",["profession:Herbalism"]="Apesar do terreno desértico rigoroso, maravilhas botânicas raras florescem aqui, incluindo Sálvia-prata-da-montanha, Folha-de-sonho, Ervassol e o excepcionalmente valioso Lótus Preto.",["profession:Mining"]="As rochas áridas e os túneis de insetos de Silithus abrigam alguns dos depósitos de Tório mais ricos do mundo, incluindo veios raros cobertos de lodo escondidos dentro das colmeias dos silithids.",["race:NightElf"]="Silithus é o campo de repouso sombrio onde seus ancestrais sangraram durante a Guerra das Areias Movediças, sacrificando milhares para selar os portões de Ahn'Qiraj."},sec={{t="A Fronteira do Deserto",b="Chegar a Silithus exige navegar pela selva primordial da Cratera Un'Goro e subir uma passagem larga e rochosa situada em seu canto noroeste. A transição é drástica: o crescimento primordial e luxuriante desaparece em uma vasta extensão de dunas movediças, pedra irregular e colmeias imponentes artificiais. Água é praticamente inexistente, e os ventos carregam o zumbido de asas de insetos e a areia sussurrante. O Círculo Cenariano mantém o Forte Cenariano próximo ao centro do deserto, servindo como o único baluarte de civilização e abrigo para viajantes, pesquisadores e guerreiros que enfrentam as terras devastadas hostis."},{t="Ecos das Areias Movediças",b="Há mil anos, esta extensão árida serviu como campo de batalha para a Guerra das Areias Movediças. Um exército aliado de elfos noturnos e grandes revoadas de dragões lutou desesperadamente para repelir os Qiraji, um império insetoide insidioso gerado da antiga civilização Aqiri. Quando a vitória total provou-se impossível, os defensores selaram os enxames dentro de sua fortaleza usando a Muralha do Escaravelho e o encantado Palanque do Escaravelho. Enquanto os portões monumentais resistiam, túneis subterrâneos permitiram que os silithids bestiais cavassem para fora, estabelecendo colônias extensas como Colme'Ashi, Colme'Zora e Colme'Régia por todas as areias."},{t="Uma Tempestade Convergente",b="O culto apocalíptico Martelo do Crepúsculo se entrincheirou em vários postos avançados fortificados, invocando terrores elementais e venerando o poder sombrio que dorme sob Ahn'Qiraj. Observadores do Círculo Cenariano monitoram as colônias de silithids em expansão pelo deserto e a antiga ameaça atrás da Muralha do Escaravelho."}},faq={{q="Como chego a Silithus a pé?",a="Viaje para o canto noroeste da Cratera Un'Goro. Perto da curva sinuosa do rio, entre dois pilares de pedra natural proeminentes, uma estrada de terra inclinada leva para cima através da parede montanhosa da cratera diretamente para o deserto de Silithus.",al={"entrada de silithus","como chegar a silithus","caminho para silithus"}},{q="O que é a Muralha do Escaravelho?",a="A Muralha do Escaravelho é uma barreira maciça e encantada no sul de Silithus. Foi erguida há mil anos pelos elfos noturnos e pelas revoadas de dragões durante a Guerra das Areias Movediças para aprisionar o malévolo império Qiraji dentro de Ahn'Qiraj.",al={"portão de ahn'qiraj","muralha do escaravelho","o grande muro em silithus"}},{q="Quem administra o Forte Cenariano?",a="O Forte Cenariano é um posto avançado estabelecido e administrado pelo Círculo Cenariano. Seus druidas e guardiões aliados observam os enxames de silithids que avançam, investigam ruínas antigas e recebem viajantes neutros tanto da Aliança quanto da Horda.",al={"quem está no forte cenariano","facção do forte cenariano","forte cenariano amigável"}},{q="O que são os montes gigantes de insetos por toda a zona?",a="São as principais colmeias subterrâneas dos silithids: Colme'Ashi, Colme'Zora e Colme'Régia. Cada colmeia é uma extensa rede de túneis abrigando castas distintas de criaturas insetoides que servem às vontades trancadas atrás de Ahn'Qiraj.",al={"colmeias de silithus","colmeias de insetos em silithus","colme'ashi colme'zora"}},{q="O que o Martelo do Crepúsculo está fazendo aqui?",a="O culto do Martelo do Crepúsculo mantém várias bases fortificadas em Silithus, incluindo o Acampamento do Crepúsculo e o Posto Crepúsculo. Eles conduzem rituais vis para invocar elementais e adoram as entidades antigas e malévolas sepultadas atrás da Muralha do Escaravelho.",al={"cultistas do crepúsculo em silithus","posto avançado do crepúsculo silithus","por que o twilight's hammer está em silithus"}}},fp="8,245,19.408.0,28.509.0,18.272.0,33.207.0,24.219.0,23.205.0,49.212.0,41.243.0"}
P.entries["zone:silverpine"] = {n="Floresta de Pinhaprata",s="A Floresta de Pinhaprata é uma mata sombria e envolta em névoa que se estende pela costa oeste de Lordaeron, entre as Clareiras de Tirisfal e a fechada Muralha Greymane. Assombrada pelas cicatrizes persistentes da praga do Flagelo, ela serve como a disputada fronteira sul dos Renegados. Os viajantes aqui enfrentam worgens ferozes vagando pelas sombras, gnolls enfermos e enclaves humanos hostis.",h="A Floresta de Pinhaprata é uma mata sombria e envolta em névoa que se estende pela costa oeste de Lordaeron...",kw={"lenhâmbar","arugal","ilha de fenris","muralha greymane","vilarejo lenhardente","rot hide","o sepulcro","bastilha da presa negra","floresta de pinhaprata"},ang={["class:Mage"]="A presença de Lenhâmbar e a queda do Arquimago Arugal na loucura lupina tornam Pinhaprata um conto sombrio de advertência sobre a magia do Kirin Tor que deu desastrosamente errado.",["faction:Alliance"]="Exploradores da Aliança encontrarão uma floresta profundamente hostil, interrompida apenas por uma frágil guarnição de Dalaran em Lenhâmbar e pelos trágicos aldeões amaldiçoados do Vilarejo Lenhardente.",["race:Undead"]="Pinhaprata representa a linha de frente imediata da expansão dos Renegados ao sul das Clareiras de Tirisfal, onde a Sociedade Real dos Boticários testa novas misturas e a Guarda Negra combate agentes remanescentes do Flagelo."},sec={{t="Uma Fronteira Assombrada",b="Outrora celebrada como uma exuberante maravilha de Lordaeron pela qual nobres viajantes seguiam rumo a Capital, a Floresta de Pinhaprata definhou sob o impacto da Terceira Guerra. Névoas fantasmagóricas serpenteiam entre pinheiros agonizantes de casca prateada, e fazendas em ruínas jazem abandonadas à natureza selvagem. Ao norte ficam as Clareiras de Tirisfal, enquanto a margem leste faz fronteira com o Espelho de Lordaeron. Ao sul ergue-se a imponente e fechada Muralha Greymane, isolando o reino isolacionista de Guilnéas do caos ao redor. Os Renegados mantêm seu entreposto central n'O Sepulcro, lutando para proteger os bosques de inimigos por todos os lados."},{t="Os Worgens e a Presa Negra",b="O perigo mais infame de Pinhaprata é a maldição dos worgens. No alto da floresta a sudoeste fica a Bastilha da Presa Negra, antiga sede do Barão Silverlaine, hoje dominada pelo arquimago louco de Dalaran, Arugal. Buscando repelir o Flagelo durante a Terceira Guerra, Arugal evocou feras-lobos extradimensionais. As criaturas se voltaram contra seus invocadores, espalhando uma maldição licantrópica pelos bosques ao sul. No Vilarejo Lenhardente, aldeões de aparência humana comum cuidam de seus afazeres durante o dia, mas transformam-se em worgens selvagens sob o céu noturno."},{t="Enclaves Rivais e o Flagelo",b="O domínio dos Renegados sobre Pinhaprata é fortemente disputado tanto por facções vivas quanto mortas-vivas. A leste, na Ilha de Fenris, Thule Corvinalle lidera remanescentes do Flagelo enquanto comanda os gnolls Rot Hide assolados pela peste que infestam as fazendas do norte. No sul, magos humanos de Dalaran mantêm o assentamento fortificado de Lenhâmbar, conduzindo pesquisas místicas e opondo-se à expansão dos Renegados. A Sociedade Real dos Boticários e o Alto-executor Hadrec n'O Sepulcro travam uma campanha brutal e multifacetada para eliminar essas ameaças e testar novas e virulentas pragas."}},faq={{q="O que é a Muralha Greymane na fronteira sul?",a="A Muralha Greymane é uma colossal barreira de pedra erguida pelo Rei Genn Greymane para isolar completamente o seu reino de Guilnéas do restante de Lordaeron. Quando o Flagelo devastou o continente durante a Terceira Guerra, Guilnéas trancou seus portões e recusou ajuda externa, deixando as terras ao norte da muralha — incluindo o sul de Pinhaprata — entregues à própria sorte.",al={"por que tem uma muralha gigante","historia da muralha greymane","portao para guilneas"}},{q="Por que os habitantes do Vilarejo Lenhardente atacam à noite?",a="Os habitantes do Vilarejo Lenhardente sofrem com a maldição dos worgens do Arquimago Arugal. De dia, mantêm a forma humana e suas rotinas diárias, permanecendo amigáveis com a Aliança. Quando a lua nasce, a maldição ganha força, transformando toda a população em worgens selvagens e sanguinários que atacam com violência qualquer um por perto.",al={"misterio do vilarejo lenhardente","worgen de vilarejo lenhardente","por que humanos de lenhardente sao hostis a noite"}},{q="Quem é Thule Corvinalle?",a="Thule Corvinalle é um poderoso necromante a serviço do Flagelo. Operando a partir do Castelo Fenris na Ilha de Fenris, dentro do Espelho de Lordaeron, ele comanda legiões de mortos-vivos e exerce controle sobre os enfermos gnolls Rot Hide pelo leste de Pinhaprata, ameaçando diretamente o flanco oriental dos Renegados.",al={"quem lidera a ilha de fenris","historia de thule corvinalle","flagelo na ilha de fenris"}},{q="Por que Dalaran está ocupando Lenhâmbar?",a="Lenhâmbar é mantida por magos de Dalaran liderados pelo Arquimago Ataeric. Operando na vila, esses magos humanos monitoram os movimentos dos Renegados, estudam as aflições mágicas que assolam a floresta e buscam conter o surto próximo de worgens que se espalha a partir da Bastilha da Presa Negra.",al={"magos de lenhambar","por que a alianca esta em lenhambar","dalaran em pinhaprata"}},{q="O que é O Sepulcro?",a="O Sepulcro é o principal posto avançado militar e ponto de trânsito dos Renegados na Floresta de Pinhaprata. Sob o comando do Alto-executor Hadrec, serve como base de operações para patrulhas da Guarda Negra, batedores Rastreadores da Morte e para a Sociedade Real dos Boticários na luta para proteger a floresta.",al={"cidade da horda em pinhaprata","onde fica o ponto de voo","historia do sepulcro"}},{q="Jogadores da Aliança podem fazer missões na Floresta de Pinhaprata?",a="A Floresta de Pinhaprata não possui centros de missões ou cidades amigáveis para a Aliança; todas as missões locais pertencem com exclusividade à Horda. Aventureiros da Aliança geralmente só entram na floresta ao viajar de Costa Sul para explorar a Bastilha da Presa Negra ou combater forças hostis dos Renegados.",al={"pinhaprata e so para horda","missoes da alianca em pinhaprata","alianca pode ir para pinhaprata"}}},fx={["21fc6836"]={q="O que é a Floresta de Pinhaprata?",a="A Floresta de Pinhaprata é uma vasta e antiga floresta ao longo da costa oeste acidentada de Lordaeron, diretamente ao sul das Clareiras de Tirisfal e delimitada a leste pelo Espelho de Lordaeron. Antes uma floresta exuberante e verdejante protegida pela Aliança, agora ela está envolta em névoas fantasmagóricas, pinheiros pálidos e doentios, e um silêncio sinistro interrompido apenas por uivos distantes. Os Renegados dominam o norte a partir do Sepulcro, mas sua reivindicação é constantemente contestada por remanescentes do Flagelo, gnolls selvagens da Couro Podre, magos de Dalaran e os worgens amaldiçoados da Bastilha da Presa Negra.",al={"o que é pinhaprata","fale sobre pinhaprata","história da floresta de pinhaprata"}},["01503e92"]={q="O que aconteceu na Floresta de Pinhaprata?",a="Pinhaprata antigamente lembrava a natureza intocada das Terras Agrestes, mas a Terceira Guerra a arruinou. Quando o Flagelo do Lich Rei varreu o sul, exércitos de mortos-vivos incendiaram fazendas, massacraram a população rural e contaminaram a terra com a praga da morte-viva. O Rei Genn Greymane selou Guilnéas atrás de sua enorme muralha, abandonando terras ao norte como o Vilarejo Lenhardente e Lenhâmbar. Para repelir o Flagelo, o Arquimago Arugal invocou worgens selvagens, mas a maldição saiu do controle. Com Lordaeron despedaçada, as florestas devastadas tornaram-se um campo de batalha contestado.",al={"história de pinhaprata","o que aconteceu aqui em pinhaprata","queda de pinhaprata"}},b9edb2aa={q="Quem costumava viver aqui antes dos Renegados?",a="Antes da Terceira Guerra, Pinhaprata era habitada por fazendeiros, mineiros e soldados humanos de Lordaeron e Guilnéas. Assentamentos do sul, como o Vilarejo Lenhardente e Lenhâmbar, ficaram do lado de fora quando Guilnéas se selou atrás da Muralha Greymane. A Ilha de Fenris abrigava uma movimentada guarnição militar de Lordaeron no Castelo Fenris. A maioria desses antigos habitantes pereceu durante a invasão do Flagelo, fugiu para o sul em direção à muralha selada, ou sucumbiu à morte-viva e à maldição worgen.",al={"quem viveu em pinhaprata antes","antigos moradores de pinhaprata","habitantes do passado de pinhaprata"}},["5b2addb4"]={q="Por que a floresta parece tão morta?",a="A floresta carrega as cicatrizes profundas e persistentes da Terceira Guerra. Pinhaprata marca a extensão mais ao sul onde a praga da morte-viva do Flagelo corrompeu visivelmente a flora, drenando a vitalidade do solo e deixando os antigos pinheiros de casca prateada pálidos, doentios e perdendo agulhas contaminadas. Com Lordaeron destruída e Guilnéas isolada, nenhum cuidador permaneceu para curar os bosques devastados ou cuidar das terras cultiváveis queimadas, permitindo que névoas frias e a podridão se instalassem sobre a floresta.",al={"por que pinhaprata está morrendo","por que pinhaprata parece morta","árvores contaminadas de pinhaprata"}},["67376895"]={q="A Floresta de Pinhaprata é perigosa?",a="Extremamente perigosa. Predadores selvagens como ursos contaminados, aranhas gigantes e worgs ferozes rondam sob as árvores. Gnolls da Couro Podre, assolados pela praga, massacram violentamente viajantes ao longo das estradas, enquanto magos humanos de Dalaran fortificam Lenhâmbar contra a intrusão da Horda. Ao sul, os worgens Fúria da Lua selvagens aterrorizam os vales sob o domínio do Arquimago Arugal. Fora do santuário fortificado do Sepulcro, a sobrevivência exige vigilância constante.",al={"quão perigosa é pinhaprata","ameaças em pinhaprata","é seguro aqui"}},["6dcc337b"]={q="Por que a Horda me enviou para Pinhaprata?",a="Você foi enviado para o sul das Clareiras de Tirisfal para reforçar a fronteira dos Renegados. A Cidade Baixa considera Pinhaprata vital para garantir sua fronteira sul, mas seu controle é frágil e está sobrecarregado. O Alto-executor Hadrec e a Guarda da Morte precisam de campeões capazes para repelir necromantes invasores do Flagelo, eliminar gnolls hostis, monitorar as manobras secretas de Dalaran e conter os worgens sedentos de sangue que ameaçam invadir as florestas.",al={"por que estou em pinhaprata","chegada da horda em pinhaprata","por que me enviaram aqui"}},ab9ff98b={q="Isso ainda é terra dos Renegados?",a="Os Renegados reivindicam Pinhaprata como território soberano da Cidade Baixa, mas seu controle é fortemente contestado. Embora mantenham domínio firme sobre o norte de Pinhaprata e o refúgio fortificado do Sepulcro, eles não detêm domínio absoluto sobre toda a floresta. Gnolls hostis da Couro Podre dominam as águas orientais, magos de Dalaran ocupam Lenhâmbar e os worgens selvagens de Arugal dominam as áreas do sudoeste.",al={"os renegados são donos de pinhaprata","quem controla pinhaprata","território renegado em pinhaprata"}},["858ebaa5"]={q="Quem construiu o Sepulcro?",a="Antes da Terceira Guerra, o Sepulcro era simplesmente um cemitério humano grande e silencioso e uma cripta à beira da estrada construída pelo povo de Lordaeron para sepultar seus mortos ao longo da rodovia oeste. Após a queda de Lordaeron, os Renegados sobreviventes tomaram os terrenos do cemitério e reestruturaram a cripta em um posto militar fortificado, estação de caravanas e quartel-general logístico para suas operações no sul.",al={"quem criou o sepulcro","origem do sepulcro","história do sepulcro"}},f51f7d3d={q="Por que os Renegados estão baseados no Sepulcro?",a="Aninhado de forma defensável nas colinas ocidentais, o Sepulcro oferece aos Renegados um ponto de vantagem natural que vigia a costa e a estrada principal. Posicionado entre o Flagelo a leste, Dalaran a sudeste e worgens selvagens ao sul, ele serve como o único posto avançado seguro onde patrulhas da Guarda da Morte e pesquisadores da Boticária Real podem coordenar defesas e proteger a rota para Tirisfal.",al={"por que os renegados estão no sepulcro","por que o sepulcro é base dos renegados","importância do sepulcro"}},["0581536d"]={q="Quem é o Alto-executor Hadrec?",a="O Alto-executor Hadrec é o comandante militar das operações dos Renegados na Floresta de Pinhaprata, estacionado no Sepulcro. Severo e pragmático, ele orienta a Guarda da Morte e os batedores Carrascos a pacificar a floresta, descobrir ameaças ocultas e orquestrar ataques contra forças hostis como Thule Corvinalle e os gnolls da Couro Podre.",al={"hadrec","quem é hadrec","alto-executor hadrec pinhaprata"}},ff53d58c={q="A quem o Alto-executor Hadrec responde?",a="Hadrec responde diretamente à Grande Dama Sylvana Correventos, a Rainha Banshee dos Renegados, e seu alto comando na Cidade Baixa. Como oficial sênior da Guarda da Morte, seu mandato é proteger as fronteiras do reino recém-nascido dela e eliminar qualquer poder que possa comprometer a soberania dos Renegados.",al={"quem é o chefe de hadrec","superior de hadrec","a quem hadrec se reporta"}},["6c73f41e"]={q="Quem são os gnolls da Couro Podre e por que estão aqui?",a="Os Couro Podre são um clã vicioso de gnolls que habita a Floresta de Pinhaprata, operando principalmente a partir da Ilha de Fenris e rondando as margens do Espelho de Lordaeron. Ao contrário dos gnolls comuns, eles são afligidos pela praga da morte-viva, exibindo pelagem cinza irregular e olhos amarelados e remelentos. Eles travam uma guerra de guerrilha brutal contra os Renegados, vasculham campos de batalha e atacam ferozmente qualquer um que se aproxime de seus acampamentos.",al={"gnolls da couro podre","por que existem gnolls em pinhaprata","gnoll couro podre pinhaprata"}},ad054bc9={q="Quem está controlando os gnolls Peles-podres?",a="Os gnolls Peles-podres estão sob o jugo de Thule Corvinalle, um necromante traiçoeiro aliado ao Flagelo. De sua fortaleza na Ilha de Fenris, Thule usa magia sombria para manipular essas feras purulentas, enviando-as a campos de batalha exumados para colher cadáveres frescos para suas legiões crescentes de mortos-vivos.",al={"quem comanda os peles-podres","mestre dos peles-podres","quem lidera os peles-podres"}},["97f89d60"]={q="O que é o Campo Morto?",a="O Campo Morto é uma vasta extensão de terras agrícolas devastadas na região central da Floresta de Pinhaprata, ao longo da estrada que leva ao Espelho de Lordaeron. Antigamente uma propriedade agrícola pacífica, tornou-se um grande campo de extermínio durante a Terceira Guerra, quando o Flagelo invadiu Lordaeron. Hoje, é um cemitério aberto repleto de covas rasas e terra revolvida.",al={"campo morto floresta de pinhaprata","campo morto","o que é o campo morto"}},d487a8f2={q="Por que os gnolls estão cavando no Campo Morto?",a="Os gnolls Peles-podres estão escavando o Campo Morto para desenterrar os cadáveres humanos enterrados lá durante a Terceira Guerra. Agindo sob as ordens de Thule Corvinalle, eles desenterram corpos e restos preservados para fornecer ao necromante matéria-prima para construir constructos do Flagelo e reforçar seu exército de mortos-vivos na Ilha de Fenris.",al={"por que os peles-podres estão cavando","gnolls campo morto por quê","gnoll desenterrando cadáveres"}},["3bca491d"]={q="O que há na Ilha de Fenris?",a="A Ilha de Fenris é uma grande ilha situada no Espelho de Lordaeron, na costa leste da Floresta de Pinhaprata. Ela é dominada pelo Castelo Fenris, uma antiga fortaleza militar de Lordaeron que caiu em ruínas sombrias. Hoje, a ilha serve como um reduto fortemente fortificado, infestado de gnolls Peles-podres e lacaios mortos-vivos de Thule Corvinalle.",al={"ilha de fenris","o que há na ilha de fenris","castelo fenris"}},bd044bca={q="Por que Hadrec quer atacar a Ilha de Fenris?",a="Hadrec reconhece a Ilha de Fenris como o coração pulsante da ameaça do Flagelo na parte leste da Floresta de Pinhaprata. Deixar Thule Corvinalle entrincheirado no Castelo Fenris dá ao Flagelo uma base inexpugnável para criar gnolls mortos-vivos, atacar caravanas de suprimentos e ameaçar a abordagem leste das Clareiras de Tirisfal. Atacar a ilha é crucial para quebrar o poder de Thule e proteger o lago.",al={"por que atacar a ilha de fenris","motivo de hadrec para ilha de fenris","motivo para assault on fenris isle"}},["574e415e"]={q="Os magos de Dalaran em Lenhâmbar estão trabalhando com a Aliança?",a="Sim. Embora Dalaran se concentre intensamente na reconstrução de sua cidade devastada, as forças do Kirin Tor estacionadas em Lenhâmbar permanecem abertamente amigáveis com a Aliança e ferozmente hostis com a Horda. Dalaran frequentemente envia ajuda aos enclaves humanos sobreviventes da Floresta de Pinhaprata, opondo-se à expansão dos Renegados e trabalhando em estreita colaboração com os remanescentes do sul.",al={"lenhâmbar dalaran aliança","dalaran está com a aliança aqui","kirin tor aliança floresta de pinhaprata"}},fd7851b2={q="Quem é Arugal e o que é a 'Loucura de Arugal'?",a="O Arquimago Arugal era um mago de Dalaran que, desesperado para se defender do Flagelo durante a Terceira Guerra, recorreu a magia proibida e invocou feras lupinas monstruosas conhecidas como worgens. No entanto, as feras selvagens voltaram-se contra os magos do Kirin Tor e os habitantes locais inocentes, espalhando uma maldição licantrópica voraz pelo sul da Floresta de Pinhaprata. Enlouquecido pela culpa e pelo horror do que havia libertado, Arugal retirou-se para a Bastilha da Presa Negra, adotando os worgens como seus 'filhos'.",al={"arugal","loucura de arugal","quem foi arugal","lore do arquimago arugal"}},f38b73fd={q="De onde vieram os worgens?",a="Os worgens são feras lupinas de outro mundo trazidas através de dimensões pelo Arquimago Arugal. Buscando uma arma para reforçar Dalaran contra o Flagelo durante a Terceira Guerra, Arugal conjurou essas criaturas para a Floresta de Pinhaprata, onde elas rapidamente se voltaram contra seus invocadores e espalharam uma maldição transformadora.",al={"de onde vieram os worgens","origem dos worgens floresta de pinhaprata","como os worgens chegaram aqui"}},fc903f13={q="Arugal ainda está vivo?",a="Sim, o Arquimago Arugal está muito vivo. Envolto em loucura, ele reside no alto das torres da Bastilha da Presa Negra, com vista para o Vilarejo Lenhardente. De sua fortaleza, ele dirige sua matilha de worgens da Presa Negra e protege seu domínio lupino retorcido de qualquer um que seja ousado o suficiente para romper seus portões.",al={"arugal está vivo","onde está arugal agora","status de arugal"}},["5dc043c6"]={q="O que é o Vilarejo Lenhardente?",a="O Vilarejo Lenhardente é um assentamento humano aninhado no sudoeste da Floresta de Pinhaprata, diretamente abaixo das imponentes falésias da Bastilha da Presa Negra. Ele foi deixado de fora quando Guilnéas selou a Muralha Greymane antes da Terceira Guerra. Seus habitantes sobreviventes lutam para manter uma aparência de vida normal durante o dia, embora uma escuridão antiga os consuma assim que o sol se põe.",al={"lore do vilarejo lenhardente","o que é lenhardente","cidade de lenhardente"}},["20eec241"]={q="Para onde tudo isso leva depois da Floresta de Pinhaprata?",a="Depois que você estabilizar a Floresta de Pinhaprata enfrentando Thule Corvinalle e eliminando Arugal na Bastilha da Presa Negra, sua jornada normalmente leva para o leste, através das montanhas, até o Contraforte de Eira dos Montes para apoiar os Renegados na Serraria Tarren. Alternativamente, muitos viajantes da Horda pegam um zepelim para Kalimdor para fazer campanha através das vastas planícies dos Sertões.",al={"para onde ir depois da floresta de pinhaprata","próxima zona depois da floresta de pinhaprata","próximo passo na floresta de pinhaprata"}},da147569={q="Como fui parar na Floresta de Pinhaprata?",a="Você provavelmente seguiu a estrada para o sul saindo das Clareiras de Tirisfal, passando pela passagem da montanha a sudoeste das ruínas da Cidade Baixa. Os personagens Renegados terminam de proteger seu lar ao norte, em Tirisfal, e naturalmente pressionam para o sul em direção à Floresta de Pinhaprata para expandir o império nascente. Alternativamente, os viajantes da Horda de outros continentes chegam via zepelim fora da Cidade Baixa antes de caminhar pela costa, enquanto aventureiros raros vindos do sul podem cruzar o Contraforte de Eira dos Montes para chegar a essas florestas devastadas.",al={"como cheguei aqui","como chego na floresta de pinhaprata","caminho para a floresta de pinhaprata"}},["97a9302a"]={q="O que devo fazer na Floresta de Pinhaprata?",a="Você está aqui para ajudar os Renegados a proteger sua fronteira sul contra perigos crescentes. Apresentando-se ao Alto-executor Hadrec e aos sicários no Sepulcro, você deve enfrentar os gnolls Peles-podres doentes que atacam do Campo Morto e da Ilha de Fenris, erradicar necromantes do Flagelo como Thule Corvinalle e manter vigilância sobre os magos de Dalaran entrincheirados em Lenhâmbar. Mais ao sul, você também investigará as feras lupinas vorazes que aterrorizam o Vilarejo Lenhardente e a sombra lançada pela Bastilha da Presa Negra.",al={"qual é minha missão aqui","por que fui enviado para a floresta de pinhaprata","o que estamos fazendo na floresta de pinhaprata"}}},fp="22,399,24.673.0,26.587.1,27.614.1,45.389.0,62.356.1,25.323.1,42.303.0,20.319.0,69.322.0"}
P.entries["zone:stockade"] = {n="O Cárcere",s="O Cárcere é o complexo prisional de segurança máxima de Ventobravo, escondido sob o distrito dos canais da cidade, perto do Distrito dos Magos. Construído para deter os criminosos mais perigosos, insurgentes políticos e inimigos do estado capturados do reino, as instalações colapsaram recentemente em uma anarquia violenta. O Carcereiro-chefe Thelágua foi forçado a recuar para a entrada, recrutando desesperadamente aventureiros capazes para esmagar a rebelião por dentro antes que ela se espalhe para a capital.",h="O Cárcere é o complexo prisional de segurança máxima de Ventobravo, escondido sob o distrito dos canais da...",kw={"basílio taborda","bruegal ferroque","canais","defias","flávio lúcio","ramoque","kam fundafúria","rebelião","o cárcere","ventobravo","targorr","carcereiro-chefe thelágua"},ang={["class:Mage"]="Localizada bem na beira do canal do Distrito dos Magos, a prisão contém brigões físicos vulneráveis a magias de lentidão, enquanto o ogro mago Ramoque pode liberar uma Cadeia de Raios.",["class:Rogue"]="O layout da prisão apresenta uma rede complexa de celas de ferro trancadas e conexões com a Irmandade Défias, oferecendo prática única de arrombamento de fechaduras e informações sobre o sindicato do submundo de Basílio Taborda.",["faction:Alliance"]="A rebelião ameaça o próprio coração da capital; conter a revolta preserva a segurança interna de Ventobravo enquanto honra recompensas não oficiais para Montanhas Cristarrubra, Floresta do Crepúsculo e Altaforja.",["race:Dwarf"]="A presença de Kam Fundafúria nas celas de Ventobravo é uma afronta a Dun Modr; o Reino de Altaforja exige a cabeça dele para vingar as vidas anãs perdidas nas Pantanal."},sec={{t="Uma Prisão sob Cerco",b="Sob os canais tranquilos de Ventobravo, O Cárcere tornou-se uma zona de guerra. Quando o exército regular marchou para lutar em frentes distantes, a prisão, com falta de pessoal, passou a depender de jovens inexperientes — incluindo recrutas de catorze anos — para manter a ordem. Não funcionou. Os detentos iniciaram uma rebelião sangrenta e coordenada, rasgando seus cobertores de lã para fazer bandanas de gangue e eliminando os guardas restantes. O Carcereiro-chefe Thelágua mal conseguiu manter o controle da entrada, deixando as celas, corredores e blocos de detenção nas mãos impiedosas dos condenados."},{t="Nobres e Assassinos",b="A rebelião expôs o lado feio da máquina política de Ventobravo. Territórios externos há muito estavam frustrados com a Casa dos Nobres suspendendo execuções para sua própria vantagem. O Guarda Berto, de Cristarrubra, queria que o orc capturado Targorr, o Horror fosse executado por suas atrocidades, apenas para ver os nobres congelarem a sentença. O Conselheiro Bonfá-lobos, de Vila Sombria, viu o ladrão de túmulos Flávio Lúcio ser poupado da forca, apesar de profanar túmulos para o necromante Morbent Fel. Até os anões de Dun Modr enviaram mensagens exigindo a morte do sabotador Ferro Negro Kam Fundafúria. Com O Cárcere em caos, as autoridades locais contrataram silenciosamente aventureiros para realizar as execuções que os tribunais da capital se recusaram a aplicar."},{t="O Mentor e os Rebeldes",b="Por trás do colapso sincronizado da prisão está Basílio Taborda, um criminoso astuto ligado diretamente à Irmandade Défias, que orquestrou a revolta de sua cela. Entre os rebeldes está Bruegal Ferroque, um perigoso brigão anão. Ele é um dos vários condenados endurecidos que os aventureiros podem encontrar enquanto ajudam Thelágua a retomar a prisão."}},faq={{q="Por que O Cárcere está em rebelião aberta?",a="A Irmandade Défias orquestrou uma rebelião em toda a prisão enquanto as instalações estavam com falta de pessoal. Com o Exército de Ventobravo destacado para frentes de batalha distantes, voluntários adolescentes foram deixados guardando assassinos endurecidos. Os condenados emboscaram a equipe, apreenderam armas e forçaram o Carcereiro-chefe Thelágua a sair dos blocos de celas.",al={"por que a rebelião","o que aconteceu no cárcere","causa da rebelião no cárcere"}},{q="Quem está comandando a revolta lá dentro?",a="O mentor por trás da revolta é Basílio Taborda, um influente criminoso da Irmandade Défias encarcerado no bloco de celas leste. Outros prisioneiros perigosos incluem Bruegal Ferroque, Ramoque e Kam Fundafúria.",al={"chefe do cárcere","quem lidera a rebelião","quem comanda o cárcere"}},{q="Por que prisioneiros como Targorr e Flávio Lúcio ainda estão vivos?",a="Ambos foram condenados à morte, mas políticos corruptos dentro da Casa dos Nobres impuseram impedimentos burocráticos às suas execuções para usá-los como alavancagem política. Essa interferência indignou aliados em Vila Plácida e Vila Sombria, levando-os a enviar aventureiros para eliminar os prisioneiros durante o caos.",al={"por que targorr não foi executado","julgamento de flávio lúcio","corrupção da casa dos nobres"}},{q="O que derrotar Bruegal Ferroque significa para a prisão?",a="Bruegal Ferroque é um perigoso brigão anão entre os rebeldes. Derrotá-lo remove uma ameaça da prisão enquanto os aventureiros trabalham para conter a rebelião.",al={"história de bruegal ferroque","matar bruegal","quem é bruegal"}},{q="Por que há anões Ferro Negro e orcs numa prisão humana?",a="O Cárcere serve como uma prisão de segurança máxima para prisioneiros de guerra de alto valor. Targorr, o Horror liderou ataques de orcs Rocha Negra em Montanhas Cristarrubra, enquanto Kam Fundafúria realizou sabotagem para o clã Ferro Negro nas Pantanal antes de ambos serem capturados e transferidos para a capital.",al={"por que os anões Ferro Negro estão aqui","história de Kam Fundafúria","Targorr no Cárcere"}},{q="Jogadores da Horda podem entrar em O Cárcere?",a="Sim, mas é excepcionalmente perigoso. A entrada da masmorra fica diretamente dentro de Ventobravo, perto dos canais do Distrito dos Magos. Infiltrados da Horda devem passar furtivamente pelos guardas da cidade e pelos defensores da capital para alcançar o portal.",al={"a horda pode fazer o cárcere","horda na prisão de ventobravo"}}},fx={["07af5e0b"]={q="O que é o Cárcere?",a="O Cárcere é o complexo prisional de segurança máxima de Ventobravo, construído sob o distrito de Canals da capital. Ele serve como local de detenção para pequenos ladrões, assassinos, insurgentes políticos e inimigos de alto perfil do reino que aguardam julgamento.",al={"o que é o carcere de ventobravo","prisão o carcere","cadeia de ventobravo"}},["2fc364a6"]={q="O Cárcere é apenas para a Irmandade Défias?",a="Não. Embora a Irmandade Défias componha o núcleo da revolta, as celas abrigam pequenos ladrões, saqueadores de túmulos como Flávio Lúcio, orcs do Rocha Negra capturados como Targorr, o Horror, e até mesmo sabotadores Ferro Negro como Kam Fundafúria.",al={"o carcere é só para a irmandade défias","quem está no Cárcere","todos os prisioneiros são da irmandade défias"}},["0d433487"]={q="Por que há tantos integrantes da Irmandade Défias presos aqui?",a="As autoridades de Ventobravo capturaram agentes da irmandade por toda Cerro Oeste, Floresta de Elwynn e na própria cidade. Em vez de executá-los imediatamente, a coroa os levou para o Cárcere, concentrando uma rede volátil de insurgentes bem debaixo das tábuas do assoalho da cidade.",al={"por que tantos integrantes da irmandade défias aqui","por que a irmandade défias no Cárcere","prisioneiros da Irmandade Défias"}},e96a18b2={q="Quem é o responsável por esta prisão?",a="O Carcereiro-chefe Thelágua comanda a instalação. Quando a revolta estourou, seus guardas foram sobrecarregados e expulsos dos blocos de celas. Thelágua mal conseguiu manter a entrada, deixando-o desesperado para recrutar aventureiros capazes para retomar os corredores.",al={"quem comanda o Cárcere","carcereiro do Cárcere","carcereiro-chefe thelágua"}},["06cbacdc"]={q="Por que os guardas do Carcereiro-chefe Thelágua não conseguem conter o motim?",a="A guarda prisional já estava extremamente reduzida, recorrendo até a voluntários com apenas quatorze anos para vigiar detentos perigosos. Quando a Irmandade Défias se uniu e atacou, a equipe foi pega totalmente de surpresa, massacrada ou forçada a fugir para o saguão de entrada.",al={"por que os guardas não impedem o motim","onde estão os guardas da prisão","guardas do Cárcere"}},["7c158547"]={q="Por que Ventobravo está me enviando em vez do exército?",a="Grande parte das forças militares de Ventobravo está posicionada em frentes distantes, e a burocracia corrupta na Casa dos Nobres paralisa ações municipais rápidas. Além disso, as autoridades da cidade estão desesperadas para manter o motim em segredo para evitar pânico total nas ruas.",al={"por que enviar aventureiros","por que não o exército no Cárcere","onde está o exército de ventobravo"}},a2006c52={q="Os guardas do lado de fora sabem o que está acontecendo lá dentro?",a="Os guardas contêm os amotinados no limiar da masmorra, e o Carcereiro-chefe Thelágua busca ajuda para restaurar a ordem no interior. As autoridades da cidade mantêm a perturbação discreta para evitar alarmar os cidadãos comuns.",al={"os guardas externos sabem do motim","Ventobravo sabe do motim","segredo do Cárcere"}},b1798127={q="Qual é a diferença entre os prisioneiros, condenados e insurgentes aqui dentro?",a="Os detentos variam de criminosos comuns e batedores de carteira tirados das ruas a criminosos condenados e insurgentes radicais da Irmandade Défias. Enquanto os condenados comuns aproveitaram a chance para se amotinar e saquear, os insurgentes recebem ordens ativamente de Basílio Taborda para derrubar a prisão.",al={"prisioneiros insurgentes","tipos de inimigos do Cárcere","quem são os detentos"}},["378bbf14"]={q="Como os detentos conseguiram armas e se organizaram?",a="A revolta foi meticulosamente planejada pelo líder da Irmandade Défias, Basílio Taborda. Sob sua direção, os prisioneiros rasgaram seus cobertores de lã em lenços vermelhos de gangue, atacaram guardas com pouco contingente, roubaram suas armas e chaves, e metodicamente libertaram celas em todas as alas.",al={"como os prisioneiros conseguiram armas","como a irmandade défias se organizou","quem armou os prisioneiros"}},["855deb71"]={q="Por que colocar uma prisão bem debaixo da cidade?",a="O complexo prisional fica sob os canais de Ventobravo. Sua localização original não é explicada.",al={"por que há uma prisão sob Ventobravo","localização do Cárcere","prisão sob os canais"}},caa2e4bf={q="Como eu acabei no Cárcere?",a="Você atravessou as pesadas portas de ferro perto dos canais ao norte em Ventobravo. Um motim massivo estourou sob as ruas, e os guardas restantes do Carcereiro-chefe Thelágua foram forçados a recuar até o limiar, deixando os detentos no controle. Desesperado para manter o caos escondido dos cidadãos lá em cima, o carcereiro recrutou aventureiros aptos para marchar direto para dentro dos blocos de celas e retomar a instalação à força.",al={"como eu cheguei aqui","por que eu vim aqui","como eu entrei no Cárcere"}},["45edc40e"]={q="O que devo fazer no Cárcere?",a="Sua missão principal é acabar com a rebelião e eliminar seu líder, o mentor da Irmandade Défias, Basílio Taborda. No entanto, aliados por todo o reino aproveitaram este momento de caos para acertar contas pendentes: Vila Sombria busca retribuição contra o saqueador de túmulos Flávio Lúcio, Vila Plácida quer que o impiedoso orc Targorr, o Horror seja morto, e Altaforja exige a cabeça do sabotador Kam Fundafúria.",al={"qual é minha missão aqui","o que eu faço aqui","por que estou aqui"}}},fp="12,345,20.476.0,20.680.1,30.277.1,38.302.0,35.174.0,60.285.0,60.151.0,61.253.0,37.213.0"}
P.entries["zone:stonetalon"] = {n="Cordilheira das Torres de Pedra",s="A Cordilheira das Torres de Pedra é uma cadeia montanhosa escarpada e esculpida pelo vento que faz fronteira com o Vale Gris, os Sertões e Desolação. Venerada tanto pelos elfos noturnos quanto pelos taurens como um santuário sagrado, as alturas consagradas da região contrastam fortemente com a fumaça e o maquinário que sufocam seus cânions inferiores. Hoje, as montanhas estão assoladas pelo desmatamento, pela devastação elemental instável e por crescentes hostilidades de fronteira.",h="A Cordilheira das Torres de Pedra é uma cadeia montanhosa escarpada e esculpida pelo vento que faz fronteira...",kw={"vale carbonizado","hanfritz schaventorck","malaka'jin","cordilheira das torres de pedra","morro das torres de pedra","retiro rocha do sol","talondeep pass","rochedo cortavento"},ang={["class:Druid"]="A profanação do Rochedo Cortavento e a corrupção calcinada do Vale Carbonizado servem como um grave chamado para druidas que buscam acalmar espíritos da natureza enfurecidos e proteger ninhos sagrados.",["class:Shaman"]="O clamor dos espíritos da montanha sob o ataque das perfuratrizes dos goblins pode ser ouvido até em Orgrimmar, chamando xamãs para conter elementais da terra enfurecidos e restaurar o equilíbrio dos picos.",["faction:Alliance"]="Estacionada no alto do Morro das Torres de Pedra e em acampamentos ocultos ao redor do Rochedo Cortavento, a Aliança defende covis ancestrais kaldorei de máquinas goblins e de rivais territoriais invasores.",["faction:Horde"]="Os aventureiros da Horda contam com o refúgio isolado do Retiro Rocha do Sol e o posto troll meridional de Malaka'jin para frear a poluição industrial dos Empreendimentos S.A. e erradicar os perigosos foras da lei do Totem Sombrio."},sec={{t="Os Maus Ventos e os Picos",b="Erguendo-se abruptamente da região central de Kalimdor, a cordilheira das Torres de Pedra retém a umidade trazida dos mares ocidentais, originando tempestades repentinas e trilhas traiçoeiras de arenito escorregadio pela chuva. A característica mais marcante dos vales inferiores é o vento cortante e incessante conhecido como os Maus Ventos, capaz de cegar viajantes com poeira ou atirar os desatentos diretamente de penhascos íngremes. Mais acima, florestas de coníferas cobrem as encostas ao redor do Morro das Torres de Pedra, onde os elfos noturnos cuidam de covis ancestrais e clareiras, vigiando os ninhos sagrados de mantícoras e hipogrifos que habitam o Lago Mirkfallon."},{t="Indústria e Intrusão",b="A solidão pacífica da cordilheira foi violentamente interrompida pela chegada dos Empreendimentos S.A. Montando extensos acampamentos de extração de madeira e escavando profundas minas a céu aberto no Rochedo Cortavento, os goblins — auxiliados pelo demente gnomo leproso Hanfritz Schaventorck — desmataram árvores centenárias, escureceram os céus com fumaça de fornalhas e despejaram detritos industriais nas águas da montanha. A ganância deles provocou uma retaliação rápida: xamãs locais de Orgrimmar responderam aos gritos agoniados dos espíritos da montanha, enquanto pequenos acampamentos da Aliança nas proximidades lutam contra os profanadores para proteger o que resta das terras altas."},{t="Cicatrizes do Passado",b="Ao sul fica o Vale Carbonizado, outrora uma natureza exuberante, agora reduzido a uma terra devastada coberta de cinzas e tomada por elementais do fogo rebeldes, dracônicos negros e harpias. Embora os picos tenham sido o local histórico onde a Horda e a Aliança forjaram uma frágil trégua durante a Terceira Guerra sob a orientação do misterioso Oráculo, as relações atuais estão se deteriorando. Taurens renegados do Totem Sombrio operam a partir de acampamentos capturados, e trolls Lançanegra em Malaka'jin entram em conflito com incursões da Aliança vindas dos Sertões e do Vale Gris."}},faq={{q="Como chego à Cordilheira das Torres de Pedra?",a="A maioria dos viajantes entra pelo Desfiladeiro da Garra Profunda, uma trilha na montanha que corta a cordilheira a partir do sudoeste do Vale Gris. Também há trilhas elevadas que levam ao sul para Desolação e caminhos que descem a leste diretamente para as extensões setentrionais dos Sertões.",al={"entrada da cordilheira das torres de pedra","como chegar à cordilheira das torres de pedra","estrada da cordilheira das torres de pedra"}},{q="Por que o Vale Carbonizado está queimado e arruinado?",a="O Vale Carbonizado já foi um refúgio luxuriante, mas uma devastação cataclísmica consumiu o vale em chamas. Ele foi reduzido a uma ruína fumegante infestada de agressivos elementais do fogo, draconetes rebeldes e harpias mortais.",al={"fogo no vale carbonizado","o que aconteceu com o vale carbonizado","por que o vale carbonizado queimou"}},{q="O que os Empreendimentos S.A. estão fazendo no Rochedo Cortavento?",a="Os Empreendimentos S.A. estão desmatando árvores impiedosamente e perfurando fundo a encosta da montanha em busca de riquezas minerais. Suas operações poluíram o Lago do Rochedo com graxa de motor, devastaram os vales e enfureceram os espíritos locais e os habitantes nativos.",al={"empreendimentos s.a. cordilheira das torres de pedra","goblins do rochedo cortavento","por que goblins cortam arvores"}},{q="Onde ficam os principais mestres de voo?",a="Os heróis da Aliança usam o mestre de voo situado no santuário elevado do Morro das Torres de Pedra, ao norte, enquanto os aventureiros da Horda se estabelecem na aldeia montanhosa central do Retiro Rocha do Sol.",al={"rota de voo da cordilheira das torres de pedra","onde fica o ponto de voo da cordilheira das torres de pedra","ponto de voo cordilheira das torres de pedra"}},{q="O que aconteceu no Morro das Torres de Pedra durante a Terceira Guerra?",a="Guiados por visões do Profeta Medivh, Thrall e Jaina Proudmore subiram as cavernas do Morro das Torres de Pedra em busca do Oráculo. Lá, os líderes das duas facções forjaram a histórica aliança temporária que se uniu contra a Legião Ardente no Monte Hyjal.",al={"historia do morro das torres de pedra","o oraculo da cordilheira das torres de pedra","terceira guerra cordilheira das torres de pedra"}},{q="Quem são os Totem Sombrio na Cordilheira das Torres de Pedra?",a="Os Totem Sombrio são uma tribo tauren implacável e renegada, hostil a influências externas. Na Cordilheira das Torres de Pedra, eles ocuparam um posto montanhoso perto da fronteira com os Sertões, aterrorizando viajantes locais e fazendo prisioneiros.",al={"aldeia do temível totem","totem sombrio cordilheira das torres de pedra"}}},fx={["5a5a6e9c"]={q="Por que os tauren se estabeleceram no Retiro Rocha do Sol?",a="Por gerações, os tauren reverenciaram este vale como um lugar com uma conexão profunda com o reino espiritual. Lendas antigas dizem que o deus sol An'she beijou o pico sobre o qual o retiro se ergue. Os tauren fizeram peregrinações sagradas aqui por muito tempo para comungar com espíritos e acender grandes fogueiras rituais para iluminar as montanhas sombreadas.",al={"por que tauren se instalam em rocha do sol","história do retiro rocha do sol","an'she rocha do sol"}},["51d42c77"]={q="O que é o Rochedo Cortavento?",a="O Rochedo Cortavento já foi uma floresta virgem verdejante, mas foi devastado pela exploração industrial. A Empreendimentos S.A. desmatou o vale, transformando-o em uma extensão árida de tocos, terra e maquinário fumegante. Entre o desmatamento da Empreendimentos S.A., o escoamento sujo no Lago do Rochedo e os kobolds infestando a mina local, ele se destaca como um monumento arruinado à ganância desenfreada.",al={"sobre o rochedo cortavento","zona do rochedo cortavento","lore do rochedo cortavento"}},d850bc0a={q="O que há na Mina Cortavento?",a="A Mina Cortavento, localizada nos penhascos do sudeste do Rochedo Cortavento, está tomada por kobolds Cortavento agressivos. Expulsos ou abandonados pelos mineradores regulares, os kobolds agora escavam furiosamente veios de Lingotes de Ferro Fumegante, atacando ferozmente qualquer um que tente invadir suas escavações subterrâneas.",al={"kobolds da mina cortavento","o que há na mina cortavento","ferro fumegante mina cortavento"}},d3863c46={q="O que é o Retiro do Gadanho no Morro das Torres de Pedra?",a="O Retiro do Gadanho é uma antiga toca de túmulo dos elfos noturnos esculpida nas alturas do Morro das Torres de Pedra. Ele é mantido por druidas Cenarianos que comungam com os espíritos da natureza e o Sonho Esmeralda. Lá no fundo, druidas tradicionalmente dormiam em contemplação sagrada, protegidos por dríades, guardiões e pelas proteções mágicas do pico.",al={"retiro do gadanho","a toca morro das torres de pedra","toca de túmulo torres de pedra"}},a547ffd6={q="O Vale Gris se conecta à Cordilheira das Torres de Pedra?",a="Sim. O robusto Túnel Garracava conecta diretamente o sudoeste do Vale Gris ao nordeste da Cordilheira das Torres de Pedra através de uma passagem montanhosa cavernosa. Viajantes e aventureiros frequentemente passam entre as florestas imaculadas e contestadas do Vale Gris e as alturas áridas da Cordilheira das Torres de Pedra enquanto rastreiam ameaças da Empreendimentos S.A. ou os conflitos de facções em andamento.",al={"como o vale gris se conecta às torres de pedra","túnel garracava vale gris","fronteira do vale gris torres de pedra"}},a5c2784c={q="Como vim parar na Cordilheira das Torres de Pedra?",a="A maioria dos viajantes chega a essas alturas irregulares através do Túnel Garracava, um antigo túnel montanhoso esculpido no sudoeste do Vale Gris. Outros andarilhos sobem pelas trilhas acidentadas que levam para o oeste saindo dos Sertões, ascendendo as passagens varridas pelo vento em direção aos rochedos. Seja enviado para o sul pelos comandantes elfos noturnos em Astranaar ou despachado para o oeste através da fronteira chamuscada da Encruzilhada, os cânions altos e os Ventos Uivantes saúdam qualquer um que faça a árdua jornada pela cordilheira.",al={"como vim parar aqui","como chego às torres de pedra","chegada às torres de pedra"}},["4abc7ef6"]={q="O que devo fazer na Cordilheira das Torres de Pedra?",a="Você está aqui para enfrentar as ameaças crescentes que estão destruindo essas alturas sagradas. No Rochedo Cortavento, os implacáveis goblins da Empreendimentos S.A. derrubam florestas antigas e poluem os rios com maquinário, atraindo a ira de ambas as facções. Enquanto isso, a tribo Totem Sinistro causa conflitos ao longo da fronteira leste, enquanto harpias cruéis e elementais do fogo enfurecidos infestam a bacia chamuscada do Vale Carbonizado. Você deve ajudar seus aliados a repelir esses poluidores e monstros para proteger a terra.",al={"o que devo fazer aqui","por que estou aqui","qual é minha missão nas torres de pedra"}},["4946a833"]={q="O que é a Cordilheira das Torres de Pedra?",a="A Cordilheira das Torres de Pedra é uma cordilheira acidentada e esculpida pelo vento na região central de Kalimdor, situada a oeste dos Sertões, ao sul do Vale Gris e ao norte da Desolação. Conhecida por ventos extremos, abismos profundos e picos de arenito íngremes criados durante a Grande Cisão, a região forma uma zona fronteiriça histórica onde elfos noturnos e taurens coexistiram por gerações. Seus cumes altos e sagrados permanecem exuberantes com coníferas, enquanto os vales mais baixos são secos, rochosos e fortemente marcados pela indústria.",al={"zona da cordilheira das torres de pedra","o que é a cordilheira das torres de pedra","sobre a cordilheira das torres de pedra"}},["4e995438"]={q="A Cordilheira das Torres de Pedra é perigosa?",a="Sim, os viajantes enfrentam perigos naturais e hostis ferozes. Ventos violentos e chuvas repentinas podem tornar os altos penhascos de arenito escorregadios o suficiente para fazer as pessoas caírem para a morte. Além do clima, as montanhas estão cheias de harpias Fúria-de-sangue agressivas, serpes predatórias, aranhas, kobolds e elementais enfurecidos. Além disso, o maquinário implacável e os executores armados da Empreendimentos S.A. tornam vales disputados como o Rochedo Cortavento excepcionalmente perigosos.",al={"perigo na cordilheira das torres de pedra","a cordilheira das torres de pedra é segura","perigos da cordilheira das torres de pedra"}},["9d849e11"]={q="Quem vive na Cordilheira das Torres de Pedra?",a="A região abriga facções dispersas em vez de um único poder governante. Os elfos noturnos mantêm o Morro das Torres de Pedra e guardam locais sagrados por todas as alturas, enquanto a Horda mantém assentamentos no Retiro Rocha do Sol e a aldeia troll de Malaka'jin. Harpias Fúria-de-sangue nativas aninham-se nas fendas, taurens da Tribo do Totem Sinistro hostis ocupam postos próximos, e a Empreendimentos S.A., operada por goblins, ocupa trechos desmatados ao redor do Rochedo Cortavento.",al={"quem vive na cordilheira das torres de pedra","facções da cordilheira das torres de pedra","habitantes da cordilheira das torres de pedra"}},a4f73e64={q="Por que a Empreendimentos S.A. está explorando madeira no Rochedo Cortavento?",a="A Empreendimentos S.A. é um conglomerado mercantil implacável que busca lucro através da exploração desenfreada de recursos. No Rochedo Cortavento, eles realizam cortes rasos em florestas antigas usando maquinário pesado como o Super Reaper 6000 e explodem a terra em busca de minério precioso. Seu desprezo pela natureza enche o ar com fuligem e envenena as águas locais com lodo e óleo, ganhando a oposição furiosa tanto dos druidas locais quanto da Horda.",al={"extração de madeira da empreendimentos s.a.","por que os goblins estão cortando árvores","madeira da empreendimentos s.a. cordilheira das torres de pedra"}},["66935983"]={q="Quem comanda a Empreendimentos S.A. no Rochedo Cortavento?",a="As operações locais de extração de madeira e mineração no Rochedo Cortavento são dirigidas por um gnomo leproso chamado Gerenzo Wrenchwhistle. Supervisionando o corte raso de uma plataforma construída bem acima do Lago do Rochedo, Gerenzo emprega sua experiência mecânica para maximizar a destruição. Suas operações desonestas até atraíram a ira de inventores goblins rivais da União dos Funileiros, que buscam eliminá-lo.",al={"quem comanda o rochedo cortavento","gerenzo wrenchwhistle","líder da empreendimentos s.a. na cordilheira das torres de pedra"}},ff0da62d={q="Quem são as harpias Fúria-de-sangue?",a="As harpias Fúria-de-sangue são uma tribo cruel de mulheres-pássaro nativas da Cordilheira das Torres de Pedra. Historicamente, essas montanhas eram seu coração ancestral antes de se espalharem pelos Sertões e além. Elas defendem agressivamente seu território de estranhos, capturando bestas locais e entrando em conflito violento com peregrinos taurens e maquinários goblins invasores em locais como o Vale Carbonizado.",al={"harpias fúria-de-sangue","harpias da cordilheira das torres de pedra","quem são as harpias aqui"}},["66599fe7"]={q="O que é o Retiro Rocha do Sol?",a="O Retiro Rocha do Sol é um assentamento pacífico da Horda aninhado em um vale montanhoso isolado ao sul do Lago Mirkfallon. Ele serve como a base principal para taurens e orcs na região, abrigando xamãs e druidas dedicados a restaurar a terra da poluição da Empreendimentos S.A. e combater as ameaças que invadem as montanhas sagradas.",al={"lore do retiro rocha do sol","o que é o retiro rocha do sol","taurens do retiro rocha do sol"}}},fp="20,167,27.462.0,22.461.0,17.474.0,41.202.0,42.194.0,52.224.0,42.161.0,54.229.0,36.181.0"}
P.entries["zone:stormwind"] = {n="Ventobravo",s="Ventobravo, de muralhas brancas, é o maior refúgio dos homens e o coração da Aliança. Mas seu rei está desaparecido. A coroa agora repousa sobre um menino de dez anos.",h="Ventobravo, de muralhas brancas, é o maior refúgio dos homens e o coração da Aliança.",kw={"anduin","bolvar","catedral","correfundo","prestor","pedreiros","ventobravo","vancleef","wrynn"},ang={["class:Paladin"]="Como paladino, você pode encontrar a Catedral da Luz, o principal santuário da sua fé no sul. Ela treina cavaleiros da Silver Hand e defende a justiça.",["class:Rogue"]="Como ladino, você pode encontrar o quartel-general da AVIN sob as ruas de pedra da Cidade Velha. A organização comanda a principal rede de inteligência e espionagem da Aliança.",["faction:Alliance"]="Como membro da Aliança, você pode contar com Ventobravo para obter poder naval, amparo espiritual e uma liderança diplomática vital. Ela é a metrópole mais populosa da Grand Alliance.",["race:Dwarf"]="Como anão, você pode viajar pelo Metrô Correfundo até seus semelhantes no Distrito dos Anões. Eles mantêm laços comerciais e militares estreitos com o reino humano.",["race:Human"]="Como humano, Ventobravo é a última grande sede de poder soberano do seu povo após a queda de Lordaeron, Alterac e Dalaran no norte."},sec={{t="Renascer das cinzas",b="Ventobravo é antiga. Há mais de mil anos, os descendentes dos Arathi a fundaram. Por muitas gerações, ela prosperou, um reino que não precisava da ajuda de ninguém. Então a Horda atravessou o Portal Negro. O continente ao sul foi devastado, e na First War a cidade foi arrasada.\n\nOs sobreviventes seguiram Sir Anduin Lothar rumo ao norte, atravessando o Grande Oceano até Lordaeron. Quando a Horda caiu na Second War, o Rei Terenas Menethil II e a Aliança pagaram para que Ventobravo se reerguesse. A Stonemasons Guild a reconstruiu em pedra branca polida, com canais atravessando seus bairros."},{t="Uma corte dividida",b="Mas a pedra branca esconde uma casa conturbada. A House of Nobles entrou em conflito com a Stonemasons Guild por causa dos salários, e a disputa deixou o reino paralisado por dívidas. Os trabalhadores da guilda se revoltaram. Foram expulsos da própria cidade que haviam construído.\n\nEntão o Rei Varian Wrynn desapareceu a caminho de uma reunião de cúpula. Para impedir que o pânico se espalhasse, a coroa passou a seu filho, o Príncipe Anduin Wrynn. Ele tem dez anos. O Grão-lorde Bolvar Fordragon governa agora como regente e comandante do exército. E a seu lado está a conselheira real, Lady Katrana Prestor."},{t="Coração da Grand Alliance",b="Com Lordaeron tomada pelo Flagelo, os homens voltam suas esperanças para Ventobravo mais do que para qualquer outra cidade. Os fiéis se reúnem na Catedral da Luz. E no Vale dos Heróis, estátuas imponentes homenageiam os Sons of Lothar. Eles atravessaram o Portal Negro e nunca mais foram vistos."},{t="O destino dos pedreiros",b="Os pedreiros voltaram a se reunir em Cerro Oeste sob o comando do mestre da guilda, Edwin VanCleef. Ali se tornaram a Irmandade Défias, bandidos de máscaras vermelhas que agora sufocam as terras agrícolas do reino. Os construtores das muralhas brancas de Ventobravo juraram fazer a House of Nobles pagar por cada pedra."},{t="Um amigo na corte",b="A Irmandade Défias encontrou ajuda dentro da Bastilha Ventobravo. Lorde Gregor Lescovar, da House of Nobles, negociava secretamente com a Irmandade, repassando os planos do reino enquanto ocupava seu lugar entre os lordes que haviam enganado os pedreiros."},{t="Sombras na bastilha",b="Lady Katrana Prestor tem guiado secretamente as decisões da House of Nobles. Ela acirrou o conflito com os pedreiros e ignorou pedidos de auxílio militar de povoações como Cerro Oeste e Montanhas Cristarrubra. Também sussurrou veneno aos ouvidos do Grão-lorde Bolvar, mantendo as legiões de Ventobravo inativas e divididas enquanto a agitação além das muralhas ameaça o trono."}},faq={{q="Quem governa Ventobravo agora?",a="O Príncipe Anduin Wrynn, de dez anos, detém a coroa de Ventobravo, enquanto o Grão-lorde Bolvar Fordragon governa como regente e comanda suas forças militares. Bolvar se apoia nos conselhos da conselheira real Lady Katrana Prestor enquanto o Rei Varian Wrynn permanece desaparecido.",al={"rei atual","quem é o rei","quem lidera ventobravo","rei de ventobravo"}},{q="O que aconteceu com o Rei Varian Wrynn?",a="O Rei Varian desapareceu em circunstâncias suspeitas enquanto navegava para uma reunião diplomática de cúpula em Theramore. Seu desaparecimento foi mantido em segredo para preservar a estabilidade, embora rumores se espalhassem pelas ruas e pelo interior.",al={"onde está varian","rei desaparecido","varian sumiu","varian wrynn desaparecido"}},{q="Por que a cidade foi reconstruída, e por quem?",a="A Horda dos orcs reduziu a cidade original a cinzas durante a First War. Após a Second War, a Aliança de Lordaeron financiou a reconstrução, e o mestre artesão Edwin VanCleef liderou a Stonemasons Guild na construção da capital em pedra branca.",al={"quem reconstruiu ventobravo","stonemasons guild","nova ventobravo","reconstrução da cidade"}},{q="Por que os pedreiros se rebelaram contra a coroa?",a="A House of Nobles contraiu grandes dívidas ao expandir as forças militares de Ventobravo e depois se recusou a pagar à Stonemasons Guild os salários prometidos. Quando Edwin VanCleef exigiu o pagamento, os nobres dissolveram a guilda. Os trabalhadores se revoltaram e foram expulsos da cidade.",al={"origem dos défias","por que os défias estão furiosos","revolta dos pedreiros"}},{q="Quem são as estátuas gigantes no Vale dos Heróis?",a="O Vale dos Heróis homenageia os Sons of Lothar: General Turalyon, Capitã-patrulheira Alleria Correventos, Arquimago Khadgar, Kurdran Martelo Feroz e Danath Matatroll. As estátuas celebram os heróis que atravessaram o Portal Negro rumo a Draenor para selar a fenda e proteger Azeroth.",al={"estátuas na entrada","estátuas do vale dos heróis","estátuas dos sons of lothar"}},{q="Como Ventobravo se conecta a Altaforja?",a="O Metrô Correfundo, uma ferrovia subterrânea, conecta Ventobravo a Altaforja. O Grão-faz-tudo Gelbin Mekkatorque o construiu a pedido do Rei Magni Barbabronze, para que as capitais pudessem comerciar rapidamente e enviar reforços uma à outra na guerra.",al={"metrô correfundo","trem para altaforja","como chegar a altaforja"}},{q="Por que Ventobravo não envia tropas para ajudar Cerro Oeste e Montanhas Cristarrubra?",a="A corte real, orientada por Lady Katrana Prestor, afirma que Ventobravo não pode deslocar tropas de suas muralhas e fronteiras próximas. As finanças do reino estão comprometidas, e as disputas políticas internas paralisaram a House of Nobles, deixando as cidades da região dependentes de suas milícias locais.",al={"exército de ventobravo desaparecido","por que não há ajuda para cerro oeste","reforços recusados"}}},fx={["9beefbfb"]={q="O que é Ventobravo?",a="Ventobravo é a capital do reino humano de Ventobravo e o maior bastião da humanidade que resta em Azeroth. Construída ao norte da Floresta de Elwynn ao longo da costa, ela serve como o coração pulsante, porto principal e centro cultural da Grande Aliança. Reconstruída das cinzas da Primeira Guerra, suas muralhas de pedra fortificadas abrigam artesãos, estudiosos, soldados e refugiados que veem a cidade como um símbolo da perseverança humana.",al={"sobre ventobravo","capital ventobravo","o que é ventobravo"}},edb1c1aa={q="O que aconteceu com Ventobravo no passado?",a="Originalmente fundada há mais de mil anos pelos descendentes da linhagem de Arathor, o reino prosperou por séculos através de conflitos com gnolls e trolls da selva. No entanto, durante a Primeira Guerra, a Horda Orc sitiou a capital. Após o trágico assassinato do Rei Llane Wrynn, a cidade foi invadida, saqueada e queimada até o chão. Sir Anduin Lothar liderou os refugiados sobreviventes para o norte através do mar até Lordaeron, retornando apenas após a Segunda Guerra para recuperar sua terra natal e reconstruí-la.",al={"história de ventobravo","destruição de ventobravo","primeira guerra ventobravo"}},d0a4b7c8={q="Ventobravo é perigosa?",a="Atrás de seus portões colossais e da vigilante Guarda da Cidade, Ventobravo é um dos santuários mais fortemente fortificados do mundo. No entanto, perigos ocultos permanecem dentro. O Cárcere vizinho viu motins violentos, cultistas e ladrões rondam os canais sombrios, e a agitação política provocada pela Irmandade Défias mantém a Casa dos Nobres inquieta. Embora a guerra aberta raramente rompa os muros, corrupção, traição e conspirações ocultas sussurram tanto na Fortaleza quanto nos becos.",al={"ventobravo é seguro","perigo em ventobravo","ameaças a ventobravo"}},["163d181d"]={q="O que é a Irmandade Défias?",a="A Irmandade Défias é uma guilda impiedosa de fora da lei, bandidos, ladrões e piratas que ameaçam abertamente a estabilidade do reino. Eles são reconhecíveis por suas bandanas vermelhas características, usadas para simbolizar o sangue derramado por sua causa. Embora operem fortemente a partir de Cerro Oeste, Montanhas Cristarrubra e das Minas Mortas, seu alcance se estende diretamente até Ventobravo, onde seus espiões e simpatizantes minam a autoridade da coroa e semeiam a discórdia entre as classes trabalhadoras.",al={"irmandade défias","quem são os defias","gangue defias"}},b1d432aa={q="O que é a Catedral da Luz?",a="Elevando-se acima da Praça da Catedral, a Catedral da Luz é o centro espiritual proeminente para a humanidade e a Grande Aliança. Reconstruída após a Segunda Guerra sob o Arcebispo Alonsus Faol e o então bispo Benedictus, ela serve como a sede da Igreja da Sagrada Luz e um quartel-general para a Ordem do Punho de Prata. Paladinos e sacerdotes viajam de todos os reinos para treinar, buscar sabedoria e meditar dentro de seus grandes e pacíficos salões.",al={"catedral da luz","catedral de ventobravo","igreja da luz ventobravo"}},["3414b788"]={q="Como vim parar em Ventobravo?",a="Se você começou sua jornada em Vila Norte e trabalhou seu caminho pela Floresta de Elwynn, a estrada principal o levou direto pelo Vale dos Heróis para os portões fortificados da capital. Se você vem de Dun Morogh ou de Altaforja, provavelmente embarcou no Metrô Correfundo, a maravilha da engenharia gnomica que liga a fortaleza anã diretamente ao Distrito dos Anões sob as montanhas. Viajantes de outros lugares de Azeroth chegam aos portões de Ventobravo após longas jornadas pelos reinos do sul, buscando o último grande bastião da humanidade.",al={"como vim parar aqui","como cheguei a ventobravo","como vou para ventobravo"}},["68c43aeb"]={q="O que devo fazer em Ventobravo?",a="Ventobravo é o coração pulsante da Aliança e um refúgio para descansar, treinar e se abastecer. Sob suas muralhas brancas reluzentes, no entanto, o reino está profundamente fraturado. O Rei Varian Wrynn desapareceu sob circunstâncias misteriosas, deixando o jovem rei Anduin e o Grão-lorde Bolvar Fordragon lutando contra a paralisia política na Fortaleza. Enquanto isso, as fronteiras circundantes em Cerro Oeste e nas Montanhas Cristarrubra clamam por ajuda contra o banditismo desenfreado, e a Irmandade Défias conspira nas sombras. Você está aqui para aprimorar seu ofício, reportar aos líderes de sua facção e emprestar sua espada a um reino sitiado.",al={"por que estou aqui","o que faço aqui","qual meu propósito em ventobravo"}}},fp="14,142,19.590.0,15.532.0,27.258.0,21.287.1,17.236.1,19.351.2,30.238.0,35.216.0,38.251.1,48.261.1,50.272.0,40.223.0,65.267.0"}
P.entries["zone:stranglethorn"] = {n="Selva do Espinhaço",s="A Selva do Espinhaço é uma selva densa e indomada que domina a ponta sul dos Reinos do Leste, ao sul da Floresta do Crepúsculo. Outrora a sede do grande Império Gurubashi, a floresta tropical agora está repleta de ruínas de trolls em ruínas, feras selvagens e acampamentos rivais de goblins, piratas e soldados. O controle da região é disputado ferozmente por tribos de trolls locais, pela Empreendimentos S.A. e por facções rivais que tentam estabelecer pontos de apoio no calor da selva.",h="A Selva do Espinhaço é uma selva densa e indomada que domina a ponta sul dos Reinos do Leste, ao sul da...",kw={"vela sangrenta","angra do butim","grom'gol","gurubashi","kurzen","nesingwary","rezingada","selva do espinhaço","empreendimentos s.a.","zul'gurub"},ang={["class:Hunter"]="A margem norte do rio abriga o famoso caçador de caça grossa Rosarães Guima, que desafia atiradores a testar sua coragem rastreando os mais ferozes raptores, panteras e crocoliscos da selva.",["faction:Alliance"]="Os esforços históricos de Ventobravo para conquistar e pacificar a selva sobrecarregaram o reino com pesadas dívidas e, hoje, seus interesses são defendidos apenas por amotinados em apuros no Acampamento dos Rebeldes.",["faction:Horde"]="O Acampamento Grom'gol oferece à Horda uma fortaleza estratégica indispensável no continente meridional, abastecida diretamente por zepelins de Durotar e da Cidade Baixa.",["profession:Herbalism"]="A copa úmida da floresta nutre uma flora valiosa, tornando as margens dos rios e as costas locais ideais para colher Ácera-agreste, Folha-da-névoa, Espinheira-dourada e Lótus Roxo.",["race:Troll"]="O Espinhaço é o berço ancestral dos trolls da selva, cujo antigo império Gurubashi sucumbiu à guerra civil após adorar Hakkar, o Esfolador de Almas, empurrando tribos como a Lançanegra para além dos mares."},sec={{t="Ruínas de um Império",b="Por milênios, a selva foi governada pelo poderoso Império Gurubashi a partir de sua capital, Zul'Gurub. Esse domínio se desfez quando sacerdotes radicais evocaram Hakkar, o Esfolador de Almas, mergulhando a região em uma guerra civil catastrófica. Embora os Zandalari tenham intervindo para esmagar a revolta do deus de sangue, o império se fragmentou de forma irreparável. Hoje, a selva está infestada por facções sucessoras em guerra — principalmente os Bloodscalp no noroeste e os Rachacrânio no leste —, ambas massacrando forasteiros com fervor para recuperar seu lar ancestral."},{t="Piratas e Exploradores",b="Onde as ruínas antigas jazem em silêncio, a ganância comercial preenche o vazio. No extremo sul fica a Angra do Butim, um refúgio movimentado construído pelo Cartel Bondebico e administrado pelos Blackwater Raiders sob o comando do Barão Rezingada. O porto serve como o principal centro do comércio do sul e do transporte marítimo, embora seja perpetuamente sitiado pelos rivais Bucaneiros da Vela Sangrenta, ancorados ao longo da costa. Mais para o interior, a Empreendimentos S.A. desmata a selva agressivamente em busca de madeira e minera as colinas atrás de raros cristais cantantes."},{t="Uma Terra Selvagem Disputada",b="A Selva do Espinhaço serve como uma das fronteiras mais voláteis do mundo. A Horda comanda o Acampamento Grom'gol na costa oeste, ligado por zepelins goblins a Durotar e às Clareiras de Tirisfal, enquanto legalistas da Aliança operam a partir do Acampamento dos Rebeldes para caçar o Coronel Kurzen, que desertou. Entre a folhagem densa, o lendário caçador Rosarães Guima lidera audaciosas expedições de caça grossa, atraindo viajantes a encontros perigosos com panteras à espreita, macacos enormes e soldados inimigos."},{t="A Loucura na Selva",b="Nem todas as ameaças no norte do Espinhaço são feras selvagens. O Coronel Kurzen, outrora um comandante condecorado enviado por Ventobravo, enlouqueceu na mata e estabeleceu um reduto mercenário tirânico. Na verdade, a mente de Kurzen foi enredada pela feitiçaria do Olho da Mente, um artefato empunhado pelo ogro mago Mai'Zoth, da vizinha Gruta de Mosh'Ogg, mergulhando a expedição em pura insanidade e levando seus antigos homens a formar o dissidente Acampamento dos Rebeldes."}},faq={{q="Quem controla a Selva do Espinhaço?",a="Nenhum poder único governa a selva. A região é dividida entre tribos rivais de trolls da selva, como os Bloodscalp e os Rachacrânio, acampamentos renegados como o Complexo do Kurzen, os mercenários da Empreendimentos S.A. e postos militares dispersos da Horda e da Aliança. O maior assentamento urbano é o porto goblin neutro da Angra do Butim, governado pelo Barão Rezingada e pelos Blackwater Raiders.",al={"quem controla a selva do espinhaço","quem governa a selva do espinhaço","facções da selva do espinhaço"}},{q="O que é a Angra do Butim?",a="A Angra do Butim é uma ampla cidade portuária construída nos penhascos ao sul do Cabo do Espinhaço. Originalmente um assentamento humano conhecido como Angra Aguanegra, foi capturada por trolls e, com o tempo, garantida pelo Cartel Bondebico. Hoje, o Barão Rezingada e o Mestre de Frota Chifre do Mar a administram como um porto comercial neutro que conecta viajantes à Vila Catraca através do Grande Oceano.",al={"o que é angra do butim","porto de angra do butim","quem comanda angra do butim"}},{q="Por que o Coronel Kurzen desertou?",a="O Coronel Kurzen liderou uma expedição à selva em nome de Ventobravo, mas sua mente sucumbiu à influência de Mai'Zoth, um ogro mago que empunhava uma poderosa relíquia chamada Olho da Mente. Kurzen tornou-se cada vez mais errático e despótico, forçando soldados leais, como o Tenente Doren, a romper laços e formar o Acampamento dos Rebeldes para detê-lo.",al={"por que kurzen é mau","o que aconteceu com kurzen","história de kurzen"}},{q="O que é Zul'Gurub?",a="Zul'Gurub é a antiga capital do Império Gurubashi, repleta de templos e encravada no nordeste da Selva do Espinhaço. Foi o epicentro da guerra civil que destruiu o império quinze séculos atrás, após sacerdotes radicais evocarem o deus de sangue Hakkar, o Esfolador de Almas. Embora abandonada há muito tempo às trepadeiras e ruínas, rituais sombrios continuam a ameaçar seus salões.",al={"o que é zg","história de zul'gurub","capital dos gurubashi"}},{q="O que era a Pedra das Marés?",a="A Pedra das Marés é uma relíquia lendária da história antiga dos Gurubashi, descoberta na costa por um guerreiro troll. Ela concedia ao seu portador domínio sobre a água e invocações elementais semelhantes às de um poderoso mago, rendendo ao usuário o título de 'Portador das Marés'. No entanto, carregava uma maldição que fazia o portador desaparecer lentamente do reino físico, levando cada usuário a caminhar em direção ao mar e sumir para sempre.",al={"pedra das marés","lenda do portador das marés","pedra da água gurubashi"}},{q="Como viajo até a Selva do Espinhaço?",a="Os viajantes podem caminhar para o sul atravessando a fronteira do rio a partir da Floresta do Crepúsculo até o norte da Selva do Espinhaço. A Horda mantém torres diretas de zepelim conectando o Acampamento Grom'gol a Durotar e às Clareiras de Tirisfal. Viajantes de Kalimdor também podem embarcar na embarcação mercante regular que navega entre a Vila Catraca, nos Sertões, e a Angra do Butim.",al={"como chegar à selva do espinhaço","chegar à selva do espinhaço","viagem selva do espinhaço"}}},fp="18,166,18.455.0,22.346.0,22.414.0,25.340.1,32.270.0,18.322.0,32.268.1,18.294.0,32.328.0,38.256.0"}
P.entries["zone:swampofsorrows"] = {n="Pântano das Mágoas",s="O Pântano das Mágoas é uma área úmida turva e salobra situada entre a Trilha do Vento Morto e a árida Barreira do Inferno. Antigamente a extensão norte do antigo Pântano Negro, seus pântanos incrustados de sal abrigam uma fauna perigosa, dragonspawn verdes e o arruinado Templo de Atal'Hakkar, submerso sob o Poço de Lágrimas. Enquanto a Horda mantém a guarnição fortificada de Pedregal, a Aliança não possui nenhum refúgio seguro no lodaçal, deixando a vastidão selvagem em grande parte indomada.",h="O Pântano das Mágoas é uma área úmida turva e salobra situada entre a Trilha do Vento Morto e a árida...",kw={"black morass","broken","o refúgio","os perdidos","poço de lágrimas","penumbra das mágoas","pedregal","templo submerso","pântano das mágoas","templo de atal'hakkar"},ang={["faction:Alliance"]="Sem um posto avançado para servir de base, viajar pelo pântano é uma empreitada isolada e hostil que exige preparação cuidadosa a partir de Vila Sombria ou da Bastilha de Etergarde.",["faction:Horde"]="Pedregal serve como seu reduto avançado vital no continente meridional, oferecendo rotas diretas de mantícora para Karrath, Monte Candente, Acampamento Grom'gol, Angra do Butim e Rog'mar nas Sendas do Rio.",["profession:Blacksmithing"]="Aventureiros resistentes podem coletar ferro, ouro, mithril e truesilver ao longo dos penhascos montanhosos que emolduram as bordas norte e sul do pântano.",["profession:Herbalism"]="O pântano é um dos poucos lugares em Azeroth rico em blindweed, além de generosas vegetações de liferoot, fadeleaf e stranglekelp.",["race:Troll"]="As ruínas submersas de Atal'Hakkar permanecem como uma terrível lembrança da magia de sangue sombria que fragmentou o Império Gurubashi e atraiu a ira dos Aspectos Dragônicos."},sec={{t="Uma História Submersa",b="Muito antes da chegada da Horda dos Orcs, estes pântanos formavam a metade norte de uma enorme área úmida conhecida como Pântano Negro. Após a fragmentação do Império Gurubashi, os fanáticos trolls Atal'ai fugiram para o lodaçal para erguer o Templo de Atal'Hakkar, com a intenção de evocar seu sanguinário loa, Hakkar, o Esfolador de Almas. Pressentindo a catástrofe, o Aspecto Ysera libertou seus poderes, afundando a pirâmide amaldiçoada sob as águas do Poço de Lágrimas. Guardiões da Revoada Dragônica Verde liderados por Eranikus foram posicionados para vigiar atentamente a estrutura submersa. Mais tarde, quando o cataclismo do Portal Negro crestou o pântano meridional, transformando-o na Barreira do Inferno, este charco ao norte ganhou seu atual e melancólico nome."},{t="Postos Avançados e Exilados Broken",b="Pedregal serve como o principal ponto de apoio civilizado no pântano. Originalmente estabelecido durante a First War ao lado dos assentamentos agora arruinados de Rockard e Kyross, o posto avançado foi reconstruído sob o comando de Thrall para servir como o ponto de concentração mais ao sul da Horda nos Reinos do Leste. Além das paliçadas de Pedregal, viajantes estranhos vagam pelo charco. Um grupo de retardatários draenei isolados em Azeroth sucumbiu à saudade de casa e à loucura, degenerando em ferozes Perdidos. No entanto, um pequeno enclave de exilados Broken lúcidos resiste no Refúgio, cautelosos, mas dispostos a negociar pacificamente com viajantes."},{t="O Lodaçal que Afunda",b="Sobreviver no pântano exige vigilância constante contra sua fauna predatória. Pântanos profundos escondem crocoliscos em investida, aranhas venenosas, jaguares-do-pântano à espreita e bestas-do-lodo errantes incrustadas de detritos pantanosos. Cavernas costeiras e a Praia Brumalga estão infestadas de murlocs ferozes, enquanto a maré carregada de sal avança continuamente terra adentro, preservando troncos podres sob grossas crostas salobras. Mais ao leste fica a Penumbra das Mágoas, onde dragonspawn de elite agressivos guardam ferozmente os acessos ao Templo Submerso, atacando qualquer um que se aproxime de sua vigília."}},faq={{q="Como chego ao Pântano das Mágoas?",a="A rota terrestre mais comum segue para o leste a partir de Vila Sombria, na Floresta do Crepúsculo, atravessando o perigoso e assombrado desfiladeiro da Trilha do Vento Morto e descendo direto para o pântano. Como alternativa, viajantes vindos do sul podem caminhar para o norte pela estrada principal que sai da Barreira do Inferno.",al={"como chegar ao pântano das mágoas","estrada do pântano das mágoas","como chegar a pedregal"}},{q="Por que o Templo de Atal'Hakkar está debaixo d'água?",a="Séculos atrás, o sacerdócio Atal'ai tentou evocar Hakkar, o Esfolador de Almas para Azeroth. Ysera, o Aspecto Dragônico da Revoada Verde, descobriu seus ritos de sangue demoníacos e afundou o templo inteiro no pântano para evitar o desastre, deixando para trás dragonspawn verdes para guardar os salões submersos.",al={"por que o templo submerso afundou","quem afundou o templo","história do templo submerso"}},{q="O que é Pedregal?",a="Pedregal foi um dos primeiros assentamentos construídos pela Horda dos Orcs após cruzar o Portal Negro durante a First War. Embora tenha sido devastado durante os combates, foi recentemente retomado e reconstruído sob as ordens de Thrall para ancorar a logística da Horda perto da Barreira do Inferno.",al={"história de pedregal","base orc no pântano","quem construiu pedregal"}},{q="Existe algum assentamento da Aliança aqui?",a="Não. A Aliança não mantém cidades, guardas ou rotas de voo no Pântano das Mágoas. Aventureiros da Aliança operando na área devem se estabelecer a partir de Vila Sombria, na Floresta do Crepúsculo, a oeste, ou da Bastilha de Etergarde, na Barreira do Inferno, ao sul.",al={"base da aliança no pântano das mágoas","rota de voo da aliança no pântano","onde fica o acampamento da aliança"}},{q="Quem são os estranhos humanoides mutantes no pântano?",a="Eles são draenei que ficaram isolados em Azeroth após o colapso do Portal Negro. Separados de seu mundo, a maioria enlouqueceu de desespero e se transformou em hostis Perdidos. Um pequeno grupo de exilados Broken sãos se refugiou a noroeste, no Refúgio, escolhendo a sobrevivência neutra em vez da fúria cega.",al={"quem são os perdidos","o que é o refúgio","draenei no pântano"}},{q="O que é a Penumbra das Mágoas?",a="A Penumbra das Mágoas é a densa faixa de pântano situada diretamente a leste do Poço de Lágrimas. Ela serve como área de patrulha para dragonspawn verdes de elite e filhotes que repelem mortais violentamente para proteger os segredos do Templo Submerso.",al={"área dos dragões no pântano das mágoas","dragões da penumbra das mágoas","dragonspawn verdes no pântano"}}},fp="16,249,17.556.0,26.487.0,16.475.0,36.188.0,44.259.0,16.248.0,40.179.0,51.307.0,19.185.0"}
P.entries["zone:tanaris"] = {n="Tanaris",s="Tanaris é um deserto vasto e sufocante que se estende pelos limites meridionais de Kalimdor, caracterizado por dunas de areia ondulantes e um calor abrasador. No seu coração fica Geringontzan, um entreposto comercial neutro administrado pelos goblins do Cartel Bondebico. Além dos povoados movimentados, as dunas ocultam trolls da areia hostis, perigosas colmeias de silitídeos e o domínio oculto da revoada dragônica bronze.",h="Tanaris é um deserto vasto e sufocante que se estende pelos limites meridionais de Kalimdor, caracterizado...",kw={"cavernas do tempo","deserto","freebooters","geringontzan","nozdormu","fúria da areia","silitídeo","bondebico","tanaris","uldum","zul'farrak"},ang={["faction:Alliance"]="Sem grandes fortalezas da Aliança entre o Pântano Vadeoso e Feralas, o mestre de voo da Aliança na neutra Geringontzan serve como um ponto de apoio vital para viagens pelo sul de Kalimdor.",["faction:Horde"]="Geringontzan oferece aos batedores da Horda um conveniente entreposto comercial que liga as rotas da Aldeia Vento Livre e da Aldeia Mojache diretamente aos ermos infestados de silitídeos do extremo sul.",["profession:Herbalism"]="O calor seco nutre a esquiva Ignídea pelas dunas movediças, enquanto ruínas sombreadas e oásis úmidos fornecem abrigo para o valioso Lótus Roxo.",["profession:Mining"]="Os penhascos áridos e afloramentos rochosos que cercam as dunas oferecem ricas jazidas de Mítril, Veraprata, Ferro e Ouro, além de depósitos dispersos de Tório Pequeno nas regiões mais profundas.",["race:Troll"]="Ver os Sandfury de Zul'Farrak oferece aos trolls um vislumbre cru de seus primos ancestrais, que se endureceram em uma cultura brutal no isolamento do deserto."},sec={{t="Um Mar de Dunas",b="Tanaris é uma vastidão árida e crestada pelo sol. Dentro da cidade murada de Zul'Farrak, os calejados trolls Sandfury guardam seu domínio isolado. Hoje, o chão do deserto é dominado por hienas, basiliscos e escorpidídeos, enquanto túneis subterrâneos serpenteiam sob a terra escaldante."},{t="Empreendimento Goblin",b="Como Tanaris fica tão perto de Kezan, sua terra natal insular, quanto o continente permite, o Cartel Bondebico estabeleceu um próspero empreendimento aqui. Do oásis murado de Geringontzan às docas litorâneas do Porto de Bondebico, os goblins mantêm estrita neutralidade, acolhendo as moedas tanto da Aliança quanto da Horda. Sua paz é mantida pela força bruta dos seus capangas, embora ameaças desonestas como os Southsea Freebooters hostilizem constantemente o transporte marítimo e os sítios de escavação ao longo da costa."},{t="Mistérios Antigos e Perigos Crescentes",b="As areias escondem poderes muito mais antigos do que os impérios mortais. Nos confins orientais ficam as Cavernas do Tempo, o domínio ancestral de Nozdormu e de sua revoada dragônica bronze, cujos draconídeos ocasionalmente podem ser vistos planando nas correntes térmicas do deserto. Ao sul, imponentes portões de pedra marcam o complexo titânico de Uldum. No entanto, um perigo mais sombrio se agita em ninhos subterrâneos como a Fenda Hazzali e o Covil Nóxio, onde enxames rastejantes de silitídeos começaram a cavar para fora através das areias."}},faq={{q="Como viajo para Tanaris?",a="Viajantes a pé viajam através das Mil Agulhas até a Chapada Cintilante. Uma passagem na montanha esculpida através dos penhascos no extremo sul das salinas leva diretamente para baixo no deserto, deixando você imediatamente à vista das muralhas de Geringontzan. Um navio também navega do Porto Detonapavio nas Sendas do Rio até o Porto de Bondebico na costa leste.",al={"como chegar a tanaris","chegando a tanaris","entrada de tanaris"}},{q="Por que Geringontzan é neutra para ambas as facções?",a="Geringontzan é governada pelo Cartel Bondebico, cuja única lealdade é ao lucro. Para maximizar o comércio e proteger as rotas comerciais pelo deserto, os goblins impõem uma neutralidade estrita, empregando capangas para espancar qualquer um tolo o bastante para iniciar brigas de facção dentro dos muros de sua cidade.",al={"por que geringontzan é neutra","a horda e a aliança podem ir a geringontzan","neutralidade dos goblins em geringontzan"}},{q="O que é Zul'Farrak?",a="Zul'Farrak é a capital desértica fortificada dos trolls Sandfury. Isolada há muito tempo no deserto, a tribo Sandfury tornou-se hostil a todos os forasteiros, guardando suas piscinas sagradas e santuários misteriosos contra aventureiros invasores.",al={"o que é zul'farrak","quem vive em zul'farrak","cidade dos trolls da areia"}},{q="O que são as criaturas insetoides que fazem ninhos pelo deserto?",a="As criaturas insetoides são silitídeos, escavadores coloniais monstruosos que constroem vastas colmeias como a Fenda Hazzali e o Covil Nóxio. Sua presença emergente em Tanaris inquietou observadores como o Topógrafo Sênior Secamolha, lembrando os horrores antigos da Guerra das Areias Movediças.",al={"o que são os insetos em tanaris","colmeias de insetos em tanaris","silitídeos em tanaris"}},{q="O que há por trás das gigantescas portas de pedra no sul?",a="Os portões monumentais no Vale dos Vigilantes marcam a entrada para Uldum, uma lendária instalação de pesquisa e propriedade dos antigos titãs. A entrada permanece firmemente selada, guardada por colossais sentinelas de pedra e examinada de longe por estudiosos curiosos e goblins.",al={"portões gigantes no sul de tanaris","portões de ruínas de Uldum","portão dos titãs em tanaris"}},{q="Quem habita as Cavernas do Tempo?",a="As Cavernas do Tempo servem como o covil ancestral da revoada dragônica bronze e de seu aspecto, Nozdormu. A partir dessas profundezas ocultas e sinuosas, os dragões atemporais vigiam o fluxo da história, ocasionalmente patrulhando os céus bem acima das dunas do sul.",al={"história das cavernas do tempo","o que há nas cavernas do tempo","dragões em tanaris"}}},fp="7,203,14.233.0,17.333.0,35.335.0,27.288.0,42.224.0,19.175.0,56.255.0,52.219.0,38.232.0"}
P.entries["zone:teldrassil"] = {n="Teldrassil",s="Teldrassil, que significa \"Coroa da Terra\", é uma nova e colossal Árvore do Mundo erguida na costa noroeste de Kalimdor. Cultivada pelos druidas no rescaldo da Terceira Guerra, seus galhos monumentais sustentam uma vasta natureza selvagem sob a penumbra e Darnassus, a capital dos elfos noturnos. No entanto, sob sua copa tranquila e banhada pelo luar, uma corrupção rastejante começou a se agitar.",h="Teldrassil, que significa \"Coroa da Terra\", é uma nova e colossal Árvore do Mundo erguida na costa noroeste...",kw={"círculo dos ancientes","coroa da terra","darnassus","dolanaar","fandral guenelmo","rut'theran","umbravale","teldrassil","arvore do mundo"},ang={["class:Druid"]="Com Malfurion preso no Sonho Esmeralda, o Arquidruida Fandral Guenelmo lidera o Círculo Cenariano aqui, embora muitos druidas temam que Teldrassil tenha sido erguida às pressas.",["faction:Alliance"]="Teldrassil serve como o reduto mais ao norte da Aliança em Kalimdor, ancorando a comunicação naval e o comércio entre Darnassus e os reinos do continente.",["profession:Herbalism"]="Sem nenhum mineral ou minério, a copa verdejante da árvore compensa isso ao funcionar como um paraíso para coletores de Botão-da-paz, Folha-prata e Raiz-da-terra.",["race:NightElf"]="Esta árvore colossal é o novo recomeço do seu povo após a devastação do Monte Hyjal, mas a ausência das bênçãos dos Aspectos torna sua defesa um dever urgente."},sec={{t="Uma Copa Sobre o Mar",b="Teldrassil não é apenas uma árvore; é um ecossistema elevado que se ergue imponente em meio às águas do Mar Velado. Seus galhos descomunais abrigam colinas ondulantes, rios caudalosos alimentados pelo orvalho da manhã, lagos enevoados e clareiras ancestrais densas. Em sua extremidade ocidental fica Darnassus, a grandiosa capital dos kaldorei. Na base de seu tronco monumental está a Vila de Rut'theran, conectada à copa por um portal místico e servindo como o principal porto da ilha."},{t="A Recusa dos Aspectos",b="Após o sacrifício de Nordrassil durante a Terceira Guerra e o misterioso desaparecimento do Shan'do Malfurion Tempesfúria no Sonho Esmeralda, o Arquidruida Fandral Guenelmo convenceu o Círculo dos Ancientes a plantar uma substituta. Guenelmo esperava devolver aos kaldorei sua imortalidade perdida. No entanto, Nozdormu e os Aspectos Dragônicos consideraram a iniciativa arrogante e recusaram suas bênçãos. Sem essa proteção vital, o crescimento de Teldrassil sofreu com imperfeições não naturais."},{t="Uma Enfermidade Rastejante",b="Apesar de sua majestade exterior, a jovem Árvore do Mundo abriga uma enfermidade sombria. A fauna local se tornou violenta: tribos outrora pacíficas de furbolgs caíram na loucura, grells deformados se multiplicam nos túmulos e sátiros vis realizam ritos sombrios em recessos como a Pedra Vil. Mais abaixo, nas praias de Costa Negra, gigantes do mar, debulhadores e tartarugas encalham para fugir das águas contaminadas ao redor da árvore. Naturalistas e sentinelas agora trabalham freneticamente pela copa para identificar a sombra que lentamente estrangula seu novo lar."}},faq={{q="Por que Teldrassil foi cultivada?",a="Depois que Nordrassil foi devastada no final da Terceira Guerra, os elfos noturnos perderam sua imortalidade. O Arquidruida Fandral Guenelmo pressionou o Círculo dos Ancientes e os druidas cenarianos a plantar uma nova Árvore do Mundo no mar, com o objetivo de restaurar o que seu povo havia perdido.",al={"por que foi feita","quem criou teldrassil","origem de teldrassil"}},{q="Por que Teldrassil não restaurou a imortalidade dos elfos noturnos?",a="Nordrassil concedia a imortalidade originalmente porque Nozdormu, o Atemporal, a abençoou. Quando Teldrassil foi erguida, Nozdormu julgou o desejo dos elfos noturnos como arrogante e se recusou a conceder sua bênção à nova árvore.",al={"imortalidade","por que nao sao imortais","bencao de nozdormu"}},{q="Como sair de Teldrassil?",a="Os viajantes devem atravessar Darnassus até o portal rosa nos Jardins do Templo, que os transporta para a Vila de Rut'theran na base do tronco. De Rut'theran, um navio navega pelo mar até Auberdine, no continente de Costa Negra, além das rotas de hipogrifos disponíveis.",al={"como sair","sair da arvore","barco de teldrassil"}},{q="Por que não há jazidas de mineração em Teldrassil?",a="Toda a zona se situa sobre os galhos vivos e a madeira de uma colossal Árvore do Mundo, em vez de rocha continental natural. Como não há crosta subterrânea rochosa, veios de metal ou depósitos de minério não se formam aqui, embora as ervas floresçam em grande abundância.",al={"onde tem cobre","sem minerio","mineracao em teldrassil"}},{q="O que está fazendo os furbolgs e as feras enlouquecerem?",a="Uma presença sinistra começou a se infiltrar nas raízes não abençoadas de Teldrassil. A doença corrompeu as águas e a flora locais, levando os outrora pacíficos lenhosos e a tribo furbolg Gnarlpine a uma agressividade frenética, enquanto remanescentes de sátiros cultivam ativamente a corrupção.",al={"furbolgs corrompidos","gnarlpine loucos","o que e a corrupcao"}},{q="O que é Umbravale?",a="Umbravale é um vale protegido e isolado nos galhos orientais de Teldrassil, ao redor da grande árvore Aldrassil. Ele serve como um santuário tranquilo onde os jovens elfos noturnos iniciam seu treinamento antes de se aventurarem pelo mundo afora.",al={"umbravale","area inicial","zona de aldrassil"}}},fx={["11a6d5e5"]={q="O que é Teldrassil?",a="Teldrassil é uma imensa Árvore do Mundo cultivada em uma ilha na costa noroeste de Kalimdor. Seu tronco gigantesco ergue-se do Mar Velado, espalhando-se em galhos tão vastos que sustentam um reino florestal inteiro de lagos, rios e a capital de Darnassus no topo de sua copa.",al={"o que é este lugar","sobre teldrassil","me conte sobre teldrassil"}},["313cd5a2"]={q="O que aconteceu em Teldrassil?",a="Após a Terceira Guerra e os danos causados a Nordrassil do Monte Hyjal, o druida Malfurion Tempesfúria desapareceu. Na ausência dele, o Arquidruida Fandral Guenelmo convenceu o Círculo dos Anciões a cultivar uma nova Árvore do Mundo para substituir o que foi perdido. Embora tenha crescido com sucesso, uma corrupção rastejante começou desde então a manchar seus galhos.",al={"história de teldrassil","como teldrassil foi criada","eventos de teldrassil"}},c5e34e84={q="Quem vive ou administra Teldrassil?",a="Teldrassil é o refúgio ancestral e a atual pátria dos elfos noturnos. Espiritual e civicamente, a Alta Sacerdotisa Tyrande Murmuréolo e o Arquidruida Fandral Guenelmo guiam seu povo a partir da capital de Darnassus, apoiados pela Irmandade de Eluna, druidas Cenarianos e guerreiros Sentinelas protegendo os assentamentos na floresta.",al={"quem lidera teldrassil","líderes de teldrassil","quem vive aqui"}},b86e706e={q="Teldrassil é perigosa?",a="Embora protegida pelas Sentinelas, Teldrassil é cada vez mais perigosa. Uma aflição sombria enlouqueceu as feras nativas e os furbolgs locais, enquanto sátiros maliciosos, harpias sanguinárias e timberlings desenfreados ameaçam os assentamentos além das estradas patrulhadas.",al={"é seguro aqui","ameaças em teldrassil","perigos de teldrassil"}},["2863bed2"]={q="Por que se chama Teldrassil?",a="Na língua Darnassiana dos elfos noturnos, Teldrassil traduz-se diretamente como 'coroa da terra'. Foi nomeada em homenagem ao seu papel como uma Árvore do Mundo monumental destinada a acolher e proteger sua civilização.",al={"o que significa teldrassil","significado do nome teldrassil"}},["514d23b0"]={q="Quem é Fandral Guenelmo?",a="Fandral Guenelmo é o Arquidruida que assumiu a liderança dos druidas elfos noturnos após o desaparecimento de Malfurion Tempesfúria no Sonho Esmeralda. Apaixonado, teimoso e agressivo, Fandral defendeu o plantio de Teldrassil e frequentemente entra em conflito com a Alta Sacerdotisa Tyrande Murmuréolo sobre políticas.",al={"quem é o arquidruida","lore de fandral guenelmo","guenelmo"}},["52c333ac"]={q="Quem é Tyrande Murmuréolo?",a="Tyrande Murmuréolo é a Suma Sacerdotisa da deusa Eluna e líder suprema do povo elfo noturno. Tendo guiado seu povo por dez mil anos através da Longa Vigília e da Terceira Guerra, ela agora governa a partir do Templo da Lua em Darnassus.",al={"quem é tyrande","suma sacerdotisa tyrande","quem lidera os elfos noturnos"}},["29b1e9e4"]={q="Como vim parar em Teldrassil?",a="Se você é um elfo noturno, esta colossal Árvore do Mundo é o novo lar do seu povo. Após sacrificar Nordrassil e sua antiga imortalidade no topo do Monte Hyjal para derrotar a Legião Ardente, os kaldorei se realocaram na costa noroeste de Kalimdor. O Arquidruida Fandral Guenelmo e o Círculo dos Anciões cultivaram Teldrassil no Mar Velado para dar à sua raça um refúgio renovado, e você começou sua jornada dentro de seus galhos verdejantes em Umbravale. Se você viajou para cá do exterior, provavelmente navegou até o porto da Vila de Rut'theran na base da árvore vindo da Costa Negra, depois passou pelo portal brilhante que leva os viajantes diretamente para a copa.",al={"como cheguei a teldrassil","como cheguei aqui","por que estou começando aqui"}},["8381279f"]={q="O que devo fazer em Teldrassil?",a="Você foi chamado para proteger a jovem Árvore do Mundo e descobrir a doença sombria que perturba seus galhos. Apesar de suas florestas exuberantes, uma corrupção sinistra está se instalando: os timberlings estão se tornando agressivos, os furbolgs pacíficos da tribo Pinho Retorcido estão caindo na loucura, e sátiros vis espreitam em matagais sombrios como Pedra Vil. Começando em Umbravale e ajudando assentamentos como Dolanaar, você deve ajudar as Sentinelas e druidas a restaurar o equilíbrio. Você reabastecerá os Poços da Lua sagrados, erradicará a praga corrompida e aprenderá a história do seu povo antes de se aventurar na capital de Darnassus e atravessar o mar até o continente de Kalimdor.",al={"o que fazer em teldrassil","por que estou aqui","qual minha missão aqui"}}},fp="10,168,21.379.0,26.466.0,17.410.1,25.260.0,52.182.0,28.253.0,44.210.0,52.248.0,19.205.0"}
P.entries["zone:thousandneedles"] = {n="Mil Agulhas",s="Mil Agulhas é um cânion extenso de pilares escarpados de arenito e planícies de sal crestadas pelo sol no sul de Kalimdor. Tribos de taurens se apegam a povoados no topo de imponentes platôs para escapar de bandos agressivos de centauros, enquanto engenhoqueiros gnomos e goblins pilotam carros-foguete em alta velocidade pelo leito marinho seco da Chapada Cintilante.",h="Mil Agulhas é um cânion extenso de pilares escarpados de arenito e planícies de sal crestadas pelo sol no sul...",kw={"vigia do rochedo chifre longo","pináculo da nuvem negra","xabu latafuso","aldeia vento livre","o grande elevador","totem sombrio","kravel barbakarvão","circuito da ilusão","relé","chapada cintilante","mil agulhas"},ang={["faction:Horde"]="O Grande Elevador conecta os Sertões à sua fortaleza na Aldeia Vento Livre, funcionando como uma fronteira estratégica ao sul contra os clãs de centauros e os taurens rebeldes.",["profession:Engineering"]="As planícies de sal são um destino de peregrinação para engenhoqueiros que procuram estudar combustível de foguete, peças de veículos e propulsão de alta velocidade no Circuito da Ilusão.",["race:Gnome"]="O Circuito da Ilusão, na Chapada Cintilante, é a principal chance de sua facção demonstrar a precisão e a elegância da engenharia gnômica contra as engenhocas grosseiras dos goblins.",["race:Tauren"]="A Aldeia Vento Livre ergue-se como um lembrete do quão alto seu povo precisou subir para escapar do massacre dos centauros, servindo também de ponto de apoio contra os traiçoeiros Totem Sombrio no Pináculo da Nuvem Negra."},sec={{t="Uma floresta de pedra",b="Antes que a Grande Cisão despedaçasse a antiga Kalimdor, este território era um cânion fluvial verdejante alimentado por cursos d'água continentais que fluíam em direção ao mar. O cataclismo rasgou o continente, empurrando o leito do rio acima do lençol freático e alterando seu curso até restarem apenas pedra seca e pináculos de arenito. Hoje, dezenas de esguias colunas cilíndricas erguem-se do fundo do cânion como uma floresta petrificada. Os taurens se estabeleceram nos cumes, estendendo pontes de corda precárias entre os picos para criar aldeias fora do alcance dos saqueadores centauros hostis que patrulham o fundo sombrio do desfiladeiro."},{t="Perigo nos platôs",b="No topo dos pináculos em forma de agulha, a vida está longe de ser pacífica. Na Aldeia Vento Livre, os taurens leais à Horda enfrentam não apenas serpentes aladas predatórias e mantícoras de Alcândora, mas também seus próprios parentes traiçoeiros: o belicoso clã Totem Sombrio, entrincheirado no Pináculo da Nuvem Negra. O Vigia do Rochedo Chifre Longo supervisiona a defesa do platô, em busca de combatentes corajosos para atacar os agitadores Totem Sombrio e proteger as frágeis pontes que conectam os picos. Ao norte, os enormes guinchos mecânicos d'O Grande Elevador transportam viajantes a partir dos Sertões Meridionais, embora cruzar o fundo do cânion continue sendo uma empreitada mortal."},{t="O Circuito da Ilusão",b="A sudeste, os paredões do cânion se abrem para a Chapada Cintilante, uma enorme e ressecada planície de sal situada abaixo do nível do mar. Nessa extensão árida e de uma brancura ofuscante, gnomos e goblins mantêm uma neutralidade incômoda ao redor do Circuito da Ilusão. Engenheiros rivais, Relé e Xabu Latafuso, disputam corridas de carros-foguete experimentais sobre o sal duro para decidir qual raça detém a superioridade tecnológica. Essa parada atrai canalhas, vigaristas como Kravel Barbakarvão e caçadores em busca dos resistentes escorpiões, tartarugas e basiliscos que vagam pela bacia causticante."}},faq={{q="Como Mil Agulhas recebeu esse nome?",a="A zona deve seu nome às dezenas de pináculos cilíndricos colossais de arenito que brotam do fundo do cânion. Esculpidas originalmente pelas correntes caudalosas dos rios antes da Grande Cisão, essas torres geológicas hoje parecem uma floresta de agulhas gigantes.",al={"por que se chama mil agulhas","origem dos pilares de agulha","história dos pináculos"}},{q="Como se desce até Mil Agulhas vindo dos Sertões?",a="Os viajantes utilizam O Grande Elevador, uma imensa estrutura com duas cabines operada por guardas da Horda na fronteira sul dos Sertões. Saltar da beirada é fatal, portanto é essencial aguardar a plataforma. Os viajantes da Aliança também podem chegar a pé pelo oeste, passando por Thalanaar, em Feralas.",al={"como chegar em mil agulhas","entrada d'o grande elevador","elevador para mil agulhas"}},{q="Por que os taurens vivem no topo dos platôs?",a="Os bandos de guerra centauros quase levaram os nômades taurens à extinção no passado. Construir postos avançados como a Aldeia Vento Livre no alto de pilares de pedra inacessíveis os manteve a salvo de investidas terrestres. Eles conectaram os platôs por meio de pontes pênseis de madeira, possibilitando viagens em grandes altitudes, muito acima dos predadores e saqueadores lá embaixo.",al={"por que taurens ficam nos pilares","história da aldeia vento livre","terreno elevado dos taurens"}},{q="O que é o Circuito da Ilusão?",a="O Circuito da Ilusão é um campo de provas de engenharia situado na planície de sal da Chapada Cintilante. Engenhoqueiros gnomos e goblins apostam corrida com carros experimentais movidos a foguete pelo leito plano de sal para resolver a rivalidade de longa data sobre qual raça constrói as melhores máquinas.",al={"pista da chapada cintilante","corrida de gnomos e goblins","pista de carro-foguete"}},{q="Qual é a presença do Totem Sombrio no cânion?",a="O clã Totem Sombrio ocupa o Pináculo da Nuvem Negra, um conjunto fortificado de torres rochosas que se opõe diretamente à Aldeia Vento Livre. Ao contrário das demais tribos taurens que juraram lealdade à Horda, o Totem Sombrio ataca ativamente outros taurens e conspira para tomar o controle dos platôs.",al={"totem sombrio em mil agulhas","taurens do pináculo da nuvem negra","taurens malignos de agulhas"}},{q="O que é a Chapada Cintilante?",a="A Chapada Cintilante é o leito de um vasto lago seco a leste dos platôs do cânion. A crosta de sal formou-se quando as antigas águas continentais evaporaram após a Cisão. O calor escaldante, o sal de brancura ofuscante e os predadores implacáveis transformam o local em um deserto inóspito, utilizado principalmente para testes de veículos em alta velocidade.",al={"deserto de sal","deserto branco de mil agulhas","deserto oriental"}}},fx={d1fb42e2={q="O que são as Mil Agulhas?",a="Mil Agulhas é um cânion vasto e árido que divide o centro e o sul de Kalimdor. O chão do cânion é repleto de imponentes pináculos de arenito que se estendem em direção ao céu como uma floresta petrificada, ligados acima por delicadas pontes de corda e madeira. A leste, o cânion dá lugar à Chapada Cintilante, uma planície de sal branca e ofuscante.",al={"o que é este lugar","sobre mil agulhas","me conte sobre mil agulhas"}},["98fcff4e"]={q="Por que tudo são cânions e pilares?",a="Eras atrás, antes da Grande Fragmentação, esta região era um cânion fluvial verdejante esculpido por águas correntes que fluíam para o leste de Feralas até um mar interior. Quando o mundo se despedaçou, o cataclismo empurrou o leito do rio para cima e alterou o curso do rio. Privada de água, a terra secou, deixando para trás imponentes pilares de arenito e um leito de sal ressecado.",al={"por que existem pináculos","como as agulhas se formaram","por que pilares de arenito"}},["05d5c74f"]={q="As Mil Agulhas são perigosas?",a="É bastante perigoso. Centauros Galak bárbaros patrulham o chão do cânion em bandos de invasores, enquanto abutres predatórios, escorpídeos e harpias ladinas assombram os penhascos. Até mesmo as pontes de corda entre os pináculos altos carregam perigo, já que aves de rapina frequentemente descem sobre viajantes incautos ou danificam as extensões.",al={"quão perigosas são as mil agulhas","perigos aqui","é seguro"}},["1b8e8bea"]={q="Por que a Horda me enviou para as Mil Agulhas?",a="A Horda mantém uma presença vital aqui para ajudar as tribos tauren locais que estão sob ataque implacável. A Aldeia Vento Livre ergue-se como um baluarte crítico que conecta os Sertões aos desertos do sul, e a Horda precisa de bravos campeões para repelir os centauros saqueadores e suprimir ameaças internas.",al={"missão da horda em mil agulhas","por que estou aqui horda","o que a horda quer aqui"}},a7c3b539={q="Esta é uma terra tauren?",a="Sim. Os cânions áridos e as mesas altas das Mil Agulhas têm sido tradicionalmente o território ancestral de várias tribos tauren por inúmeras gerações, embora clãs cruéis de centauros os tenham levado à beira da sobrevivência antes da chegada da Horda.",al={"os tauren possuem mil agulhas","território tauren","isto é terra shu'halo"}},fef8bf7c={q="O que é a Aldeia Vento Livre?",a="A Aldeia Vento Livre é o principal posto avançado da Horda nas Mil Agulhas. Construída no topo de uma mesa enorme bem acima do chão do vale, ela possui elevadores de madeira, uma torre de voo e uma rede de pontes suspensas que alcançam os pináculos adjacentes.",al={"aldeia vento livre","o que é a aldeia vento livre"}},["6ac472b0"]={q="Quem são os centauros Galak e por que eles estão nos atacando?",a="A tribo Galak são os centauros locais que reivindicam o chão do cânion. Como todos os centauros, eles são ferozmente territoriais, nômades e violentos. Eles caçam qualquer viajante que passe pelas gargantas e buscam erradicar completamente os assentamentos tauren.",al={"centauros galak","por que centauros atacam","tribo galak"}},["9f0b1de8"]={q="Por que eles odeiam os tauren?",a="A inimizade entre tauren e centauros é antiga e implacável. Por gerações através das planícies de Kalimdor, centauros itinerantes caçavam tauren por esporte e lançavam guerras brutais e não provocadas que mantinham as tribos pacíficas constantemente em fuga.",al={"por que centauros odeiam tauren","rixa entre centauros e tauren","rancor dos centauros"}},["0eee4587"]={q="Por que goblins e gnomos estão correndo com carros foguete no deserto?",a="O sal plano e aberto da Chapada Cintilante fornece o campo de provas perfeito para testar motores de alta velocidade. Gnomos e goblins estabeleceram o Circuito da Ilusão para resolver permanentemente a longa disputa sobre qual raça possui a engenharia superior.",al={"por que carros de corrida","corrida de goblin e gnomo","rivalidade de carros foguete"}},e421f132={q="Qual é a história do Pináculo da Nuvem Negra e daquelas notas secretas?",a="O Pináculo da Nuvem Negra é a fortaleza fortemente guardada da tribo Totem Sinistro nas mesas a leste de O Grande Elevador. Correspondências secretas descobertas lá revelam contato secreto entre líderes dos Totem Sinistro, como Arnak Totem Sinistro, e uma força sombria desconhecida, sugerindo ambições traiçoeiras muito além de simples disputas tribais.",al={"notas do pináculo da nuvem negra","notas dos totem sinistro","mistério do pináculo da nuvem negra"}},["7b560411"]={q="O que os Totem Sinistro estão planejando?",a="Os Totem Sinistro rejeitam fundamentalmente a liderança de Caerne Casco Sangrento e as mudanças culturais trazidas pela adesão à Horda. Eles buscam depor Caerne, minar a autoridade da Horda e até mesmo manter contato com poderes sinistros e invocar entidades de vingança para afirmar seu domínio.",al={"plano dos totem sinistro","o que os totem sinistro querem","conspiração dos totem sinistro"}},["853c4dd1"]={q="O que é Alcândora e por que queremos ovos de serpe?",a="Alcândora é o local de nidificação ancestral de serpes selvagens nas Mil Agulhas. Tauren da Aldeia Vento Livre escalam esses puleiros altos para coletar ovos férteis de serpe para que possam ser cuidadosamente criados e treinados como montarias voadoras leais para a Horda.",al={"serpes de alcândora","por que coletar ovos de serpe","ovos de alcândora"}},dc3189d8={q="Como vim parar nas Mil Agulhas?",a="A maioria dos viajantes chega do norte cavalgando para o sul através dos Sertões, passando pelo Acampamento Taurajo, eventualmente alcançando a borda do penhasco íngreme onde o enorme O Grande Elevador, projetado pelos tauren, leva você diretamente para o chão do cânion. Alternativamente, aventureiros que caminham para o leste através das densas florestas de Feralas entram na garganta ocidental a pé, enquanto exploradores ousados que enfrentam os perigos do Pântano Vadeoso ou navegam até Theramore passam pelas lacunas disputadas. Uma longa marcha por terra ao norte dos desertos de Tanaris também o leva diretamente para a extensa planície de sal da Chapada Cintilante.",al={"como cheguei aqui","como chego às mil agulhas","chegando às mil agulhas"}},["16801326"]={q="O que devo fazer nas Mil Agulhas?",a="Sua presença aqui depende de suas lealdades e ambições. Campeões da Horda têm a tarefa de ajudar a Aldeia Vento Livre: repelir os bandos de centauros Galak que vagam pelo chão do cânion, monitorar os ninhos de harpias, coletar ovos de serpe de Alcândora e combater a traiçoeira tribo Totem Sinistro entrincheirada no topo do Pináculo da Nuvem Negra. Para andarilhos não alinhados e viajantes da Aliança, a extensão dramática serve como uma encruzilhada terrestre perigosa entre o centro e o sul de Kalimdor, levando à Chapada Cintilante, onde temerários goblins e gnomos pagam boas moedas por peças, combustível e assistência com sua eterna rivalidade de carros foguete.",al={"por que estou aqui","qual meu propósito aqui","o que fazer nas mil agulhas"}}},fp="16,179,17.529.0,18.553.0,18.535.0,38.222.0,59.251.0,43.279.0,27.248.0,45.235.0,30.284.0"}
P.entries["zone:thunderbluff"] = {n="Penhasco do Trovão",s="O Penhasco do Trovão é a magnífica capital dos taurens, empoleirada no topo de platôs de rocha vermelha fustigados pelo vento que se erguem sobre as pradarias de Mulgore. Fundada pelo Grande Chefe Caerne Casco Sangrento após unir as tribos nômades com a ajuda da Nova Horda, ela serve como o coração cultural, espiritual e mercantil de seu povo. Conectada por pontes de corda oscilantes e elevadores de madeira, a cidade oferece proteção contra saqueadores centauros e um santuário pacífico para viajantes por toda Kalimdor.",h="O Penhasco do Trovão é a magnífica capital dos taurens, empoleirada no topo de platôs de rocha vermelha...",kw={"caerne casco sangrento","platô dos anciãos","elevadores","hamuul runa totem","platô dos caçadores","magatha temível totem","mulgore","poços das visões","platô dos espíritos","penhasco do trovão"},ang={["class:Druid"]="O Platô dos Anciãos serve como o santuário supremo de magia da natureza da Horda, liderado pelo Arquidruida Hamuul Runa Totem, o primeiro druida tauren instruído em milhares de anos.",["class:Shaman"]="O Platô dos Espíritos e os subterrâneos Poços das Visões oferecem um elo sereno onde os espíritos elementais e os espíritos dos ancestrais taurens são reverenciados e ouvidos.",["faction:Horde"]="Muito mais tranquilo e espiritual do que as fortificações austeras de Orgrimmar, o Penhasco do Trovão atua como o alicerce pastoral da influência da Nova Horda no sul de Kalimdor.",["race:Tauren"]="O Penhasco do Trovão representa a duramente conquistada união e o renascimento do seu povo após gerações de vida nômade e perseguição pelos centauros, sob o comando do Grande Chefe Caerne Casco Sangrento."},sec={{t="Um Refúgio Permanente",b="Por incontáveis gerações, os taurens viveram como andarilhos nômades por toda Kalimdor, travando uma luta brutal pela sobrevivência contra tribos vorazes de centauros. Essa era desesperadora terminou durante a Terceira Guerra, quando Caerne Casco Sangrento uniu forças com o Chefe Guerreiro Thrall. Juntos, os orcs e taurens repeliram as investidas dos centauros e garantiram as pastagens verdejantes de Mulgore. Para proteger o futuro deles, Caerne conduziu as tribos aliadas à segurança desses bastiões de pedra naturais, fundando o Penhasco do Trovão como o primeiro lar unificado e permanente dos taurens em séculos."},{t="Uma Cidade nas Nuvens",b="Estendendo-se por vários platôs elevados conectados por pontes de corda suspensas, o Penhasco do Trovão mescla com perfeição a arquitetura natural com a praticidade tauren. Os platôs centrais abrigam os movimentados mercados, o banco, a estalagem e o imponente poleiro de Mantícoras, enquanto três platôs especializados se ramificam sobre o abismo. O Platô dos Caçadores serve aos batedores e rastreadores da cidade; o Platô dos Anciãos abriga os guardiões da história e o Círculo Cenariano sob a liderança do Arquidruida Hamuul Runa Totem; e o Platô dos Espíritos é dedicado à comunhão espiritual, acolhendo xamãs, sacerdotes e as misteriosas cavernas subterrâneas conhecidas como os Poços das Visões."},{t="União Inquieta",b="Embora Caerne Casco Sangrento imponha imenso respeito de quase todas as tribos, governar um povo orgulhoso e recém-estabelecido traz seus atritos. Notavelmente, a tribo Temível Totem — liderada pela perspicaz e mordaz Matriarca Magatha Temível Totem — mantém uma presença sombria no Platô dos Anciãos. Magatha questiona abertamente os métodos conciliatórios de Caerne e sua lealdade às raças estrangeiras da Horda. Embora a paz se mantenha sob o olhar vigilante do chefe, fendas ideológicas murmuram entre as fogueiras do conselho sobre as planícies."}},faq={{q="Quem governa o Penhasco do Trovão?",a="O Grande Chefe Caerne Casco Sangrento governa o Penhasco do Trovão e lidera as tribos taurens unidas. Reverenciado por sua sabedoria, paciência e força colossal, Caerne fundou a cidade após se aliar à Horda de Thrall e expulsar os centauros de Mulgore.",al={"líder do penhasco do trovão","quem governa","chefe do penhasco do trovão","caerne"}},{q="Como se sobe até o Penhasco do Trovão?",a="Visitantes que chegam a pé ou em kodos precisam usar elevadores maciços com plataformas de madeira localizados nos lados sudoeste e nordeste do platô central. Como alternativa, a cidade conta com um poleiro de Mantícoras com rotas de voo por toda Kalimdor.",al={"elevador do penhasco do trovão","como entrar","entrada do penhasco do trovão","como subir"}},{q="Por que os taurens construíram no topo de platôs em vez de no chão?",a="Séculos de existência nômade foram marcados por ataques implacáveis de guerrilha desferidos por clãs agressivos de centauros. Os penhascos íngremes dos platôs de Mulgore oferecem defesa natural, protegendo as habitações, ferrarias e sábios anciãos dos taurens contra emboscadas terrestres, permitindo que eles se estabeleçam de forma permanente em paz.",al={"por que platôs","por que ficam em penhascos","penhascos do penhasco do trovão","posição elevada dos taurens"}},{q="Quais são os diferentes platôs da cidade?",a="A cidade abrange um platô central (dividido em níveis inferior, intermediário e superior) cercado por três platôs periféricos. O Platô dos Caçadores é dedicado aos guerreiros, caçadores e alojamentos de rastreamento. O Platô dos Anciãos é o lar de druidas, sábios e da facção Temível Totem. O Platô dos Espíritos abriga santuários para a Mãe Terra, instrutores de xamãs, sacerdotes e magos, e as cavernas dos Poços das Visões.",al={"áreas do penhasco do trovão","o que são os platôs","distritos do penhasco do trovão"}},{q="O que são os Poços das Visões?",a="Os Poços das Visões são cavernas subterrâneas sagradas ocultas sob o Platô dos Espíritos. Videntes, andarilhos espirituais e praticantes do arcano taurens se reúnem nessas águas serenas e envoltas em névoa para comungar com os elementos e interpretar presságios sobre o futuro de seu povo.",al={"poços das visões","caverna do platô dos espíritos","caverna do penhasco do trovão"}},{q="Quem é Magatha Temível Totem?",a="Magatha Temível Totem é a matriarca do formidável clã Temível Totem. Embora resida no Platô dos Anciãos e participe externamente do conselho de Caerne, ela é ferozmente tradicionalista, desconfia de forasteiros e desafia veladamente a postura branda da tribo Casco Sangrento em relação à Horda.",al={"magatha","matriarca","quem é o líder dos temível totem"}}},fx={["6fa5b073"]={q="O que é o Penhasco do Trovão?",a="O Penhasco do Trovão é a capital dos tauren, situada no topo das mesas varridas pelo vento ao norte de Mulgore. Estabelecida pelo Grão-chefe Caerne Casco Sangrento após repelir os centauros com a Horda de Thrall, ela oferece um santuário seguro e permanente para um povo que viveu como nômades errantes por gerações.",al={"o que é esta cidade","me conte sobre o penhasco do trovão","cidade do penhasco do trovão"}},fc90632b={q="Caerne Casco Sangrento é um rei?",a="Não. Caerne Casco Sangrento detém o título de Grão-chefe das tribos tauren unidas. A sociedade tauren não coroa monarcas; Caerne governa através do profundo respeito, sabedoria e força que demonstrou ao longo de décadas, em vez de direito divino real hereditário.",al={"caerne casco sangrento rei","caerne é um rei","rei tauren"}},["047fa056"]={q="Caerne Casco Sangrento responde a Thrall?",a="Thrall é o Chefe Guerreiro da Horda, mas seu vínculo com Caerne baseia-se em honra mútua e aliança, não em subjugação estrita. Caerne comprometeu seu povo com a Horda por gratidão e visão compartilhada, posicionando-se como um dos conselheiros e iguais mais confiáveis de Thrall.",al={"caerne responde a thrall","thrall é chefe de caerne","caerne e thrall"}},["85c1a10f"]={q="Por que os tauren se juntaram à Horda?",a="Saqueadores centauros haviam empurrado os tauren nômades à beira da extinção pelos Sertões. Quando o Chefe Guerreiro Thrall e os orcs desembarcaram em Kalimdor, eles ajudaram o povo de Caerne a romper o cerco centauro e a proteger Mulgore, forjando um vínculo inquebrável entre suas culturas.",al={"por que se juntar à horda","tauren horda aliança","como os tauren se juntaram"}},["3180b5ca"]={q="Qual é a situação da tribo Grimtotem?",a="Os Grimtotem são um clã feroz e agressivo liderado pela anciã Magatha. Ao contrário dos pacíficos Casco Sangrento, eles nutrem profunda suspeita em relação a forasteiros e questionam abertamente a liderança pacífica de Caerne, acreditando que os tauren deveriam conquistar Kalimdor e expulsar as outras raças.",al={"tribo grimtotem","quem são os grimtotem","tauren grimtotem"}},ca8246e8={q="Os Grimtotem são inimigos de Caerne?",a="Abertamente, eles permanecem parte da nação unida dos tauren, e Magatha até reside no Platô dos Anciãos. Sob a superfície, no entanto, uma amarga rivalidade política ferve, pois Magatha trama constantemente e acredita que ela, sozinha, possui a visão correta para governar os tauren.",al={"grimtotem são maus","grimtotem contra caerne","magatha vs caerne"}},["54829977"]={q="O Penhasco do Trovão é perigoso?",a="Dentro da cidade, os bravos guardas mantêm a ordem e a segurança contra as feras e javatus que rondam as planícies abaixo. O maior perigo imediato para os visitantes é a queda abrupta — um passo em falso descuidado das bordas do platô ou das pontes de madeira será fatal.",al={"o penhasco do trovão é seguro","ameaças no penhasco do trovão","perigo aqui"}},["7db56847"]={q="Como vim parar no Penhasco do Trovão?",a="Se você é um jovem tauren, sua jornada começou ao sul, nas pastagens protegidas da Chapada Nuvem Vermelha, e passou pela Aldeia Casco Sangrento antes de trazê-lo aqui. A estrada leva à base desses platôs imponentes, onde grandes elevadores de corda de madeira içam viajantes a centenas de pés de altura no céu. Alternativamente, visitantes que viajam de terras distantes por Kalimdor frequentemente chegam de serpe no Poleiro dos Cavaleiros do Vento central, no topo dos penhascos.",al={"como cheguei aqui","como cheguei ao penhasco do trovão","como chego ao penhasco do trovão"}},["347b5cac"]={q="O que devo fazer no Penhasco do Trovão?",a="O Penhasco do Trovão é o coração espiritual e cultural das tribos tauren unidas. Aqui, você pode buscar treinamento avançado com xamãs, druidas, caçadores e guerreiros anciãos reunidos por todos os platôs. O Alto Chefe Caerne Casco Sangrento e os anciãos tribais também contam com campeões capazes para proteger Mulgore de ameaças persistentes — incluindo saqueadores centauros, a invasora Empreendimentos S.A., harpias e javatus rebeldes — antes de enviá-lo para o leste, para as provações mais amplas da Horda.",al={"o que devo fazer no penhasco do trovão","por que estou aqui","qual é meu propósito aqui"}}},fp="13,326,17.466.0,20.453.0,12.391.1,24.277.0,35.194.0,61.212.0,41.395.0,29.239.0,25.233.0"}
P.entries["zone:tirisfal"] = {n="Clareiras de Tirisfal",s="Clareiras de Tirisfal é o território assombrado ao norte de Lordaeron, agora servindo como o coração de Lady Sylvanas e dos Renegados. Sob céus assolados pela praga e galhos apodrecidos jazem mansões caídas, criptas adormecidas e a vasta capital subterrânea da Cidade Baixa. Cercado pelo Flagelo sem mente e pelos zelosos cruzados Escarlates, é um reino perigoso onde mortos-vivos com livre-arbítrio lutam por sua sobrevivência.",h="Clareiras de Tirisfal é o território assombrado ao norte de Lordaeron, agora servindo como o coração de Lady...",kw={"agamand","balnir","montalvo","plangemortis","renegados","clareiras","lordaeron","cruzada escarlate","sylvanas","tirisfal","cidade baixa"},ang={["class:Priest"]="Terras sagradas históricas como o Repouso de Faol — o túmulo do Arcebispo Alonsus Faol, fundador da Mão de Prata — jazem aqui, distorcidas pela morte e disputadas entre fanáticos e sacerdotes das Sombras.",["faction:Alliance"]="Para as nações sobreviventes da Aliança, Tirisfal é um monumento trágico à queda de Lordaeron, repleto dos túmulos profanados de antigos irmãos e irmãs na fé.",["faction:Horde"]="Tirisfal é o bastião vital da Horda nos Reinos do Leste ao norte, ancorando laços diplomáticos com os Renegados enquanto afasta extremistas humanos e o Flagelo.",["race:Undead"]="Esta é a sua terra natal ancestral duas vezes: o reino que você construiu em vida e o santuário precário que você deve defender na morte sob o comando de Lady Sylvanas."},sec={{t="Uma Terra no Crepúsculo",b="Outrora o berço fértil da humanidade, Clareiras de Tirisfal definhou sob a maldição da praga do Lich King. O sol raramente penetra a escuridão sombria, lançando uma palidez doentia eterna sobre bosques moribundos, plantações de abóboras negligenciadas e colinas costeiras frias. Embora remanescentes de antigas fazendas como os Moinhos dos Agamand e a Fazenda dos Balnir permaneçam, seus antigos mestres foram em grande parte varridos para valas comuns ou ressurgiram como mortos inquietos. Apesar da devastação, uma resiliência sombria permeia o campo, ancorada por cidades como Montalvo e o santuário enclausurado de Plangemortis, onde Renegados recém-despertados aprendem a suportar sua segunda vida."},{t="Uma Guerra em Duas Frentes",b="Embora Lady Sylvanas reivindique domínio sobre a região a partir das subterrâneas Ruínas de Lordaeron, os Renegados permanecem em batalha em todos os lados. Escravos residuais do Flagelo ainda infestam grotas, campos e criptas dilapidadas, inteiramente submissos ao trono congelado de Northrend. Para o leste, a fanática Cruzada Escarlate fez do norte de Tirisfal seu bastião principal, operando a partir do Monastério Escarlate. Zelosamente devotados ao extermínio de toda criatura morta-viva, viva ou morta, seus postos avançados e patrulhas travam uma guerra de guerrilha constante contra batedores Renegados e viajantes civis."},{t="Ecos do Passado Antigo",b="Muito antes de os reinos humanos coroarem seus primeiros monarcas, as Clareiras carregavam um legado antigo. Exilados elfos superiores tentaram brevemente estabelecer-se nestes bosques antes que energias sombrias nas profundezas da terra começassem a enlouquecê-los, provocando sua migração para o norte. Em séculos posteriores, a cabala mortal secreta conhecida como Conselho de Tirisfal escolheu estes bosques sombrios para capacitar Guardiões solitários, protegendo Azeroth de intrusões demoníacas."}},faq={{q="Por que o céu é verde e a terra está apodrecendo?",a="Durante a Terceira Guerra, o Príncipe Arthas e o Flagelo desencadearam a Praga da Morte-viva por todo o Reino de Lordaeron. A praga mágica envenenou não apenas a população, mas o solo, as árvores e a própria água, deixando as Clareiras em um estado eterno de decadência sinistra e doentia.",al={"por que tirisfal está assolada pela praga","o que aconteceu com tirisfal","por que tirisfal está morrendo"}},{q="Qual é a diferença entre os Renegados e o Flagelo aqui?",a="Os Renegados são mortos-vivos que se libertaram da dominação telepática do Lich King após a Batalha do Monte Hyjal, escolhendo seguir a Grande Dama Sylvana Correventos com seu próprio livre-arbítrio. O Flagelo que vagueia pelas fazendas e ruínas permanece como escravos sem mente presos aos comandos do Lich King.",al={"renegados vs flagelo","por que zumbis atacam mortos-vivos","todos os mortos-vivos são malignos"}},{q="Quem são os soldados de armadura vermelha que atacam viajantes?",a="Eles pertencem à Cruzada Escarlate, uma ordem dissidente intransigente de antigos paladinos da Mão de Prata e sobreviventes. Convencidos de que todos os mortos-vivos são abominações irredimíveis que devem ser purificadas pela espada e pelo fogo, eles executam tanto escravos sem mente quanto Renegados com livre-arbítrio com ódio fanático.",al={"cruzada escarlate","humanos vermelhos","humanos do monastério"}},{q="De onde vem o nome Tirisfal?",a="O nome é mais antigo que qualquer reino humano, e sua verdadeira origem foi perdida na história. É mais conhecido através do Conselho de Tirisfal, a ordem secreta de magos que capacitou os Guardiões para proteger Azeroth de demônios.",al={"significado de tirisfal","origem de tirisfal"}},{q="Onde os Renegados recém-despertados começam sua jornada?",a="Os Renegados recém-despertados emergem das criptas do Sepulcro Sombrio dentro de Plangemortis, uma cidade enclausurada situada no sudoeste de Tirisfal. Lá, administradores e executores avaliam se os mortos ressuscitados possuem a sanidade e a lealdade necessárias para servir à Dama Sombria.",al={"zona inicial dos mortos-vivos","onde fica plangemortis","área inicial dos renegados"}},{q="Como os viajantes deixam Tirisfal para outros continentes?",a="Uma grande torre de zepelim operada por goblins fica na encosta ao sul de Montalvo, logo fora das Ruínas de Lordaeron. Essas aeronaves fornecem trânsito direto e regular pelos mares até Orgrimmar em Kalimdor e o Acampamento Grom'gol na Selva do Espinhaço.",al={"zepelins de tirisfal","como ir para orgrimmar","como ir para a selva do espinhaço"}}},fx={["6c272224"]={q="O que são as Clareiras de Tirisfal?",a="As Clareiras de Tirisfal são o coração dos Renegados na costa norte de Lordaeron. Antes o núcleo pacífico e fértil de um orgulhoso reino humano, foi devastado durante a Terceira Guerra pela Praga da Morte do Flagelo. Hoje, bosques assolados e uma penumbra verde perpétua cobrem as colinas, emolduradas pelas ruínas da capital de Lordaeron e cercadas por fanáticos hostis, feras selvagens e mortos-vivos persistentes.",al={"o que é tirisfal","fale-me sobre as clareiras de tirisfal","lore da zona tirisfal"}},["342b65f9"]={q="Estas terras sempre foram dos mortos-vivos?",a="Não. Por milhares de anos, Tirisfal foi o berço da civilização humana e o coração próspero do Reino de Lordaeron. Fazendas pacíficas, moinhos prósperos e pequenas aldeias floresceram sob o Rei Terenas Menethil. Essa era terminou violentamente durante a Terceira Guerra, quando o Príncipe Arthas e a Seita dos Malditos passaram por lá com a praga, transformando os habitantes em escravos mortos-vivos antes que Sylvana os libertasse.",al={"tirisfal sempre foi dos mortos-vivos","quem morava aqui antes","tirisfal antes da praga"}},["4790468d"]={q="Quem vive ou governa as Clareiras de Tirisfal?",a="Os Renegados reivindicam as Clareiras de Tirisfal sob o governo da Rainha Sylvana Correventos da Cidade Baixa. No entanto, seu domínio é constantemente contestado. A fanática Cruzada Escarlate comanda fortificações e seu grande Monastério no nordeste, enquanto o Flagelo irracional ronda fazendas abandonadas. Na fronteira leste, no Baluarte, os Renegados coordenam com a Aurora Argêntea para manter os horrores das Terras Pestilentas contidos.",al={"quem governa tirisfal","quem controla as clareiras de tirisfal","facções de tirisfal"}},["97ffdb73"]={q="As Clareiras de Tirisfal são perigosas?",a="Extremamente perigosas. Além dos muros dos postos avançados dos Renegados, você enfrentará remanescentes irracionais do Flagelo, gnolls selvagens, aracnídeos gigantes e vida selvagem viciosa contaminada pela praga. Pior ainda são os fanáticos da Cruzada Escarlate, que executam qualquer morto-vivo à vista. No extremo leste ficam as Terras Pestilentas Ocidentais, onde monstros muito mais mortais do que qualquer coisa em Tirisfal despedaçarão os incautos.",al={"quão perigosa é tirisfal","ameaças de tirisfal","é seguro aqui"}},["30e6283a"]={q="Quem está no comando em Montalvo?",a="O Magistrado Sevren supervisiona a administração civil de Montalvo, gerenciando a reconstrução e a sobrevivência diária da cidade. A autoridade militar e as operações táticas, particularmente a campanha contra Cruzada Escarlate próxima, são comandadas pelo Executor Zigano.",al={"líder de montalvo","quem lidera montalvo","no comando de montalvo"}},["3fc3649e"]={q="A quem o Magistrado Sevren responde?",a="Sevren serve à Dama Sombria, Rainha Sylvana Correventos. Como magistrado de Montalvo, ele representa a autoridade civil da coroa dos Renegados na região, operando em concerto direto com os executores reais e a Real Sociedade de Boticários sediada na Cidade Baixa.",al={"chefe de sevren","a quem sevren responde","cadeia de comando de montalvo"}},["381a9b46"]={q="Onde está a Rainha Banshee?",a="A Grande Dama Sylvana Correventos reside no Royal Quarter da Cidade Baixa, profundamente abaixo das ruínas da Cidade Capital, logo ao sul de Montalvo. De sua sala do trono, ela direciona os Renegados em sua guerra contra o Flagelo e a Cruzada Escarlate.",al={"onde está sylvana","encontrar sylvana","localização da rainha banshee"}},e7993821={q="O que é Montalvo?",a="Montalvo é a principal cidade dos Renegados nas Clareiras de Tirisfal centrais, situada ao longo das encruzilhadas ao norte da Cidade Capital. Antigamente um assentamento vivo sob a propriedade Barov, foi reconstruída após a Terceira Guerra para fornecer aos mortos-vivos recém-despertos um lugar de descanso, comércio e organização antes de se aventurarem mais pelo mundo.",al={"sobre montalvo","que tipo de cidade é montalvo","lore de montalvo"}},["529e09c8"]={q="Pessoas vivas moravam aqui antes?",a="Sim. Montalvo já foi uma comunidade humana tranquila dentro do Reino de Lordaeron. Tornou-se o marco zero para os primeiros experimentos com a praga orquestrados por Kel'Thuzad, resultando em baixas em massa e enormes sepulturas comunitárias antes mesmo de o Príncipe Arthas chegar para investigar.",al={"humanos moravam em montalvo","história de montalvo","quem morava em montalvo"}},["7b7ff5e2"]={q="O que é a Taberna Finda Forca?",a="A Taberna Finda Forca é o salão de reuniões e estalagem central de Montalvo. Oferece abrigo, bebidas imundas e descanso das clareiras sombrias lá fora. Em seus cantos mais escuros, os Renegados mantêm inimigos capturados — como fanáticos da Cruzada Escarlate — para testes sinistros de concoções da Sociedade de Boticários.",al={"taberna finda forca","estalagem de montalvo","o que é a taberna finda forca"}},["0d8014ee"]={q="Qual é a situação dos Moinhos dos Agamand?",a="Os Moinhos dos Agamand já foram a propriedade agrícola mais rica e produtiva das Clareiras de Tirisfal, famosa pela farinha e grãos. Quando a praga atingiu, todo o complexo foi invadido e o massacre aconteceu. Hoje, permanece como uma ruína apodrecida, pontilhada de moinhos de vento e sufocada por mortos-vivos persistentes do Flagelo.",al={"lore dos moinhos dos agamand","o que aconteceu aos moinhos dos agamand","moinhos dos agamand"}},["001d4abe"]={q="Quem eram os Agamand?",a="Os Agamand eram uma dinastia humana nobre e rica que desenvolveu os moinhos extensos e possuía propriedades por toda Tirisfal, incluindo Montalvo. Durante a Terceira Guerra, sua fortuna não pôde salvá-los; a família caiu para o Flagelo e seus patriarcas reanimados continuam a assombrar a propriedade.",al={"família agamand","quem morava nos moinhos dos agamand","os agamand"}},eeb96a2c={q="Por que eles são hostis conosco se eles também são mortos-vivos?",a="Os mortos-vivos que assombram os Moinhos dos Agamand nunca recuperaram seu livre-arbítrio. Ao contrário dos Renegados, que se livraram do controle mental do Lich Rei, essas criaturas permanecem escravizadas como servos irracionais do Flagelo, compelidos a destruir qualquer vivo ou morto-vivo rebelde que invada seu domínio.",al={"por que os agamand nos atacam","por que os mortos-vivos agamand são hostis","por que lutar contra outros mortos-vivos"}},a357af07={q="Onde tudo isso leva depois de Tirisfal?",a="A maioria dos Renegados viaja para o sul através da passagem da montanha até a Floresta de Pinhaprata para ajudar a garantir a fronteira sul e batalhar contra agentes de Dalaran e gnolls Couro-podre. Alternativamente, zepelins ao sul de Montalvo fornecem passagem para Orgrimmar ou para o Acampamento Grom'gol através do mar.",al={"para onde ir depois de tirisfal","próxima zona depois de tirisfal","depois das clareiras de tirisfal"}},["50336b90"]={q="O que é a Cidade Baixa?",a="A Cidade Baixa é a vasta capital subterrânea dos Renegados, construída dentro dos antigos esgotos, criptas e catacumbas sob as Ruínas de Lordaeron despedaçadas. Ela serve como a fortaleza da Rainha Sylvanas e o Command Center para as operações dos Renegados por toda Azeroth.",al={"o que é a cidade baixa","lore da cidade baixa","sobre a cidade baixa"}},ddddba9f={q="A fronteira de Floresta de Pinhaprata é a seguir?",a="Sim. Seguir a estrada para o sul saindo das Clareiras de Tirisfal leva diretamente à Floresta de Pinhaprata. É a continuação natural do seu serviço aos Renegados, onde você confronta a crescente ameaça ao longo das fronteiras do sul de Lordaeron.",al={"floresta de pinhaprata a seguir","vou para floresta de pinhaprata em seguida","fronteira da floresta de pinhaprata"}},["789ead4d"]={q="Como fui parar nas Clareiras de Tirisfal?",a="Se você é um Renegado recém-erguido, você morreu durante a queda de Lordaeron para o Flagelo e foi enterrado aqui. Com o controle do Lich King quebrado, seu livre arbítrio retornou e você saiu da cova no vale isolado de Plangemortis. Se você pertence a outras nações da Horda, você provavelmente chegou através das torres de zepelim situadas entre Montalvo e a Cidade Baixa, que conectam este reino assolado diretamente a Orgrimmar e ao Acampamento Grom'gol.",al={"como cheguei aqui","como cheguei às clareiras de tirisfal","como cheguei a este lugar"}},["89135166"]={q="O que eu devo fazer nas Clareiras de Tirisfal?",a="Seu objetivo é ajudar os Renegados a garantir seu domínio tênue sobre as terras centrais assoladas de Lordaeron. Saindo das criptas de Plangemortis em direção à cidade de Montalvo, você deve expurgar o Flagelo irracional que assombra as fazendas abandonadas, eliminar os fanáticos zelotas da Cruzada Escarlate que avançam do norte e abater as feras contaminadas que vagam pelos bosques apodrecidos. Fazer isso prova seu valor para Lady Sylvanas e prepara você para servir ao seu reino em crescimento sob as ruínas da Capital.",al={"o que devo fazer aqui","por que estou em tirisfal","qual é meu objetivo aqui"}}},fp="15,338,18.442.0,19.456.0,26.372.0,42.269.0,65.287.0,53.289.0,39.222.0,53.244.0,53.247.0"}
P.entries["zone:undercity"] = {n="Cidade Baixa",s="Nas profundezas das ruínas devastadas da Cidade Capital de Lordaeron fica Cidade Baixa, a sombria fortaleza dos Renegados. Escavada originalmente a partir de antigas criptas reais e masmorras pelo Flagelo, foi tomada por Grande Dama Sylvana Correventos e transformada em um impenetrável santuário subterrâneo. Hoje, serve como a sede do poder dos Renegados e o bastião vital da Horda no norte dos Reinos do Leste.",h="Nas profundezas das ruínas devastadas da Cidade Capital de Lordaeron fica Cidade Baixa, a sombria fortaleza...",kw={"boticarium","arthas","renegados","lordaeron","flagelo","sylvanas","terenas","tirisfal","cidade baixa","varimatras"},ang={["faction:Horde"]="Como a principal fortaleza da Horda nos Reinos do Leste, Cidade Baixa garante conexões diretas por zepelim com Durotar e o Acampamento Grom'gol.",["race:Human"]="Sob o solo do seu reino ancestral devastado jaz uma sombria perversão das criptas reais de Lordaeron, ocupada pelos cadáveres ambulantes dos seus antigos irmãos.",["race:Orc"]="Nas profundezas destas mesmíssimas masmorras, o lendário Chefe de Guerra Orgrim Martelo da Perdição já esteve aprisionado pela Aliança de Lordaeron antes de realizar sua fuga histórica.",["race:Undead"]="A Cidade Baixa é o seu santuário soberano e lar, esculpido por suas próprias mãos depois de quebrar o domínio de ferro do Lich Rei sobre a sua mente."},sec={{t="De Criptas Reais a Reduto do Flagelo",b="Muito antes de a peste assolar Lordaeron, as catacumbas, masmorras e esgotos sob o palácio eram conhecidos coletivamente como Cidade Baixa. O local abrigava os túmulos da nobreza, as prisões mais profundas do reino — onde o antigo Chefe de Guerra Orgrim Martelo da Perdição já esteve preso antes de fugir — e os habitantes mais indigentes da região. Quando Arthas Menethil assassinou o Rei Terenas e devastou a capital em 20 ADP, o príncipe ordenou que seus servos mortos-vivos escavassem e expandissem as passagens subterrâneas em uma sede fortificada para o domínio do Flagelo."},{t="Ascensão dos Renegados",b="O Flagelo nunca viu sua capital sombria concluída. Quando os poderes do Lich Rei diminuíram após a batalha do Monte Hyjal, Grande Dama Sylvana Correventos libertou-se do controle mental, levando consigo milhares de mortos-vivos. Ela atraiu Arthas para uma emboscada e o expulsou de volta para Northrend. Após uma violenta guerra civil tripartite contra remanescentes do Flagelo, Senhores do Medo e a resistência humana, Sylvanas reivindicou as catacumbas inacabadas. Dando ao seu povo o nome de Renegados, ela supervisionou anos de trabalho árduo para concluir a vasta cidade subterrânea."},{t="Arquitetura dos Condenados",b="Cidade Baixa é organizada em anéis concêntricos divididos em bairros funcionais. Em seu coração fica o Distrito Comercial, conectado por grandes elevadores às ruínas do palácio acima. Ao seu redor estão o Distrito Bélico, o Distrito dos Ladinos, o Distrito da Magia e o tóxico Boticarium, onde a Real Sociedade de Boticários prepara pestes virulentas em canais cheios de lodo verde. Mais abaixo ainda fica o Distrito Real, onde a Rainha Banshee governa ao lado de seu comandante Senhor do Medo, Varimatras, protegida por legiões de imponentes abominações."}},faq={{q="O que era Cidade Baixa antes de os mortos-vivos a tomarem?",a="Sob o palácio de Lordaeron ficavam as antigas criptas da realeza humana, juntamente com o complexo carcerário e a vasta rede de esgotos da cidade. Ali ficavam prisioneiros de guerra, incluindo Orgrim Martelo da Perdição, bem como cidadãos desprovidos vivendo nas sombras subterrâneas. Após saquear a capital, o Príncipe Arthas começou a transformar essas catacumbas em uma fortaleza do Flagelo antes de Sylvanas tomá-las.",al={"origens de cidade baixa","o que era cidade baixa originalmente","historia dos esgotos de lordaeron"}},{q="Por que a cidade é construída no subsolo em vez de na superfície?",a="A cidade de Lordaeron na superfície foi completamente arruinada durante a Terceira Guerra, tornando difícil defendê-la contra Cruzada Escarlate, as forças do Flagelo e os sobreviventes da Aliança. Os túneis subterrâneos ofereciam fortificação natural, pontos de estrangulamento e discrição, permitindo aos Renegados concluir a construção inicial do Flagelo e prosperar sem serem vistos.",al={"por que morar no subsolo","por que nao reconstruir lordaeron","por que cidade baixa sob as ruinas"}},{q="Quem governa Cidade Baixa?",a="A cidade é governada por Grande Dama Sylvana Correventos, a Rainha Banshee e Rainha dos Renegados. Ela lidera a partir do Distrito Real, guardada por sentinelas reais dos Renegados e por seu tenente Senhor do Medo subjugado, Varimatras.",al={"quem e o lider de cidade baixa","governante de cidade baixa","quem comanda cidade baixa"}},{q="O que é o memorial do Rei Terenas nas ruínas acima?",a="Acima dos elevadores principais da cidade encontra-se um memorial de pedra para o falecido Rei Terenas Menethil II. Não contém seu corpo, pois seus restos foram cremados e suas cinzas descartadas durante a ressurreição de Kel'Thuzad. Humanos sobreviventes da Aliança esculpiram bravamente o monumento em meio às ruínas para que a memória do último verdadeiro rei de Lordaeron perdurasse.",al={"tumulo do rei terenas","tumulo na sala do trono de lordaeron","quem construiu o tumulo acima de cidade baixa"}},{q="O que são os barulhos estranhos na sala do trono de Lordaeron?",a="Na sala do trono em ruínas acima dos elevadores de Cidade Baixa, ecos espectrais do passado ainda permanecem. Os visitantes que ficam no centro podem ouvir tênues sons fantasmagóricos: os sinos festivos e as pétalas de rosa do retorno de Arthas, as palavras de aviso do profeta Medivh e a conversa final entre o Rei Terenas e seu filho parricida.",al={"sons de fantasmas na sala do trono","sussurros na sala do trono","vozes na sala do trono de lordaeron"}},{q="Por que os Renegados permitem outros membros da Horda aqui?",a="Os Renegados formaram uma aliança de conveniência com a Horda do Chefe de Guerra Thrall para garantir sua sobrevivência, cercados como estão por fanáticos zelotes da Cruzada Escarlate e legiões do Flagelo. Embora as raças vivas da Horda achem os vapores tóxicos e os rios alquímicos sufocantes, emissários e viajantes têm acesso liberado para cultivar laços diplomáticos e militares.",al={"por que ha orcs em cidade baixa","horda em cidade baixa","por que cidade baixa faz parte da horda"}}},fx={a590d153={q="O que é a Cidade Baixa?",a="A Cidade Baixa é a capital subterrânea dos Renegados, construída diretamente sob as ruínas despedaçadas da Cidade Capital nas Clareiras de Tirisfal. Esculpida a partir de antigas criptas reais, esgotos e catacumbas, ela foi expandida pelo Príncipe Arthas como um reduto do Flagelo antes que a Grande Dama Sylvana Correventos e seus mortos-vivos renegados a tomassem durante a guerra civil. Hoje, ela permanece como um santuário fortificado para mortos-vivos com livre-arbítrio, entrecruzado por lodo tóxico e vigiado atentamente contra todos os intrusos vivos.",al={"o que é a cidade baixa","fale-me sobre a cidade baixa","lore da cidade baixa"}},c51b16b2={q="O que aconteceu com o antigo rei de Lordaeron?",a="O Rei Terenas Menethil II foi assassinado na sala do trono diretamente acima desta cidade por seu próprio filho, o Príncipe Arthas. Após retornar de Nortúndria corrompido pela lâmina rúnica Gélido Lamento, Arthas abateu seu pai e libertou o Flagelo sobre o reino. As cinzas de Terenas foram mais tarde roubadas pelo cavaleiro da morte para ressuscitar Kel'Thuzad, deixando para trás apenas a pedra memorial e o rastro seco de sangue que você ainda pode ver perto do trono arruinado.",al={"destino do rei terenas","o que aconteceu com o rei terenas","quem matou o rei terenas"}},c11144c7={q="Quem era Arthas?",a="Arthas Menethil era o Príncipe Herdeiro de Lordaeron e um celebrado Paladino da Mão de Prata. Desesperado para deter a Praga da Morte que varria sua terra natal, sua cruzada tornou-se implacável e fanática. Em Nortúndria, ele reivindicou a amaldiçoada lâmina rúnica Gélido Lamento, que devorou sua alma e o tornou o temível campeão do Lich Rei. Ele retornou para casa apenas para massacrar seu pai, arrasar Lordaeron e, eventualmente, viajar de volta para o norte para se fundir ao Trono de Gelo.",al={"quem é arthas","lore do príncipe arthas","arthas menethil"}},["7f6bbd49"]={q="Quem é Sylvana Correventos?",a="A Grande Dama Sylvana Correventos foi outrora a valente General-Patrulheira de Luaprata, defendendo Quel'Thalas contra o Flagelo durante a Terceira Guerra. Quando ela caiu, Arthas arrancou sua alma de seu cadáver e a transformou em uma banshee para torturá-la. Quando o domínio do Lich Rei enfraqueceu, ela se libertou, recuperou sua forma física e reuniu outros mortos-vivos independentes nos Renegados. Agora ela reina como sua Rainha Banshee a partir do Distrito Real.",al={"quem é a rainha banshee","lore de sylvana","quem é sylvana"}},["2a8de90f"]={q="Por que Sylvana é chamada de Dama Sombria?",a="Os Renegados homenageiam Sylvana como a Dama Sombria porque ela os libertou da escravidão sem mente do Lich Rei e lhes deu abrigo quando o restante de Azeroth buscava seu extermínio total. Reverenciado junto com seu título de Rainha Banshee, o apelido reflete tanto seu domínio sombrio sobre a morte quanto a devoção feroz e inabalável de seus súditos mortos-vivos.",al={"por que dama sombria","título dama sombria sylvana","significado de dama sombria"}},["84f18f47"]={q="Por que os Renegados fazem parte da Horda?",a="Cercados por Cruzados Escarlates hostis, o implacável Flagelo e remanescentes vingativos da Aliança, os Renegados não poderiam sobreviver sozinhos em Lordaeron. A Grande Dama Sylvana contatou o Chefe Guerreiro Thrall do outro lado do mar, forjando uma aliança pragmática de conveniência. A Horda obteve um ponto de apoio militar crucial nos Reinos do Leste, enquanto os Renegados garantiram reforços essenciais e legitimidade política em sua guerra pela sobrevivência.",al={"por que os renegados na horda","mortos-vivos juntam-se à horda","renegados horda aliança"}},["71200045"]={q="O que é o Flagelo e eles ainda estão por perto?",a="O Flagelo é o vasto e voraz exército de mortos-vivos sem mente criado pela Legião Ardente e governado pelo Lich Rei de Nortúndria. Embora os Renegados tenham arrebatado a Cidade Baixa e Tirisfal de suas garras, o Flagelo permanece um perigo imediato e letal. Suas legiões ainda sufocam as Terras Pestilentas próximas sob o comando de Kel'Thuzad e infestam fazendas abandonadas e criptas por todas as clareiras.",al={"o flagelo está por perto","o que é o flagelo","flagelo em lordaeron"}},["501548ab"]={q="Onde está o Lich Rei agora?",a="O Lich Rei reside no topo do Trono de Gelo nos distantes e gelados ermos de Nortúndria. Após a guerra civil nas Terras Pestilentas, o Príncipe Arthas fugiu de Lordaeron para proteger seu mestre enfraquecido, ascendendo à geleira e fundindo suas essências em uma única entidade aterrorizante. Daquele baluarte ártico, seu olhar gelado ainda observa Azeroth.",al={"onde está o lich rei","localização do lich rei","onde está arthas agora"}},["4cc7f971"]={q="Quem é a Cruzada Escarlate?",a="a Cruzada Escarlate é uma ordem fanática de fanáticos humanos nascida das ruínas da defesa de Lordaeron. Cegados por seu ódio justo aos mortos-vivos, eles não fazem distinção entre o Flagelo sem mente e os Renegados com livre-arbítrio, vendo qualquer um maculado pela morte-viva — e qualquer forasteiro vivo que os tolere — como abominações vis dignas apenas da pira. Seu principal baluarte em Tirisfal é o Monastério Escarlate.",al={"quem é a cruzada escarlate","cruzados escarlates","lore da cruzada escarlate"}},["271820ed"]={q="A Cidade Baixa é perigosa?",a="É extraordinariamente perigosa, especialmente para os vivos. Canais de resíduos alquímicos brutos e lodo venenoso percorrem as ruas da cidade, preenchendo os salões cavernosos com vapores tóxicos que tornam a respiração perigosa para visitantes de carne e osso. Sob os bairros pavimentados jazem esgotos infestados, e ainda mais fundo estão experimentos secretos onde alquimia sombria e assassinatos implacáveis são planejados diariamente.",al={"a cidade baixa é segura","perigo na cidade baixa","perigos da cidade baixa"}},["2539a3c3"]={q="Como fui parar na Cidade Baixa?",a="Como um Renegado, seu caminho naturalmente o levou até aqui após despertar da morte em Plangemortis e provar sua lealdade através das Clareiras de Tirisfal, seguindo as estradas após Montalvo para descer sob as ruínas despedaçadas da Cidade Capital. Se você vem de Kalimdor ou de terras distantes, provavelmente chegou a bordo de um zepelim da Horda atracando nas torres logo fora da capital, ou caminhou pelo campo assolado. A Cidade Baixa permanece como o principal reduto da Horda no norte de Lordaeron, oferecendo abrigo e propósito sob as antigas catacumbas do palácio.",al={"como cheguei aqui","como cheguei à cidade baixa","como chegar à cidade baixa"}},b63c4cf2={q="O que devo fazer na Cidade Baixa?",a="Você está aqui para ajudar os Renegados e reunir a força da Horda contra os perigos que cercam Lordaeron. Dentro dos bairros concêntricos da cidade, você pode consultar instrutores de classe, adquirir suprimentos e consultar os pesquisadores sombrios da Real Sociedade de Boticários. Além de cuidar de seu ofício, seu dever é aceitar missões para a Grande Dama Sylvana Correventos e seus tenentes. Os Renegados lutam uma guerra em múltiplas frentes: expurgando os remanescentes do Flagelo sem mente, repelindo a fanática Cruzada Escarlate e garantindo um terreno seguro para que os mortos-vivos com livre-arbítrio possam perdurar.",al={"o que estou fazendo aqui","o que devo fazer na cidade baixa","por que estou aqui"}}},fp="9,318,36.556.0,20.416.0,26.421.0,54.450.0,60.340.0,24.362.0,51.333.0,57.328.0,51.322.0"}
P.entries["zone:ungoro"] = {n="Cratera Un’Goro",s="A Cratera Un’Goro é uma selva primordial e rebaixada, situada entre as terras áridas de Tanaris e Silithus. Dominada por dinossauros errantes, elementais vivos e um vulcão central, esta caldeira exuberante está repleta de relíquias antigas dos Titans e cristais de poder cujas origens permanecem um profundo mistério.",h="A Cratera Un’Goro é uma selva primordial e rebaixada, situada entre as terras áridas de Tanaris e Silithus.",kw={"demossauro","pico penacho de fogo","terras dos deuses","lakkari","refúgio do marshal","cristais de poder","torwa mateiro","ungoro","cratera un'goro"},ang={["class:Druid"]="Druidas do Círculo Cenariano estudam o ecossistema isolado de Un'Goro e colhem seu solo rico para propagar grão-matinal, buscando compreender a força vital pura e indomável que sustenta a caldeira.",["faction:Alliance"]="Naturalistas da Aliança reúnem-se em torno de Williden Marshal e J.D. Collie no Refúgio do Marshal, correndo contra o tempo para decifrar os pilares dos Titans enquanto protegem os pesquisadores de Darnassus que coletam amostras de solo.",["faction:Horde"]="Aventureiros da Horda costumam chegar por Tanaris para testar suas proezas contra demossauros lendários e ajudar os herboristas do Penhasco do Trovão a cultivar grão-matinal a partir da terra primitiva de Un'Goro.",["profession:Herbalism"]="A rica umidade da bacia sustenta uma flora rara, servindo como um dos poucos lugares em Kalimdor onde Blindweed, Folha-de-sonho e Sonsona-dourada florescem juntas, ao lado de Ignídea nas encostas do vulcão.",["profession:Mining"]="As paredes íngremes da cratera e os rochedos do Pico Penacho de Fogo são densos em Mithril Deposits e Rich Thorium Veins, tornando a zona um destino de primeira linha para minérios de alto nível."},sec={{t="As Terras dos Deuses",b="Espremida entre extensões desérticas, a Cratera Un’Goro desafia a geografia do sul de Kalimdor. Antigos registros de elfos noturnos detalhando a Guerra das Areias Cambiantes observam que os insectoides Qiraji foram repelidos nas bordas da cratera, incapazes de penetrar no que sua língua chamava de 'Terras dos Deuses'. Estudiosos teorizam que a caldeira serviu como campo de testes ou morada antiga para os Titans durante a formação de Kalimdor. Pilares de pedra erguem-se ao longo das cristas, zumbindo com energia, enquanto formações de cristais azuis, vermelhos, verdes e amarelos brotam pela terra primitiva."},{t="Um Ecossistema Selvagem",b="Un'Goro não contém cidades, vilas ou sociedades humanoides nativas. Em vez disso, a vida prospera em um estado selvagem e primitivo. Demossauros predadores de topo espreitam pelas planícies de Terroral, bloodpetals predatórias atacam nos Pântanos, e gosmas rastejam pelos poços de piche de Lakkari. No coração da cratera ergue-se o Pico Penacho de Fogo, um pico vulcânico ativo repleto de elementais de fogo hostis liderados pela entidade Blazerunner. Para exploradores e esfoladores, a bacia oferece uma riqueza natural inigualável — incluindo os cobiçados couros de demossauros — desde que se sobreviva à cadeia alimentar."},{t="Refúgio do Marshal",b="A presença civilizada na cratera limita-se quase inteiramente ao Refúgio do Marshal, um acampamento elevado situado nos penhascos do norte. Liderada por Williden Marshal, uma expedição de cientistas, naturalistas e caçadores de fortuna tentou catalogar os tesouros da bacia, apenas para ser castigada pela fauna monstruosa e forçada a recuar para terrenos mais altos. Hoje, o refúgio serve como um ponto de partida combatido para viajantes intrépidos que estudam os misteriosos cristais de poder da cratera, mapeiam a atividade vulcânica e mantêm A Watchful Eye nos enxames de silithídeos invasores que rompem as cristas ao sul."}},faq={{q="Como você entra na Cratera Un’Goro?",a="Os viajantes podem entrar por meio de rampas naturais que descem pelas paredes da cratera: uma acessível a partir do canto sudoeste de Tanaris, perto do Vale Moitagulhas, e outra vinda do nordeste de Silithus. Embora aventureiros imprudentes às vezes saltem dos penhascos, a queda é fatal sem assistência mágica. O Refúgio do Marshal, ao norte, oferece conexões de voo para Geringontzan e o Forte Cenariano.",al={"como entrar em ungoro","entrada de ungoro","como chegar a cratera un'goro"}},{q="Para que servem os cristais de poder coloridos?",a="Espalhados pelo chão da selva estão Cristais de Poder vermelhos, azuis, verdes e amarelos. Com a orientação da pesquisadora gnoma J.D. Collie no Refúgio do Marshal, os exploradores podem decifrar instruções para usar esses cristais nos Pylons Norte, Leste e Oeste. A combinação de cores específicas nos pilares apropriados canaliza energias latentes dos Titans para criar berloques defensivos ou restauradores.",al={"cristais de ungoro","cristais vermelhos azuis verdes amarelos ungoro","pilares de poder"}},{q="Por que Un'Goro é exuberante apesar de estar cercada por desertos?",a="Estudiosos acreditam que a vivacidade não natural de Un'Goro é artificial, originada dos Titans que moldaram o mundo. Condutos titânicos, a atividade geotérmica vulcânica quente do Pico Penacho de Fogo e a antiga energia das linhas de meridiano alimentam um ecossistema isolado e hiperacelerado que resiste às condições áridas das vizinhas Tanaris e Silithus.",al={"por que ungoro é uma selva","conexão de ungoro com o deserto","como ungoro tem plantas"}},{q="Por que os qiraji chamavam este lugar de 'Terras dos Deuses'?",a="De acordo com tabuletas traduzidas da Guerra das Areias Cambiantes, os enxames de insetos interromperam seu avanço no limiar da cratera. O Geólogo Larksbane, que traduziu o relato, vincula o nome a teorias de que os Titans outrora habitaram a cratera e se pergunta se o próprio Aman'Thul vigiava as Terras dos Deuses.",al={"significado de Terras dos Deuses","qiraji em Un'Goro","por que os silitídeos não tomaram Un'Goro"}},{q="Para que serve o Solo de Un'Goro?",a="Pilhas de terra rica e potente repousam por toda a bacia da cratera. Quando coletado, esse solo pode ser combinado com sementes de Tharlendris em um Bornal de Sempre-viva para cultivar grão-matinal, uma erva mística intensamente procurada por pesquisadores no Penhasco do Trovão, em Darnassus e no Círculo Cenariano.",al={"amostra de solo de ungoro","para que serve o solo de ungoro","solo de grão-matinal"}},{q="Existe algum assentamento humanoide ou masmorra aqui?",a="A Cratera Un’Goro abriga uma masmorra, O Terraço do Moldador, para níveis aproximados de 58 a 60, mas nenhuma sociedade humanoide nativa. O único assentamento duradouro é o Refúgio do Marshal, um pequeno posto avançado de expedição na borda norte. Além de caçadores eremitas isolados ou exploradores perdidos, o restante da caldeira é totalmente selvagem.",al={"masmorras de ungoro","quem vive em ungoro","humanoides em ungoro"}}},fp="14,269,13.410.0,18.462.0,16.490.0,35.282.0,45.336.0,56.270.0,51.330.0,30.235.0,52.287.0"}
P.entries["zone:wailing"] = {n="Caverna Ululante",s="Escondida sob o Oásis das Águas Claras, nos áridos Sertões, fica a Caverna Ululante, um sistema labiríntico de nascentes e fissuras subterrâneas que recebeu esse nome devido ao silvo sinistro do vapor represado. O que começou como um nobre esforço druídico para revitalizar a savana crestada pelo sol de Kalimdor transformou-se em um submundo distorcido e venenoso. As cavernas agora fervilham com uma fauna deturpada e discípulos decaídos corrompidos por um pesadelo profundo e antinatural.",h="Escondida sob o Oásis das Águas Claras, nos áridos Sertões, fica a Caverna Ululante, um sistema labiríntico...",kw={"desvirtuado","druidas da presa","pesadelo esmeralda","lady sucurina","lorde cobrahn","lorde pítias","lorde serpentis","oásis das águas claras","mutanus","naralex","verdan"},ang={["class:Druid"]="Para druidas tanto da tradição cenariana quanto da senda tauren, as cavernas são um aviso trágico dos perigos dentro do Sonho Esmeralda e um dever solene de purgar seus irmãos decaídos, os Druidas da Presa.",["race:NightElf"]="Naralex era uma figura reverenciada entre os druidas elfos noturnos, e a tragédia de sua corrupção pelo Pesadelo Esmeralda representa uma catástrofe dolorosa para seus semelhantes do outro lado do mar.",["race:Tauren"]="As águas retorcidas ameaçam os frágeis oásis que sustentam a vida pelos Sertões, tornando a purificação das nascentes vital para as tribos de Mulgore e da Encruzilhada."},sec={{t="Uma Nobre Visão Tornada Venenosa",b="O druida elfo noturno Naralex originalmente descobriu este vasto sistema de águas e concebeu um plano ambicioso: ao abrir um canal direto para o Sonho Esmeralda, ele drenaria pura essência vital primordial através das nascentes subterrâneas, transformando os ressequidos Sertões de volta em um paraíso verdejante e próspero. Nas profundezas das cavernas, Naralex entrou em comunhão com o Sonho, ancorado por seus leais acólitos. Tragicamente, em vez de extrair vitalidade pura, a mente adormecida do druida tocou o Pesadelo Esmeralda. A corrupção purulenta apoderou-se dele instantaneamente, transformando seu canal de boas intenções em uma válvula que despeja veneno e loucura nos cursos d'água subterrâneos."},{t="Os Druidas da Presa",b="À medida que a energia sombria do Pesadelo irradiava da forma indefesa de Naralex, seus pupilos sucumbiram à loucura. Abandonando a sabedoria tranquila do Círculo Cenariano, eles formaram os fanáticos Druidas da Presa. Assumindo formas reptilianas, os líderes da seita — Lady Sucurina, Lorde Cobrahn, Lorde Pítias e Lorde Serpentis — agora abraçam a mutação venenosa das cavernas em vez de combatê-la. Eles protegem ativamente seu mestre adormecido de qualquer interferência externa, acreditando que esse crescimento retorcido é a verdadeira evolução da natureza."},{t="O Pesadelo Feito Carne",b="Quebrar o domínio dos Druidas da Presa não salva Naralex automaticamente. Quando seus discípulos restantes não corrompidos iniciam o ritual para despertá-lo suavemente de seu transe em Dreamer's Rock, o subconsciente agitado do elfo adormecido expurga violentamente seu mais profundo terror. A criatura que irrompe — um murloc monstruoso e distorcido chamado Mutanus, o Devorador — é a manifestação física dos piores pesadelos de Naralex. Apenas derrotando essa abominação o canal para o Pesadelo pode ser rompido, permitindo que Naralex acorde, assuma uma forma aviária e fuja em voo das cavernas maculadas."}},faq={{q="Por que se chama Caverna Ululante?",a="A caverna recebe esse nome devido aos uivos lamentosos ouvidos por todos os túneis. Esses sons são produzidos naturalmente quando saídas subterrâneas de vapor e rajadas de vento de alta pressão forçam passagem por fissuras estreitas na rocha calcária.",al={"por que caverna ululante","origem do nome","por que elas uivam"}},{q="O que fez com que as feras de dentro se tornassem 'desvirtuadas'?",a="Quando Naralex caiu sob o domínio do Pesadelo Esmeralda, as energias oníricas maculadas vazaram diretamente para as nascentes subterrâneas. Beber e viver nessas águas contaminadas causou mutações nos raptores, crocoliscos e serpentes naturais, transformando-os em variantes 'desvirtuadas' antinaturais.",al={"corrupção desvirtuada","por que os raptores mutacionam","origem das feras desvirtuadas"}},{q="Quem são os Druidas da Presa?",a="Eles já foram os devotos acólitos elfos noturnos e taurens de Naralex. Corrompidos junto com ele pelo Pesadelo, suas mentes se despedaçaram e distorceram suas artes druídicas em adoração a serpentes e veneno, adotando títulos como Cobrahn, Pítias e Sucurina.",al={"druidas da presa","história dos druidas da presa","quem é serpentis"}},{q="Por que o último chefe é um murloc gigante chamado Mutanus?",a="Mutanus surge durante a tentativa de despertar Naralex. Sua natureza e conexão com o druida adormecido são reveladas conforme o ritual se desenrola.",al={"por que mutanus murloc","o que é mutanus","história do último chefe"}},{q="O que acontece após Mutanus ser derrotado?",a="A tentativa dos discípulos de despertar Naralex continua após o confronto. O destino do druida é revelado ao final do ritual.",al={"despertar naralex","desfecho de naralex","o que acontece com naralex"}},{q="Quem vive na caverna acima da entrada da masmorra?",a="Instalados dentro da cavidade ocular de rocha semelhante a um crânio da caverna estão lealistas do Círculo Cenariano, incluindo Nalpak e Ebru. Eles procuram viajantes corajosos para coletar Deviate Hides e purificar a corrupção antes que ela engula completamente os Sertões.",al={"caverna acima da entrada","npcs no olho do crânio de serpente","quem são nalpak e ebru"}}},fx={["3386ab3f"]={q="O que é a Caverna Ululante?",a="A Caverna Ululante é uma extensa rede de cavernas subterrâneas que passa sob os áridos Sertões, perto do Oásis das Águas Claras. Suas nascentes subterrâneas naturais canalizam água por quilômetros sob a terra, alimentando os raros oásis de superfície espalhados pela região. Descoberta pelo druida Elfo Noturno Naralex, ela deveria ser o coração de um grande projeto de regeneração natural. Em vez disso, tornou-se um epicentro de corrupção perigosa após uma catástrofe trágica atingir os druidas lá dentro.",al={"o que é a caverna ululante","visão geral da caverna ululante","sobre a caverna ululante"}},e070a543={q="Quem vive lá embaixo?",a="As cavernas fervilham com vida selvagem antinatural e druidas rebeldes. Os seguidores corrompidos de Naralex, os Druidas da Presa, reivindicaram os túneis como seu domínio ao lado de serpentes mutantes, limos, raptores e crocoliscos. Do lado de fora do portal da instância, feras selvagens, limos e até párias espreitam nas passagens úmidas, enquanto os druidas corrompidos guardam as câmaras internas e protegem seu mestre adormecido.",al={"quem está na caverna ululante","criaturas da caverna ululante","habitantes da caverna ululante"}},["49d47201"]={q="Por que a Horda me enviou aqui?",a="A estranha mutação das feras locais e as energias fétidas que borbulham do Oásis das Águas Claras ameaçam todos os Sertões. A Horda e os druidas Cenarion de Penhasco do Trovão não podem tolerar um poder sombrio incontrolável envenenando a terra e os cursos d'água bem à porta da Encruzilhada. Você foi enviado para investigar, dar um fim aos líderes rebeldes dos Druidas da Presa e ajudar a conter o perigo crescente.",al={"por que estou na caverna ululante","missão da horda na caverna ululante","por que me enviar para a caverna ululante"}},d445bb78={q="Isso é parte de um problema maior nos Sertões?",a="Sim. Os canais subterrâneos sob essas cavernas alimentam os oásis de superfície por todos os Sertões. A mancha do Emerald Nightmare corrompendo as águas dentro das cavernas começou a transbordar para a paisagem ao redor, fazendo com que criaturas selvagens como raptores e crocoliscos sofram mutações e transformando o Oásis das Águas Claras em um criadouro para estranhas formas de vida anormais.",al={"problema no oásis dos sertões","corrupção anormal nos sertões","a caverna ululante está afetando os sertões"}},["038fd1cf"]={q="Os anormais estão se espalhando para fora das cavernas?",a="Eles já estão. As nascentes subterrâneas fluem diretamente para oásis de superfície como o Oásis das Águas Claras, trazendo crescimento antinatural e criaturas mutantes para a savana aberta. Criaturas estranhas como Peixe Anormal podem ser pescadas nas águas do lado de fora, e predadores mutantes agressivos assediam cada vez mais os viajantes entre os oásis e a Encruzilhada.",al={"os anormais estão se espalhando","feras anormais nos sertões","peixe anormal do lado de fora"}},["8502642f"]={q="Quem está no comando aqui embaixo?",a="Enquanto Naralex jaz preso em seu sono corrompido nas profundezas das cavernas, o governo diário das cavernas pertence aos Druidas da Presa. Eles são liderados pelo Lorde Serpentis, outrora o melhor aluno de Naralex, que reuniu seus irmãos distorcidos para refazer a terra em seu próprio paraíso deturpado, ao lado de outros lordes dos presas como Lorde Cobrahn, Lorde Pítias e Lady Sucurina.",al={"quem lidera a caverna ululante","líder da caverna ululante","chefe da caverna ululante"}},["32be29c8"]={q="O que é o Sonho Esmeralda e como ele se conecta a esta caverna?",a="O Sonho Esmeralda é um vasto reino espiritual que representa Azeroth intocada e selvagem, cuidado pela revoada dragônica verde e acessível aos druidas. Naralex acreditava que poderia canalizar as energias puras e restauradoras do Sonho para os aquíferos subterrâneos da Caverna Ululante para restaurar a vida vegetal exuberante aos Sertões. No entanto, quando ele acessou o Sonho, foi aprisionado pelo Emerald Nightmare, projetando uma versão distorcida da natureza nas cavernas físicas.",al={"conexão com o sonho esmeralda","caverna ululante e sonho esmeralda","naralex e sonho esmeralda"}},["38e519c2"]={q="Por que todo mundo está tão preocupado com este lugar?",a="As nascentes subterrâneas nas cavernas alimentam os oásis principais que sustentam a vida por todos os áridos Sertões. Se a mancha do Emerald Nightmare continuar a infiltrar-se naqueles cursos d'água sem controle, as mutações distorcidas e a loucura que corrompem a flora e a fauna da caverna podem se espalhar por toda a região, transformando a terra em um horror desperto.",al={"por que se preocupar com a caverna ululante","ameaça da caverna ululante aos sertões","quão ruim é a caverna ululante"}},["81917ac6"]={q="Como fui parar na Caverna Ululante?",a="Você viajou para o sul da Encruzilhada até o Oásis das Águas Claras, seguindo relatos de feras bizarras e águas corrompidas infiltrando-se pelos Sertões. Escondida atrás da folhagem exuberante e dos acampamentos dos centauros Kolkar, fica uma caverna maciça em forma de crânio esculpida na rocha. Atraído por pedidos de ajuda de Penhasco do Trovão, goblins de Vila Catraca buscando essências estranhas, ou discípulos acampados no olho do crânio acima, você desceu pelas fissuras sinuosas e pelo silvo dos gêiseres subterrâneos até as profundezas gementes abaixo.",al={"como cheguei aqui","como chego à caverna ululante","de onde vim para chegar aqui"}},["28a012f3"]={q="O que eu devo fazer na Caverna Ululante?",a="Você está aqui para expurgar a corrupção que se apoderou desta nascente subterrânea. O druida elfo noturno Naralex caiu em um sono de pesadelo tentando revitalizar os Sertões, distorcendo as criaturas lá dentro e transformando seus discípulos nos venenosos Druidas da Presa. Você deve caçar os quatro lordes dos presas — Lady Sucurina, Lorde Cobrahn, Lorde Pítias e Lorde Serpentis — para quebrar o domínio deles, e então ajudar o discípulo restante a despertar Naralex antes que seu pesadelo febril consuma o oásis completamente.",al={"qual é meu objetivo aqui","por que estou na caverna ululante","o que estou fazendo aqui embaixo"}}},fp="15,278,31.501.0,22.495.0,24.481.1,37.218.0,50.226.0,31.267.0,51.127.1,39.123.1,52.229.0"}
P.entries["zone:warsonggulch"] = {n="Ravina Brado Guerreiro",s="A Ravina Brado Guerreiro é um vale arborizado na fronteira entre o Vale Gris e os Sertões, palco de uma batalha entre a Horda e a Aliança que nunca termina de verdade. Os orcs do clã Brado Guerreiro cortam a madeira do Vale Gris para a Horda, e os elfos noturnos do Castelo Asa de Prata lutam para expulsá-los da floresta sagrada. Combatentes de todas as raças vêm oferecer espada ou magia, e cada lado ataca a fortaleza do outro para roubar sua bandeira.",h="A Ravina Brado Guerreiro é um vale arborizado na fronteira entre o Vale Gris e os Sertões, palco de uma...",kw={"ravina brado guerreiro","campo de batalha","pioneiros do brado guerreiro","sentinelas da asa de prata","castelo asa de prata","warsong mill","bandeira","madeira","vale gris","grom hellscream"},ang={["faction:Alliance"]="Soldados da Aliança lutam aqui por seus aliados elfos noturnos, cuja floresta sagrada cai uma árvore por vez sob os machados do clã Brado Guerreiro.",["faction:Horde"]="Cada tora que deixa a Warsong Mill ergue uma muralha da Horda em algum lugar de Kalimdor; controlar a ravina mantém a Horda construindo.",["race:NightElf"]="Estes bosques conhecem os passos dos kaldorei há dez mil anos. Cada orc expulso da ravina é um pedaço do Vale Gris reconquistado.",["race:Orc"]="O clã Brado Guerreiro é o próprio povo de Grom Hellscream, e a ravina é onde seus guerreiros ainda honram seu nome, machado em punho contra as Sentinelas."},sec={{t="Madeira e Sangue",b="A Horda construiu seu novo lar em Kalimdor com madeira, e grande parte dessa madeira vem do Vale Gris. O clã Brado Guerreiro, guerreiros de Grom Hellscream, cortam a floresta desde o primeiro desembarque da Horda, e sua Warsong Mill no fim da ravina abastece os acampamentos e muralhas da Horda. Para os elfos noturnos, cada árvore derrubada fere uma floresta que eles guardam há dez mil anos, e eles não esqueceram que os guerreiros de Grom outrora mataram Cenarius nestes bosques."},{t="Pioneiros e Sentinelas",b="Os combatentes da Horda aqui são os Pioneiros do Brado Guerreiro, abastecidos pelo Campo-base Mor'shan, na extremidade norte dos Sertões, onde Kelm Hargunth os mantém armados e alimentados. Contra eles estão as Sentinelas da Asa de Prata do Castelo Asa de Prata, guerreiros elfos noturnos juramentados a expulsar todo invasor do Vale Gris, abastecidos por Iliana Fulgiluna no Bosque Asa de Prata. Aliados de ambos os lados afluem à ravina: anões e humanos ao lado das Sentinelas, taurens, trolls e Renegados ao lado dos Pioneiros."},{t="A Luta pelos Estandartes",b="Cada lado mantém uma fortaleza em uma das extremidades da ravina: o Moinho Brado Guerreiro, para a Horda, e o Castelo Asa de Prata, para os elfos noturnos. Cada lado guarda seu estandarte ali. A batalha é uma disputa de incursões: os combatentes invadem a fortaleza inimiga, tomam sua bandeira e correm de volta com ela até a própria fortaleza, enquanto os defensores os perseguem. Cada bandeira trazida para casa é um golpe no orgulho do inimigo, e vence o dia o lado que capturar mais."}},faq={{q="O que é a Ravina Brado Guerreiro?",a="A Ravina Brado Guerreiro é um campo de batalha em um vale arborizado entre o Vale Gris e os Sertões. Os Pioneiros do Brado Guerreiro da Horda e as Sentinelas da Asa de Prata dos elfos noturnos lutam ali pela extração de madeira do Vale Gris pela Horda, com cada lado tentando capturar a bandeira do outro.",al={"o que é a ravina brado guerreiro","campo de batalha ravina brado guerreiro","rbg"}},{q="Por que a Horda luta na Ravina Brado Guerreiro?",a="A Horda precisa da madeira do Vale Gris para construir e manter seu lar em Kalimdor. A serraria do clã Brado Guerreiro na ravina é uma de suas principais fontes, e os Pioneiros a defendem para que os acampamentos e muralhas da Horda continuem a se erguer.",al={"interesses da horda na ravina brado guerreiro","por que os orcs extraem madeira no vale gris","motivo dos pioneiros do brado guerreiro"}},{q="Por que os elfos noturnos lutam na Ravina Brado Guerreiro?",a="Para os elfos noturnos, o Vale Gris é uma floresta sagrada que eles guardam há dez mil anos, e o clã Brado Guerreiro outrora matou o semideus Cenarius ali. As Sentinelas da Asa de Prata lutam para deter a extração de madeira e expulsar os orcs de seus bosques, e o restante da Aliança está ao lado delas.",al={"interesses da aliança na ravina brado guerreiro","por que as sentinelas lutam","motivo das sentinelas da asa de prata"}},{q="Quem são os Pioneiros do Brado Guerreiro?",a="Os Pioneiros do Brado Guerreiro são os combatentes da Horda na Ravina Brado Guerreiro, originários do clã Brado Guerreiro outrora liderado por Grom Hellscream. Eles são abastecidos a partir do Campo-base Mor'shan, no norte dos Sertões, onde Kelm Hargunth equipa aqueles que lutam por eles.",al={"pioneiros do brado guerreiro","combatentes do clã brado guerreiro","kelm hargunth"}},{q="Quem são as Sentinelas da Asa de Prata?",a="As Sentinelas da Asa de Prata são guerreiras elfas noturnas do Castelo Asa de Prata, juramentadas a expulsar a Horda do Vale Gris. Iliana Fulgiluna, no Bosque Asa de Prata, abastece os campeões da Aliança que lutam ao lado delas na ravina.",al={"sentinelas da asa de prata","castelo asa de prata","iliana fulgiluna"}},{q="Como a batalha na Ravina Brado Guerreiro é vencida?",a="Cada lado mantém sua bandeira em sua própria fortaleza. Os combatentes invadem a base inimiga, capturam sua bandeira e a levam de volta para a sua própria enquanto defendem seu estandarte, e o lado que trouxer mais bandeiras para a base vence.",al={"objetivos da ravina brado guerreiro","capturar a bandeira brado guerreiro","como vencer na ravina brado guerreiro"}}},fp="13,291,16.424.0,23.488.0,28.315.0,22.226.0,42.201.0,46.259.0,30.223.0,33.216.0,39.193.0"}
P.entries["zone:westernplaguelands"] = {n="Terras Pestilentas Ocidentais",s="Outrora o fértil celeiro agrícola do norte de Lordaeron, as Terras Pestilentas Ocidentais agora sufocam sob uma névoa tóxica e legiões de mortos-vivos. Embora os caldeirões de Kel'Thuzad tenham arruinado as fazendas e cidades da região, o solo ainda se apega tenazmente à vida. A Aurora Argêntea, a Aliança, os Renegados e a Cruzada Escarlate travam campanhas desesperadas por seus campos assolados.",h="Outrora o fértil celeiro agrícola do norte de Lordaeron, as Terras Pestilentas Ocidentais agora sufocam sob...",kw={"andorhal","o baluarte","castro das flechas","caldeirões","acampamento ventogelante","amparo","bastilha mardenforte","scolomântia","tumba de uther","terras pestilentas ocidentais"},ang={["class:Paladin"]="Os campos profanados de Lordaeron são uma prova sombria para guerreiros sagrados, oferecendo peregrinação à Tumba de Uther, bem como uma guerra justa contra os horrores de Scolomântia e os fanáticos corrompidos de Amparo.",["faction:Alliance"]="O Acampamento Ventogelante serve como a guarnição avançada da Aliança, onde o Comandante Ashlam Punhovalor lidera campanhas para neutralizar os caldeirões da peste e vingar as cidades caídas de Lordaeron.",["faction:Horde"]="O Baluarte marca a fronteira da soberania dos Renegados; a partir daqui, a Horda avança para o leste para neutralizar comandantes do Flagelo e combater os fanáticos Escarlates ao longo de seu flanco vulnerável.",["profession:Herbalism"]="A mácula persistente faz da região um dos poucos lugares onde flora rara e perigosa, como Pragônia e Lágrimas-de-arthas, consegue criar raízes entre os pinheirais assolados."},sec={{t="O Celeiro de Lordaeron",b="Antes da Terceira Guerra, esta terra era um corredor verdejante de fazendas que se estendia a leste das Clareiras de Tirisfal até o Lago das Flechas. Amparo governava a administração do norte a partir da Bastilha Mardenforte, enquanto a vasta cidade de Andorhal orquestrava o armazenamento e a exportação de grãos por todo o reino. Esse papel agrícola crucial tornou a região o alvo principal de Kel'Thuzad. Ao introduzir a Peste da Morte-viva diretamente nas remessas de grãos em Andorhal, a Seita dos Malditos transformou o sustento de Lordaeron em sua ruína."},{t="Uma Terra Sob Cerco",b="Para envenenar o solo de forma permanente, o Flagelo ergueu quatro enormes caldeirões da peste pelas maiores propriedades agrícolas: Campo Pedravil, Lágrimas de Dalson, o Antro Repelente e a Aridez de Garrão. Hoje, monstruosos Senhores dos Caldeirões mantêm essas cubas nocivas, bombeando névoa venenosa na atmosfera. As árvores ao redor se retorcem com crescimentos tumorais inchados, e animais selvagens corrompidos vagam descontrolados pela vegetação. Sob o Castro das Flechas, no Lago das Flechas, o Umbromestre Gandling treina necromantes dentro de Scolomântia, agravando a ameaça dos mortos-vivos."},{t="Facções Divididas",b="Apesar da onipresença do Flagelo, várias facções mantêm posições disputadas. a Cruzada Escarlate controla a fortaleza de Amparo no norte, expurgando com zelo raivoso qualquer coisa que considerem contaminada. Ao sul, as forças da Aliança se organizam a partir do Acampamento Ventogelante, enquanto os Renegados defendem suas fronteiras no Baluarte. Mediando e liderando a luta contra os caldeirões dos mortos-vivos está a neutra Aurora Argêntea, que ajuda campeões de ambas as facções e guarda a Tumba de Uther — o último solo verdadeiramente santificado da região."}},faq={{q="Por que a Peste atingiu esta área com tanta força?",a="Andorhal era o centro de distribuição agrícola do norte de Lordaeron. Kel'Thuzad atacou intencionalmente o suprimento regional, infectando silos de grãos e instalando enormes caldeirões da peste em quatro grandes propriedades rurais para espalhar rapidamente a morte-viva por meio de remessas de alimentos por todo o reino.",al={"por que as terras pestilentas ocidentais foram assoladas","o que aconteceu com andorhal","por que caldeirões aqui"}},{q="Quem controla Amparo no norte?",a="Amparo e sua fortaleza, a Bastilha Mardenforte, são governadas pela Cruzada Escarlate. Embora originalmente tenha sido um centro administrativo regional de Lordaeron, os fanáticos agora executam qualquer forasteiro que se aproxime de suas fronteiras, vendo todos os não membros da cruzada com suspeita.",al={"facção de amparo","quem vive na bastilha mardenforte","amparo é amigável"}},{q="Onde os jogadores da Aliança e da Horda podem encontrar postos avançados seguros?",a="A Aliança mantém o Acampamento Ventogelante perto da fronteira sul com as Montanhas de Alterac, oferecendo um mestre de voo e aliados da Aurora Argêntea. A Horda opera a partir d'O Baluarte, na fronteira oeste com as Clareiras de Tirisfal.",al={"onde ficam as rotas de voo","acampamento da horda tpo","acampamento da aliança tpo"}},{q="Qual é o objetivo dos caldeirões da peste nos campos?",a="Erigidos pela Seita dos Malditos no Campo Pedravil, nas Lágrimas de Dalson, n'O Antro Repelente e na Aridez de Garrão, esses caldeirões bombeiam vapores constantes da peste para o ar e o solo. Agentes da Aurora Argêntea recrutam aventureiros para abater os Senhores dos Caldeirões e neutralizar as misturas tóxicas.",al={"o que são os caldeirões","objetivo dos caldeirões","caldeirão de pedravil"}},{q="O que é Scolomântia e onde ela fica?",a="Scolomântia é uma academia subterrânea de necromancia administrada pelo Flagelo e pela Seita dos Malditos. Ela fica escondida sob as ruínas do Castro das Flechas, uma fortaleza insular situada nas águas a sudeste do Lago das Flechas.",al={"localização de scolomântia","onde fica scolomântia","masmorra castro das flechas"}},{q="Alguma parte das Terras Pestilentas Ocidentais permaneceu pura?",a="A Tumba de Uther, localizada na Colina do Pesar perto do limite sul da zona, permanece totalmente sagrada e intocada pela praga. Ela se ergue como um memorial consagrado ao falecido Alto-general Uther, o Arauto da Luz, e à perdida Ordem do Punho de Prata.",al={"solo sagrado em tpo","a tumba de uther está limpa","a tumba de uther é segura"}}},fp="19,342,28.378.0,18.438.0,16.443.0,41.268.0,37.227.0,56.233.0,58.277.0,44.206.0,51.204.0"}
P.entries["zone:westfall"] = {n="Cerro Oeste",s="As fazendas de Cerro Oeste estão expostas, e a Irmandade Défias domina boa parte da zona rural. Outrora o celeiro de Ventobravo, o território agora luta para sobreviver sem apoio da coroa nem guarnições militares.",h="As fazendas de Cerro Oeste estão expostas, e a Irmandade Défias domina boa parte da zona rural.",kw={"minas mortas","défias","golem da colheita","milícia","arroio da lua","saldean","morro da sentinela","stoutmantle","vancleef","cerro oeste"},ang={["class:Rogue"]="Como ladino, você encontra uma guerra nas sombras por toda Cerro Oeste, onde espiões da AVIN enfrentam batedores, ladrões e assassinos da Irmandade Défias com malícia das ruas.",["faction:Alliance"]="Como viajante da Aliança, você pode ver como a People's Militia defende o Morro da Sentinela. Sem ela, a Irmandade Défias controlaria os acessos ao sul da Floresta de Elwynn.",["profession:Cooking"]="Como cozinheiro, você pode descobrir como os colonos sitiados na Fazenda dos Saldanha se viram com feras locais de carne dura e ensinam viajantes a preparar Westfall Stew.",["race:Human"]="Como humano, você vê em Cerro Oeste a decadência política de Ventobravo. Os fazendeiros que passam fome na terra foram abandonados pela nobreza que tanto trabalharam para alimentar."},sec={{t="Uma terra abandonada",b="Os pastos e campos de trigo de Cerro Oeste já alimentaram o Reino de Ventobravo. Após a Second War, os recursos financeiros do reino escassearam, e seus líderes negligenciaram o território. Ventobravo enviou recursos para outros lugares e retirou suas guarnições. A terra ficou sem cultivo.\n\nAgora, pastos estéreis, ventos costeiros impiedosos, golems da colheita descontrolados e gnolls Riverpaw dificultam a sobrevivência dos poucos colonos que restam."},{t="A ascensão da Irmandade",b="A chegada da Irmandade Défias acelerou o colapso de Cerro Oeste. Os bandidos usam máscaras vermelhas e seguem um líder cujo nome ninguém na zona rural conhece. Eles fizeram de Cerro Oeste sua fortaleza, queimando os campos dos fazendeiros, salgando o solo e ocupando minas abandonadas.\n\nDe Arroio da Lua, uma cidade fantasma, a Irmandade governa a maior parte da zona rural, embora sem título oficial."},{t="A People's Militia",b="A House of Nobles ignorou o sofrimento de Cerro Oeste, então os moradores assumiram a própria defesa. No Morro da Sentinela, Gryan Stoutmantle formou a People's Militia, uma força voluntária que resiste aos gnolls e bandidos. Ventobravo não envia soldados regulares nem suprimentos.\n\nA milícia depende de aventureiros errantes para repelir os Défias e proteger as fazendas que restam."},{t="Pedreiros de máscaras vermelhas",b="Edwin VanCleef lidera a Irmandade. Ele era o mestre da guilda que reconstruiu Ventobravo, mas a House of Nobles negou o pagamento a seus pedreiros, e tumultos os expulsaram. Eles adotaram a máscara vermelha em Cerro Oeste. Os bandidos que queimam seus campos são as mesmas mãos que ergueram as muralhas da capital."},{t="A conspiração das Minas Mortas",b="Sob Arroio da Lua, Edwin VanCleef reuniu assassinos, goblins e renegados nos poços de ouro abandonados das Minas Mortas. A Irmandade está construindo ali um enorme navio de guerra couraçado. Ele foi projetado para subir a costa e bombardear Ventobravo."}},faq={{q="Por que tantas fazendas estão abandonadas em Cerro Oeste?",a="Ventobravo retirou suas guarnições quando a manutenção ficou cara demais, deixando Cerro Oeste desprotegido. A Irmandade Défias então tomou grande parte da zona rural, expulsando colonos, queimando plantações e reprogramando vigias mecânicos da colheita como sentinelas letais.",al={"fazendas abandonadas","por que cerro oeste está morto","por que a terra está sem cultivo"}},{q="Por que Ventobravo não envia tropas para ajudar Cerro Oeste?",a="O tesouro do reino está sob pressão, e a House of Nobles dá maior prioridade a ameaças em outras terras. Manipulações na corte também privaram discretamente Cerro Oeste de atenção e suprimentos, deixando os moradores à própria defesa.",al={"por que não há exército de ventobravo","onde estão os guardas","ajuda de ventobravo"}},{q="O que é a People's Militia?",a="Gryan Stoutmantle organizou a People's Militia no Morro da Sentinela para defender Cerro Oeste. Sem soldados da coroa, fazendeiros e colonos se uniram para combater a Irmandade Défias e os gnolls Riverpaw.",al={"people's militia","milícia do morro da sentinela","exército de gryan stoutmantle"}},{q="Quem lidera a Irmandade Défias em Cerro Oeste?",a="Edwin VanCleef, antigo mestre da Stonemasons Guild, lidera a Irmandade Défias. Ele supervisionou a reconstrução de Ventobravo, depois levou seus trabalhadores para Cerro Oeste e os armou após uma amarga disputa salarial terminar em tumultos.",al={"líder dos défias","quem lidera os défias","vancleef"}},{q="O que está escondido em Arroio da Lua?",a="Sob um celeiro discreto em Arroio da Lua fica a entrada das Minas Mortas. A Irmandade Défias transformou a mina de ouro abandonada em uma fortaleza subterrânea e um estaleiro para sua guerra contra Ventobravo.",al={"segredo de arroio da lua","o que há nas minas mortas","mina de arroio da lua"}},{q="Por que os espantalhos mecânicos estão atacando as pessoas?",a="Engenhoqueiros goblins aliados aos Défias capturaram os vigias mecânicos da colheita, originalmente construídos para cuidar das plantações e espantar pragas. Eles os modificaram para patrulhar os campos e matar invasores.",al={"golems da colheita atacando","vigias da colheita","espantalhos malignos"}}},fx={cd1e134e={q="O que é o Cerro Oeste?",a="Cerro Oeste é o território ocidental varrido pelos ventos do Reino de Ventobravo, situado a oeste da Floresta de Elwynn e ao sul do mar. Outrora o celeiro fértil do reino, suas colinas ondulantes e vastas pastagens alimentaram Ventobravo por gerações. Hoje, negligenciado pela coroa e devastado pelo conflito, deteriorou-se em planícies de poeira improdutivas, propriedades rurais arruinadas e território de fora da lei.",al={"que zona é esta","fale-me sobre o cerro oeste","lore do cerro oeste"}},["44cadea7"]={q="Por que é tão vazio por aqui?",a="Uma combinação composta de seca, negligência e banditismo esvaziou o campo. Após a Segunda Guerra, Ventobravo concentrou seus soldados em outros lugares, deixando as propriedades locais indefesas. Quando a Irmandade Défias se levantou, eles expulsaram fazendeiros, queimaram plantações e salgaram campos. Sem guarnições reais para protegê-los, a maioria dos habitantes fugiu ou morreu de fome.",al={"por que o cerro oeste é estéril","por que tão vazio","por que não há ninguém aqui"}},["1a97e791"]={q="O Cerro Oeste sempre foi tão pobre?",a="De jeito nenhum. Por gerações, o Cerro Oeste foi o orgulhoso coração agrícola de Ventobravo, celebrado por campos de trigo dourados, solo rico e minas de ouro abundantes como Jangolode e as Minas Mortas. Sua comida alimentava a capital, e suas minas enchiam os tesouros reais antes que guerras e agitação doméstica o deixassem estéril.",al={"o cerro oeste sempre foi pobre","o cerro oeste era rico antes","passado do cerro oeste"}},["1d4a9481"]={q="O que é a Irmandade Défias?",a="A Irmandade Défias é uma organização criminosa massiva composta por pedreiros rebeldes, ladrões, bandoleiros e párias. Liderados por Edwin VanCleef, eles tomaram as fazendas e minas abandonadas do Cerro Oeste para travar uma amarga guerra das sombras contra o Reino de Ventobravo, com a intenção de exigir retribuição por dívidas não pagas e traições percebidas.",al={"quem são os defias","o que é a Irmandade Défias","quem são esses bandidos"}},b6953315={q="Por que os Defias usam bandanas vermelhas?",a="Bandanas vermelhas são a marca registrada da Irmandade Défias, e o material indica a patente de um membro. Red Silk Bandanas identificam membros de patente mais alta; a Batedora Riell pede que aventureiros as coletem como prova de suas mortes.",al={"por que bandanas vermelhas","máscaras vermelhas defias","significado das máscaras vermelhas"}},["908b4fe1"]={q="O que os Defias querem no Cerro Oeste?",a="Eles tratam o Cerro Oeste como sua fortaleza soberana e base de operações. Ao controlar suas minas de ouro, apreender suprimentos de comida e expulsar fazendeiros legalistas, eles podem secretamente construir suas forças e maquinário longe da vista direta de Ventobravo enquanto tramam a queda do reino.",al={"o que os defias querem","objetivos dos defias no cerro oeste","por que os defias estão no cerro oeste"}},d384bc2d={q="Por que fui enviado para o Cerro Oeste?",a="Você foi enviado para cá porque o exército regular de Ventobravo se recusa a mobilizar tropas para o Cerro Oeste, ou falha em fazê-lo, deixando o território à beira de cair completamente no banditismo. As autoridades da Floresta de Elwynn redirecionam aventureiros capazes para o oeste para reforçar os habitantes locais, que estão desesperados por ajuda.",al={"por que estou no cerro oeste","quem me enviou para o cerro oeste","por que me enviar para cá"}},d59f010f={q="Quem é Gryan Stoutmantle?",a="Gryan Stoutmantle é um paladino da Mão de Prata e natural do Cerro Oeste. Ao retornar para casa após lutar em Lordaeron durante a Terceira Guerra, ele encontrou sua terra natal invadida por bandidos e abandonada pelo exército de Ventobravo. Em resposta, ele reuniu defensores locais para estabelecer a Milícia Popular no Morro da Sentinela.",al={"quem é stoutmantle","gryan stoutmantle","quem lidera o morro da sentinela"}},af1c3ddb={q="Gryan Stoutmantle está realmente no comando do Cerro Oeste?",a="Na prática, sim. Embora o rei-menino em Ventobravo detenha a reivindicação legal do Cerro Oeste, a coroa quase não exerce autoridade real aqui. Stoutmantle e sua milícia voluntária no Morro da Sentinela representam a única defesa e força policial funcional que resta no reino.",al={"quem governa o cerro oeste","stoutmantle é o líder","quem está no comando"}},c01912f7={q="O que aconteceu com a Guilda dos Alvenéis?",a="Sob o comando do Grão-mestre Edwin VanCleef, a Guilda dos Alvenéis passou anos reconstruindo Ventobravo após a Primeira Guerra. Quando o trabalho foi concluído, a Câmara dos Nobres recusou-se a pagar a quantia combinada. Após o fracasso de apelos pacíficos, a guilda foi dissolvida à força, desencadeando tumultos furiosos que levaram os pedreiros ao exílio.",al={"o que aconteceu com os alvenéis","história da guilda dos alvenéis","quem eram os alvenéis"}},ec2fd06e={q="Ventobravo realmente se recusou a pagar os Pedreiros?",a="Sim. A Câmara dos Nobres havia acumulado dívidas impressionantes expandindo expedições militares em outros lugares, deixando o reino quase falido. Influenciados por intrigas da corte e pela arrogância aristocrática, os nobres ofereceram apenas trocados por um trabalho colossal, recusando-se abertamente a honrar os contratos completos.",al={"ventobravo enganou os pedreiros","por que os nobres não pagaram","disputa de pagamento dos pedreiros"}},cf60f690={q="Por que há tantos gnolls no Cerro Oeste?",a="Os gnolls da matilha Pata-de-Rio migraram através da fronteira para explorar a ausência de soldados de Ventobravo. Pior, a Irmandade Défias os contratou ativamente como mercenários, posicionando-os pelas colinas e planícies para emboscar viajantes e assediar quaisquer propriedades que ainda resistissem.",al={"por que há gnolls aqui","gnolls pata-de-rio cerro oeste","gnolls de danuvin"}},e40fa3bd={q="O que é Arroio da Lua?",a="Arroio da Lua já foi o principal mercado e cidade mineradora do sul do Cerro Oeste. Situada acima da entrada antiga para as Minas Mortas, foi completamente tomada e esvaziada pela Irmandade Défias, que agora usa seus prédios vazios como um perímetro de guarda para sua fortaleza subterrânea.",al={"o que é arroio da lua","lore de arroio da lua","conte-me sobre arroio da lua"}},["46f1c864"]={q="Para onde leva a investigação da Defias?",a="Sua investigação revela o coração secreto da Irmandade sob Arroio da Lua, nas Minas Mortas. Lá, nas profundezas das cavernas subterrâneas, Edwin VanCleef supervisiona a construção de um enorme navio de guerra revestido de ferro, destinado a bombardear Ventobravo a partir do mar, o que leva a um ataque direto ao próprio mestre da guilda.",al={"para onde vai a série de missões da défias","como termina a história da défias","conclusão das minas mortas"}},["27471424"]={q="Como eu vim parar no Cerro Oeste?",a="Você provavelmente atravessou a ponte do rio vindo da Floresta de Elwynn seguindo a estrada para o oeste, enviado por autoridades ou amigos do Morro da Sentinela. Com as forças de Ventobravo reduzidas e incapazes de poupar tropas reais, espalhou-se pelas terras vizinhas que Gryan Stoutmantle e os fazendeiros locais precisam desesperadamente de mãos capazes. Quer você tenha chegado atendendo a um chamado por ajuda ou simplesmente seguido a estrada real em busca de trabalho, você entrou em um reino que os soldados do reino praticamente abandonaram.",al={"como cheguei aqui","como cheguei ao cerro oeste","como vim parar aqui"}},["6324593c"]={q="O que eu devo fazer no Cerro Oeste?",a="Sua missão principal é ajudar a Milícia Popular no Morro da Sentinela a repelir a miríade de ameaças que sufocam a província. Gryan Stoutmantle precisa de voluntários para eliminar a vida selvagem agressiva, silenciar os vigias da colheita renegados que rondam os campos em pousio e repelir os gnolls Pata-de-Rio. Acima de tudo, você tem a tarefa de caçar a esquiva Irmandade Défias, descobrir onde eles estão se escondendo e quebrar seu domínio sobre o que resta das fazendas em dificuldade do Cerro Oeste.",al={"o que devo fazer aqui","o que estou fazendo no cerro oeste","por que estou aqui"}}},fp="8,190,18.391.0,27.355.0,20.380.0,19.294.1,24.254.1,44.264.0,52.230.0,29.199.0,45.227.1,32.204.1,51.187.0"}
P.entries["zone:wetlands"] = {n="Pantanal",s="O Pantanal é um pântano vasto e envolto em névoa, aninhado entre as montanhas de Khaz Modan e as margens da Baía de Baradin. Historicamente castigado por guerras dos anões e invasões órquicas, serve como uma zona de amortecimento rústica entre Altaforja e as terras do norte de Lordaeron. O porto fortificado do Porto de Menethil ergue-se como a principal tábua de salvação da Aliança em uma vastidão empapada dominada por orcs Presa do Dragão, murlocs e gnolls.",h="O Pantanal é um pântano vasto e envolto em névoa, aninhado entre as montanhas de Khaz Modan e as margens da...",kw={"baía de baradin","presa do dragão","dun algaz","dun modr","grim batol","menethil","porto de menethil","ponte thandol","pantanal"},ang={["faction:Alliance"]="O Porto de Menethil serve como a principal porta de entrada em águas profundas da Aliança através do Grande Oceano, ligando os reinos do leste a postos avançados expedicionários em Kalimdor.",["profession:Mining"]="As colinas e profundezas cavernosas da Rocha de Thelgen guardam ricos veios minerais, incluindo depósitos raros de Minério de Incendicita cobiçados por mineradores e engenheiros anões.",["race:Dwarf"]="Para os anões, o Pantanal é um lugar agridoce marcado pela perda de Dun Modr, pela antiga tragédia de Grim Batol e pelo trabalho contínuo de defender a rota comercial do Rei Magni para o norte."},sec={{t="Uma Terra de Água e Ruína",b="Espalhando-se sob o precipício imponente do Dique Lapidado, o Pantanal é uma extensão fria e encharcada, coberta por névoa perpétua e céus cinzentos uniformes. Embora outrora tenha sido o lar de prósperos assentamentos de anões, os pântanos agora estão repletos de ruínas de pedra afundadas, charcos empapados e atoleiros traiçoeiros. Os aventureiros que entram na região precisam navegar por desfiladeiros estreitos, seja vindo para o norte através do desfiladeiro barricado de Dun Algaz, vindo de Loch Modan, ou cruzando os imponentes arcos da Ponte Thandol, a partir do Planalto Arathi."},{t="As Cicatrizes de Grim Batol",b="Os limites orientais do pântano são dominados pela presença sombria de Grim Batol, a antiga fortaleza dos Martelo Selvagem. Após sua profanação durante a Guerra dos Três Martelos, tornou-se o reduto fortificado do clã Presa do Dragão durante a Segunda Guerra. Quando a revoada dragônica vermelha se libertou do cativeiro órquico, sua vingança ardente despedaçou as forças órquicas e devastou as encostas ao redor. Hoje, draconianos vermelhos guardam os Portões Presa do Dragão contra todos os invasores, enquanto remanescentes selvagens do clã Presa do Dragão habitam em acampamentos espalhados pelas colinas, continuando a atormentar os viajantes pelo pântano."},{t="Porto da Costa Oeste",b="Empoleirado na borda da Baía de Baradin, o Porto de Menethil é o coração pulsante do comércio e da logística da Aliança em Khaz Modan. Batizado em homenagem ao Rei Terenas Menethil II, este porto resoluto conecta os Reinos do Leste à distante Kalimdor por meio de navios de transporte regulares que navegam para a Ilha Theramore e, passando pela Costa Sul, para Auberdine. Apesar de sua importância militar estratégica e sólida arquitetura anã, o porto está perpetuamente sob ameaça de murlocs costeiros, criaturas do pântano e saqueadores costeiros que atacam embarcações navegando pelos canais rochosos."},{t="Fronteiras Sitiadas",b="O Pantanal é uma zona de guerra em várias frentes. No extremo norte, anões Ferro Negro sob o comando do bruxo Balgaras, o Asqueroso, sabotaram a Ponte Thandol com explosivos e invadiram Dun Modr, interrompendo as rotas de abastecimento por terra. Enquanto isso, gnolls Pelemusgo assolam os pântanos centrais e ameaçam até guardiões antigos como Rethiel, o Verdião. Entre bandos de orcs renegados, infiltrados Ferro Negro e naufrágios amaldiçoados na costa, manter a região segura exige vigilância constante."}},faq={{q="Como viajo para o Pantanal a pé?",a="Os aventureiros da Aliança geralmente viajam para o norte a partir de Loch Modan através da passagem montanhosa de Dun Algaz. Os viajantes da Horda que vêm do norte podem cruzar a Ponte Thandol a partir do Planalto Arathi. Tome cuidado, pois ambas as passagens são disputadas por forças hostis, como orcs Presa do Dragão e anões Ferro Negro.",al={"como chegar ao pantanal","caminho para o pantanal","correr para o pantanal"}},{q="Para onde vão os barcos no Porto de Menethil?",a="As docas no Porto de Menethil operam duas rotas principais de balsa para Kalimdor: um navio atraca na Costa Sul, no Contraforte de Eira dos Montes, e então navega pelo Grande Oceano até Auberdine, nas margens da Costa Negra, enquanto o outro navega para o sul até a Ilha Theramore, no Pântano Vadeoso.",al={"barcos de menethil","navios do porto de menethil","para onde vai o barco no pantanal"}},{q="O que é Grim Batol e por que é guardado?",a="Grim Batol é uma antiga fortaleza dos anões abandonada após a Guerra dos Três Martelos e mais tarde ocupada pelo clã Presa do Dragão. Após a Segunda Guerra, a revoada dragônica vermelha libertada expulsou os orcs e selou a montanha. Poderosos draconídeos e draconianos vermelhos patrulham os Portões Presa do Dragão para impedir que alguém entre nos salões amaldiçoados.",al={"por que há dragões em grim batol","dragões vermelhos de grim batol","portões presa do dragão"}},{q="O que aconteceu com Dun Modr?",a="Dun Modr era uma fortaleza anã do norte que protegia a Ponte Thandol. Recentemente, foi atacada e tomada por anões Ferro Negro liderados por Balgaras, o Asqueroso. Os sobreviventes, comandados por Rhag Garmason, mantêm um acampamento sitiado nas proximidades enquanto tentam recuperar a cidade.",al={"quem destruiu dun modr","ruínas de dun modr","ferro negro em dun modr"}},{q="Quem é Rethiel, o Verdião?",a="Rethiel é uma antiga besta do pântano que reside na Zona Verde do Pantanal. Ele busca a ajuda de viajantes para conter a investida dos agressivos gnolls Pelemusgo e abater Rastejantes do Pântano doentes para que os pântanos possam se recuperar.",al={"Cinturão Verde","Rethiel no Pantanal","quem é Rethiel, o Verdião"}},{q="De onde vieram todos os orcs no pântano?",a="Os orcs pertencem ao clã Presa do Dragão, que originalmente se fortificou em Grim Batol durante a Segunda Guerra. Depois de serem devastados pela revoada dragônica vermelha libertada, os orcs sobreviventes fugiram para o pântano e para as colinas, onde ainda realizam ataques em estradas e contra viajantes.",al={"por que há orcs no pantanal","presa do dragão pantanal","clã presa do dragão pantanal"}}},fx={["2cd88152"]={q="O que é o Pantanal?",a="O Pantanal é um pântano frio e vasto, aninhado entre as montanhas de Khaz Modan e o mar ocidental. Envolto em névoas cinzentas perpétuas, situa-se imediatamente ao norte de Loch Modan e ao sul do Planalto Arathi. Antigamente lar de inúmeros assentamentos anões, a região foi devastada por guerras passadas e agora é uma região selvagem, bruta e indomada, que divide os reinos anões das Ruínas de Lordaeron.",al={"o que é o pantanal","lore do pantanal","conte-me sobre o pantanal"}},["4984d286"]={q="Por que tudo aqui é pântano?",a="O Pantanal fica em uma bacia baixa, delimitada em três lados por cordilheiras imponentes, captando o escoamento e a drenagem das alturas acima. É alimentado por inúmeros rios, lagos e riachos que descem em direção à Baía de Baradin, mantendo a terra perpetuamente saturada e fria.",al={"por que o pantanal é um pântano","geografia do pantanal","por que tanta água no pantanal"}},["60c5b961"]={q="Quem vive no Pantanal?",a="A principal presença civilizada é a Aliança no Porto de Menethil, ao lado de montanheses anões que lutam para manter postos avançados importantes. No entanto, a região selvagem é dominada por forças hostis: orcs do clã Focodragão renegados escondidos nas colinas orientais, gnolls Pele-de-Musgo rondando os pântanos, murlocs rastejando ao longo da costa e anões Ferro Negro violentos avançando para o sul a partir de Dun Modr.",al={"quem vive aqui","facções do pantanal","habitantes do pantanal"}},["8d21dccb"]={q="O que é o Porto de Menethil e quem o administra?",a="O Porto de Menethil é uma cidade portuária fortemente fortificada, construída em uma ilha na Baía de Baradin, servindo como o principal portal costeiro da Aliança em Khaz Modan. Nomeado em homenagem ao Rei Terenas Menethil II de Lordaeron, é mantido por anões e humanos aliados, protegido pelas paredes de pedra robustas da Bastilha Menethil e guardado pela guarnição do Capitão Punhoforte.",al={"porto de menethil","quem administra menethil","cidade de menethil"}},fd9bb568={q="Por que os anões construíram um porto aqui?",a="Durante a Segunda Guerra, Orgrim Martelo da Perdição construiu um estaleiro aqui para transportar a Horda através da Baía de Baradin para Lordaeron. Depois de expulsar os orcs, a Aliança recuperou o local e o reconstruiu em um porto próspero, estabelecendo rotas de abastecimento marítimo essenciais que ligam Khaz Modan tanto aos aliados humanos quanto a terras distantes do outro lado do mar.",al={"por que o porto de menethil","por que construir um porto no pântano","razão para o porto de menethil"}},["4cff40a7"]={q="O Porto de Menethil é território da Aliança?",a="Sim. O Porto de Menethil é um reduto oficial da Aliança. Embora seja uma cidade portuária agitada e rústica, cheia de marinheiros, mercadores, viajantes e estivadores brutos, ela hasteia a bandeira da Aliança e é defendida pelas forças de Altaforja.",al={"menethil é aliança","facção do porto de menethil","quem é dono do porto de menethil"}},["6dc9c02b"]={q="Quem está no comando por aqui?",a="Não há um governante único sobre a região pantanosa indomada. A autoridade da Aliança está concentrada no Porto de Menethil sob o Capitão Punhoforte e a guarnição dentro da Bastilha Menethil. Fora das muralhas do porto, o pântano é uma fronteira sem lei disputada por patrulhas militares, senhores da guerra orcs e bestas primitivas.",al={"quem lidera o pantanal","comandante do pantanal","quem é o chefe aqui"}},b8a9f96f={q="Quem é o Capitão Punhoforte?",a="O Capitão Punhoforte é o comandante anão encarregado da guarnição no Porto de Menethil. Da segurança do porto, ele coordena as operações defensivas por todo o pântano, encarregando aventureiros capazes de conter os ataques implacáveis dos orcs Focodragão próximos.",al={"capitão punhoforte pantanal","lore de punhoforte","quem é punhoforte"}},["38351a9f"]={q="Quem são os orcs Focodragão e por que estão aqui?",a="Os Focodragão são um clã de orcs brutal que usou a Alma Demoníaca para escravizar Alexstrasza e a revoada dragônica vermelha durante a Segunda Guerra, governando a partir das alturas de Grim Batol. Quando a Rainha dos Dragões foi libertada, os dragões vingativos destruíram o clã, espalhando os sobreviventes pelos pântanos e montanhas do Pantanal, onde permanecem como uma ameaça violenta e persistente.",al={"focodragão pantanal","por que os focodragão estão no pantanal","orcs focodragão"}},ecc875bb={q="Quem são os anões Ferro Negro e por que estão atacando Dun Modr?",a="Os Ferro Negro são um clã de anões traiçoeiros que dominam as sombras e há muito tempo estão exilados de Altaforja. Aproveitando o deslocamento das forças da Aliança para terras distantes, avançaram rumo ao norte, tomando Dun Modr e sabotando a Ponte Thandol para cortar comunicações vitais e recuperar territórios em Khaz Modan.",al={"ferro negro dun modr","por que os ferro negro estão no pantanal","ataque dos ferro negro ao pantanal"}},["0f0d7fa8"]={q="O que é a Ponte Thandol e por que ela é importante?",a="A Ponte Thandol é um par magnífico de enormes pontes de pedra anãs que atravessam o abismo entre o norte de Khaz Modan e o Planalto Arathi. Construída após a Guerra dos Três Martelos para facilitar o comércio e a união com os Martelo Feroz, ela continua sendo a única ligação terrestre entre os reinos do sul e o norte de Lordaeron.",al={"ponte thandol","por que a ponte thandol é importante"}},faff9f74={q="Por que os Ferro Negro querem explodi-la?",a="Ao destruir a Ponte Thandol, os Ferro Negro pretendem isolar completamente Altaforja e Khaz Modan dos aliados da Aliança em Lordaeron. Cortar essa linha vital terrestre impede que reforços marchem para o sul para retomar Dun Modr ou ajudar contra novas incursões dos Ferro Negro.",al={"por que destruir a ponte thandol","trama dos ferro negro na ponte","explodir a ponte thandol"}},eabba297={q="Como vim parar no Pantanal e para onde devo ir depois?",a="A maioria dos viajantes chega marchando para o norte através da passagem montanhosa de Dun Algaz, vindo de Loch Modan, ou fazendo a longa viagem de barco até o Porto de Menethil. A partir daqui, a estrada continua para o norte através da Ponte Thandol até o Planalto Arathi, enquanto os navios que partem dos ancoradouros levam os aventureiros para o oeste, atravessando O Grande Oceano.",al={"para onde ir depois do pantanal","próxima zona do pantanal","caminho do pantanal"}},["75fb0ece"]={q="Esta é a estrada para Altaforja?",a="Sim. Seguir a estrada para o sul, saindo do pântano, leva você diretamente aos túneis estreitos de Dun Algaz. Passar pelas montanhas leva você a Loch Modan, de onde a estrada principal segue para o oeste pelo Desfiladeiro do Portão Norte diretamente para as neves de Dun Morogh e Altaforja.",al={"estrada para altaforja pantanal","como ir para altaforja a partir do pantanal","caminho para altaforja"}},["78aee5e0"]={q="Como vim parar no Pantanal?",a="A maioria dos viajantes da Aliança chega ao Pantanal indo para o norte de Loch Modan, enfrentando os estreitos túneis montanhosos de Dun Algaz para descer até os pântanos enevoados abaixo. Outros chegam de navio de além de O Grande Oceano, navegando até o Porto de Menethil vindo das costas de Kalimdor. Aqueles que se aventuram ao sul do Planalto Arathi devem, em vez disso, navegar pelas perigosas passagens da arruinada Ponte Thandol.",al={"como cheguei aqui","como cheguei ao pantanal","de onde eu vim"}},["87ca94d2"]={q="O que devo fazer no Pantanal?",a="O pântano é uma fronteira sitiada onde a Aliança se mantém em uma posição frágil. Do Porto de Menethil, você é chamado para proteger rotas comerciais essenciais e repelir os orcs Presa de Dragão remanescentes que atacam as terras baixas. Mais a leste e ao norte, os montanhistas anões precisam do seu aço para conter bandos hostis de gnolls, ajudar locais de escavação sitiados e repelir os anões Ferro Negro que ameaçam cortar a Ponte Thandol por completo.",al={"o que devo fazer aqui","por que estou aqui","qual é minha missão no pantanal"}}},fp="8,284,24.340.0,23.473.0,22.380.0,18.430.0,40.227.0,41.185.0,41.317.0,26.225.0,31.198.1,46.224.0"}
P.entries["zone:winterspring"] = {n="Hibérnia",s="Hibérnia é um vasto vale coberto de neve, situado no alto das encostas a nordeste do Monte Hyjal, logo acima das florestas encantadas da Clareira da Lua e da Selva Maleva. Conhecida por seu frio congelante, ruínas ancestrais de Altaneiros e predadores de topo errantes, a região tem como ponto central o posto avançado goblin neutro de Visteterna. O local segue sendo uma terra de perigos naturais ferozes, abrigando resquícios da revoada dragônica azul enquanto enfrenta a corrupção demoníaca ao longo de suas elevações ao sul.",h="Hibérnia é um vasto vale coberto de neve, situado no alto das encostas a nordeste do Monte Hyjal, logo acima...",kw={"dragões azuis","garganta do sussurro sombrio","bruna covaneve","visteterna","sabre-de-gelo","chapéu-de-gelo","kel'theril","mazthoril","presamatos","hibérnia"},ang={["class:Druid"]="Localizada bem acima da Clareira da Lua, Hibérnia guarda grande importância sagrada como o local onde Malfurion Tempesfúria despertou os Druidas da Garra de seu sono ancestral durante a Terceira Guerra.",["faction:Alliance"]="Heróis da Aliança visitam com frequência Ripárion Glaciares na Pedra Sabre-de-gelo, trabalhando sem parar no frio extremo para conquistar a lealdade das prestigiosas montarias de Sabre-de-gelo de Hibérnia.",["profession:Herbalism"]="Hibérnia é o único habitat conhecido do Chapéu-de-gelo, uma erva alpina indispensável e muito visada para poções alquímicas avançadas, junto com pés espalhados de Sálvia-prata-da-montanha e raras flores de Lótus Preto.",["profession:Mining"]="Os penhascos congelados e as paredes de cavernas por todo o vale são ricos em minerais valiosos, frequentemente abrigando Pequenas Veias de Tório e Veias Ricas de Tório, além de raros depósitos de Veraprata.",["race:NightElf"]="Hibérnia está intimamente ligada à história élfica, abrigando os túmulos subterrâneos onde os Druidas da Garra repousaram por milênios, as trágicas Ruínas de Kel'Theril e raízes expostas de Nordrassil danificadas durante a Batalha do Monte Hyjal."},sec={{t="Um Reino de Gelo Perpétuo",b="Erguida milhares de metros acima da natureza ao redor, Hibérnia repousa sob o ar puro da montanha e nevascas implacáveis. Enormes raízes expostas da Árvore do Mundo, Nordrassil, cortam os montes de neve como imponentes arcos de madeira, retorcidas e deformadas durante as lutas decisivas da Terceira Guerra. Embora grande parte do norte de Kalimdor seja dominada por florestas densas e climas quentes, Hibérnia é uma terra tranquila de matas alpinas moderadas, escarpas rochosas e lagos congelados, lar de formidáveis sabres-de-gelo, quimeras, iétis e ursos invernais de pelagem espessa."},{t="Encruzilhadas e Postos Avançados",b="Chegar a este planalto elevado exige atravessar as antigas passagens esculpidas do Domínio dos Presamatos, guardadas por urscabos não corrompidos que examinam de perto quaisquer viajantes vindos da Selva Maleva ou da Clareira da Lua. No centro do vale fica Visteterna, uma próspera cidade comercial operada pelo Cartel Bondebico. Os goblins recebem aventureiros tanto da Aliança quanto da Horda de caixas abertos, atuando como um refúgio indispensável de engenharia, comércio e fogueiras acolhedoras contra o frio cortante da montanha."},{t="Velhos Fantasmas e Dracos Azuis",b="Séculos antes do surgimento dos povoados modernos, elfos ancestrais ergueram a cidade lacustre de Kel'Theril. Depois que feiticeiros Altaneiros imprudentes estilhaçaram o maldito Cristal de Zin-Malor, a loucura os consumiu, deixando fantasmas inquietos a vagar pelos pilares em ruínas e pelas águas congeladas até hoje. Mais ao sul erguem-se as alturas cavernosas de Mazthoril, a tradicional fortaleza da revoada dragônica azul em Kalimdor. Ali, a ninhada do Tecelão de Feitiços Malygos, sob a vigilância da matrona protetora Haleh, guarda as correntes arcanas e contesta ameaças locais."},{t="A Sombra Iminente da Garganta",b="A serenidade de Hibérnia é bruscamente rompida ao longo de sua fronteira mais ao sul, na Garganta do Sussurro Sombrio. Ali, forças demoníacas de elite, legiões remanescentes da Terceira Guerra, rastejam por desfiladeiros irregulares bloqueando os caminhos superiores rumo ao cume do Monte Hyjal. Enquanto isso, os urscabos Quedinverno nativos sucumbiram a corrupções vis, levando pesquisadores independentes como Bruna Covaneve a investigar a mácula que avança antes que toda a vida selvagem do vale seja consumida."}},faq={{q="Como chego a Hibérnia?",a="Os viajantes devem passar pelo Domínio dos Presamatos, uma rede subterrânea de túneis localizada no nordeste da Selva Maleva. Cruzar as cavernas pacificamente exige conquistar a confiança dos urscabos Presamatos nativos, que atacam quaisquer invasores que considerem hostis. Ao passar pela saída leste, as encostas nevadas de Hibérnia surgem imediatamente.",al={"como chegar em hibérnia","como entrar em hibérnia","entrada de hibérnia","túnel dos presamatos hibérnia"}},{q="Quem governa a cidade de Visteterna?",a="Visteterna é administrada pelo Cartel Bondebico, o conglomerado mercantil goblin. Por causa do estrito foco no lucro e da neutralidade dos goblins, tanto viajantes da Horda quanto da Aliança podem utilizar seus mestres de voo, comerciantes de reparo, cofres bancários e mercadorias, desde que os visitantes não quebrem a paz dentro dos limites da cidade.",al={"quem controla visteterna","facção de visteterna","visteterna é neutra"}},{q="O que são os fantasmas que assombram o Lago Kel'Theril?",a="São os espíritos dos Elfos Noturnos Altaneiros que habitaram a antiga cidade de Kel'Theril dez mil anos atrás. Quando seus feiticeiros mexeram no roubado Cristal de Zin-Malor, sua destruição desencadeou uma maldição catastrófica. Expedições posteriores de altos-elfos séculos depois também foram levadas à loucura, fadadas a assombrar as ruínas congeladas ao lado de seus ancestrais.",al={"fantasmas do lago kel'theril","espíritos das ruínas de kel'theril","quem está em kel'theril"}},{q="Por que os urscabos Quedinverno são agressivos?",a="Os urscabos Quedinverno sucumbiram a uma corrupção não natural que se alastrou e levou o clã à hostilidade enlouquecida. Enquanto os Presamatos próximos mantêm com firmeza a sanidade, os Quedinverno caíram sob influências sombrias, motivando pesquisadores como Bruna Covaneve a estudar a mácula e limpar seus acampamentos.",al={"por que os quedinverno são hostis","corrupção da tribo quedinverno","bruna covaneve urscabos"}},{q="O que vive dentro de Mazthoril?",a="Mazthoril é o principal ninho e santuário da revoada dragônica azul em Kalimdor. Nas profundezas de suas agulhas cavernosas, dracônicos, filhotes de elite e dracos ancestrais guardam relíquias dracônicas poderosas e segredos arcanos sob o olhar atento de Haleh, consorte do Aspecto Malygos.",al={"dragões de mazthoril","o que é mazthoril","dragões azuis em hibérnia"}},{q="O que é a Garganta do Sussurro Sombrio?",a="A Garganta do Sussurro Sombrio é um desfiladeiro traiçoeiro nos confins meridionais do vale, ocupado por poderosos demônios de elite remanescentes da Terceira Guerra. O local serve como um perímetro pesadamente vigiado ao longo das trilhas traiçoeiras que levam às alturas do Monte Hyjal.",al={"demônios da garganta do sussurro sombrio","o que há na garganta do sussurro sombrio","portão de hyjal hibérnia"}},{q="É possível treinar ou domar sabres-de-gelo aqui?",a="Na Pedra Sabre-de-gelo, no extremo norte do vale, o Elfo Noturno Ripárion Glaciares cuida dos felinos brancos nativos. Aventureiros que o ajudam a conseguir suprimentos e a proteger o bando podem provar seu valor para aprender os segredos da criação e montaria de um Sabre-de-gelo.",al={"montaria sabre-de-gelo","ripárion glaciares sabre-de-gelo","como obter sabre-de-gelo"}}},fp="12,328,26.408.0,23.361.0,26.385.0,31.374.0,29.250.0,30.220.0,45.324.0,43.293.0,28.244.0,26.191.0,39.225.0"}
P.entries["zone:zephras"] = {n="Ilha de Zefras",s="A Ilha de Zefras é uma ilha voadora suspensa na Muralha Celeste, o Plano Elemental do ar. Ela serve como o lar ancestral inicial dos Skyborne, cuja sociedade agora enfrenta uma crise existencial à medida que a magia que sustenta a ilha se desgasta continuamente. Com o contato cortado com os reinos celestes vizinhos, seus habitantes lutam contra o colapso elemental e a chegada de refugiados.",h="A Ilha de Zefras é uma ilha voadora suspensa na Muralha Celeste, o Plano Elemental do ar.",kw={"aeronaves","anvilas","plano elemental","siroccas","skyborne","muralha celeste","valanaar","windstones","zefras"},ang={["class:Shaman"]="Existindo diretamente dentro do Plano Elemental do ar, a Ilha de Zefras exemplifica o que acontece com terras elementais quando os espíritos que as equilibram desaparecem de repente.",["race:Skyborne"]="A Ilha de Zefras é o seu lar ancestral e ponto de partida, embora sua beleza remanescente mascare uma crise urgente de terreno em colapso e poder elemental minguante."},sec={{t="Um Reino nas Alturas",b="A Ilha de Zefras é uma massa de terra isolada à deriva nos ventos eternos da Muralha Celeste. Por gerações, os Skyborne viveram aqui ao lado de elementais do ar nativos que ajudavam a preservar as correntes mágicas que mantinham a ilha no alto. No entanto, vários séculos atrás, esses guardiões elementais desapareceram por completo. Privados de sua presença e tutela, os encantamentos latentes que sustentavam a terra começaram a falhar lentamente, fazendo com que Zefras se frature e se desestabilize aos poucos."},{t="Horizontes Interrompidos",b="Zefras não era o único santuário habitado pelos Skyborne dentro do Plano Elemental. Ilhas irmãs conhecidas como Anvilas e Siroccas também flutuavam pela Muralha Celeste, mas as comunicações entre elas cessaram após o desaparecimento dos elementais. Recentemente, refugiados dessas massas de terra vizinhas em ruínas conseguiram chegar a Zefras em busca de segurança, trazendo notícias sombrias de que as outras ilhas estão se desintegrando de vez sob seus pés."},{t="Limiar para Azeroth",b="Com sua própria massa de terra em lenta decadência, os Skyborne de Zefras começaram a olhar além das fronteiras da Muralha Celeste, em direção a Azeroth. Dos ancoradouros celestes de Valanaar, aeronaves agora partem para estabelecer raras conexões vitais com o reino mortal. Essas viagens conectam o domínio aéreo diretamente a pontos em Azeroth, incluindo os arredores de Dalaran nas Montanhas de Alterac e o Platô do Vigia dos Céus em Mulgore."}},faq={{q="Onde fica a Ilha de Zefras?",a="A Ilha de Zefras está situada dentro da Muralha Celeste, o Plano Elemental do ar, em vez de na superfície de Azeroth. Ela flutua em meio às nuvens perpétuas e às correntes de vento deste domínio etéreo.",al={"localização da ilha de zefras","onde fica zefras","em qual plano fica zefras"}},{q="Por que a Ilha de Zefras está se desfazendo?",a="A ilha dependia da presença de elementais do ar nativos que outrora coexistiam com os Skyborne. Vários séculos atrás, esses elementais desapareceram, deixando as fundações mágicas que ancoram e preservam a terra voadora enfraquecerem e se degradarem lentamente ao longo do tempo.",al={"por que zefras está colapsando","destruição da ilha de zefras","ilha moribunda"}},{q="O que são Anvilas e Siroccas?",a="São ilhas voadoras vizinhas na Muralha Celeste, também povoadas pelos Skyborne. A Ilha de Zefras perdeu a comunicação com ambas quando os elementais desapareceram, e refugiados em fuga agora relatam que tanto Anvilas quanto Siroccas estão colapsando no esquecimento.",al={"anvilas","siroccas","outras ilhas dos skyborne"}},{q="Como as pessoas viajam entre a Ilha de Zefras e Azeroth?",a="Os Skyborne operam ancoradouros celestes no assentamento de Valanaar. Aeronaves partem dessas docas através da fronteira planar em direção a Azeroth, pousando perto de Dalaran nas Montanhas de Alterac e no Platô do Vigia dos Céus em Mulgore.",al={"como sair de zefras","aeronaves de zefras","viajar para azeroth"}},{q="Quem são os Skyborne?",a="Os Skyborne são os habitantes que vivem na Ilha de Zefras e em seus reinos celestes irmãos. Tendo habitado a Muralha Celeste por gerações, eles agora enfrentam a lenta destruição de sua terra natal voadora à medida que sua magia de sustentação se dissipa.",al={"raça skyborne","quem vive em zefras"}},{q="Quem vive na Ilha de Zefras além dos Skyborne?",a="Além de aldeias pacíficas e refugiados visitantes, a ilha é assolada por bandidos locais, noctigarras que vivem em cavernas e feras que habitam áreas como o Covil dos Guinchotes e a Caverna dos Noctigarra.",al={"habitantes de zefras","inimigos em zefras"}}},fx={["1fd88046"]={q="O que é a Ilha de Zefras?",a="A Ilha de Zefras é uma massa de terra flutuante que paira dentro da Muralha Celeste, o Plano Elemental do Ar. Milênios atrás, elfos noturnos exilados que fugiam da perseguição em Eldre'Thalas negociaram com espíritos do vento nativos, que elevaram a ilha aos céus para mantê-los em segurança. Ela serve como o santuário ancestral de seus descendentes, os Nascidos do Céu.",al={"o que é zefras","sobre a ilha de zefras","informações sobre a ilha de zefras"}},["7ea7c85c"]={q="O que aconteceu na Ilha de Zefras?",a="A Ilha de Zefras foi elevada à Muralha Celeste depois que ancestrais elfos superiores se separaram do reinado sangrento do Príncipe Tortheldrin em Eldre'Thalas. Os Nascidos do Céu viveram em harmonia com elementais do ar por milhares de anos, mas, séculos atrás, esses patronos elementais desapareceram sem explicação. Sem sua magia contínua, os pilares que ancoravam a ilha começaram a se deteriorar, e refugiados de ilhas vizinhas em colapso fugiram para cá enquanto facções internas disputam recursos cada vez menores.",al={"história de zefras","o que aconteceu aqui em zefras","lore de zefras"}},["70a3c6ae"]={q="A Ilha de Zefras é perigosa?",a="Sim. Além da ameaça física iminente da própria ilha se desestabilizar e cair dos céus, o desaparecimento dos protetores elementais deixou a terra caótica. Acampamentos de bandidos, covis de animais hostis e atritos políticos voláteis entre a Alta Ordem, os Moldavento e os Al'Aketh tornam perigosa qualquer viagem fora dos assentamentos fortificados.",al={"zefras é perigoso","ameaças em zefras","perigos em zefras"}},b4875d06={q="Onde fica a ilha em comparação com o resto de Azeroth?",a="A Ilha de Zefras não repousa sobre a superfície de Azeroth; ela deriva dentro da Muralha Celeste, um domínio dimensional separado criado pelos forjados pelos titãs para conter elementais do ar caóticos. As únicas conexões físicas entre a ilha e o mundo mortal abaixo são dirigíveis especializados que atracam em Valanaar e viajam pela fronteira para locais como Dalaran e Mulgore.",al={"onde fica zefras em relação a azeroth","zefras fica em azeroth","localização de zefras comparada a azeroth"}},["2c89f95d"]={q="Quem são os Al'Aketh?",a="Os Al'Aketh são uma das facções rivais que lutam pelo domínio na Ilha de Zefras, ao lado da Alta Ordem e dos Moldavento. À medida que os pilares que ancoram a ilha falham e a sobrevivência se torna desesperadora, os Al'Aketh competem ativamente pela supremacia e pelo controle dos recursos místicos restantes da ilha.",al={"o que são os alaketh","facção al'aketh","quem é alaketh"}},["6e14d755"]={q="Vou sair da ilha eventualmente?",a="Sim. Embora a Ilha de Zefras sirva como seu lar e campo de treinamento inicial, aeronaves partem dos ancoradouros em Valanaar através de fendas planares para o continente de Azeroth, conectando-se diretamente a Dalaran nas Montanhas de Alterac e ao Platô do Vigia dos Céus em Mulgore.",al={"vou sair de zefras","sair da ilha de zefras","podemos ir para azeroth"}},["19470e71"]={q="Como vim parar na Ilha de Zefras?",a="Você nasceu entre os Nascidos do Céu, os shen'dorei que habitam este refúgio flutuante no alto da Muralha Celeste, o Plano Elemental do Ar. Milênios atrás, seus ancestrais fugiram do expurgo do Príncipe Tortheldrin em Eldre'Thalas e fizeram um pacto com espíritos do vento que elevaram este santuário aos céus. Enquanto outras ilhas irmãs, como Anvilas e Siroccas, desmoronam ou desaparecem de alcance, a Ilha de Zefras tem sido seu lar desde o início. Você começa sua jornada aqui, entre seu próprio povo.",al={"como cheguei aqui","como cheguei à ilha de zefras","por que acordei aqui","de onde eu vim"}},["5dae6f41"]={q="O que devo fazer na Ilha de Zefras?",a="Seu lar está desmoronando sob seus pés. Séculos atrás, os elementais do ar benevolentes desapareceram, e os pilares arcanos que unem a Ilha de Zefras estão perdendo seu poder. Refugiados chegam de ilhas externas em colapso enquanto facções rivais, incluindo a Alta Ordem, os Moldavento e os Al'Aketh, discutem sobre o que resta. Você deve ajudar seu povo, conter ameaças internas e feras selvagens, ajudar a estabilizar as magias falhas e, finalmente, procurar uma passagem para Azeroth antes que a ilha caia.",al={"o que devo fazer aqui","qual é meu objetivo aqui","o que estou fazendo na ilha de zefras","por que estou aqui"}}},fp="12,263,13.353.0,16.350.0,20.265.0,30.156.0,34.190.0,30.197.0,54.178.0,21.180.0,47.152.0"}
